'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { PasswordInput } from '@diki-stwn/serupa-ds';
import { PinInput } from '@diki-stwn/serupa-ds';
import { CopyButton } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { RelativeTime } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { TypeToConfirm } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import type { ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import type { SaveState } from '@diki-stwn/serupa-ds';
import { SettingsSection } from './SettingsSection';
import { PageHeader } from './PageHeader';
import { Loader } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';

/* Account security: changing the password, turning two-step verification on and off, and the devices signed in, each
   with Sign out. For an app to copy. What it carries (WCAG 2.2):
   - 3.3.8, 1.3.5: the password fields say what they hold (current-password, new-password), so password managers fill
     and suggest them, and paste works; the rules are shown before typing, not after a failure.
   - 3.3.1: problems are listed in an error summary that takes focus and links to each field.
   - 3.3.8: two-step setup shows the key as text with Copy beside the code box, not only a picture to scan, and the
     code box takes a pasted code and the one the phone offers (autocomplete one-time-code).
   - 3.3.4: recovery codes are shown once, with Copy, before setup ends; turning two-step off asks first.
   - 1.3.1, 2.4.6: each Sign out is named with its device ("Sign out of Firefox on a Windows PC"); the device in use says
     "This device" in words and has no Sign out.
   - 2.4.3, 4.1.3: after a sign-out, focus goes to the next device's Sign out (or the list's heading), and a toast says
     it's done.
   - 4.1.3, 3.3.3: while the devices load, their list is busy with placeholder rows, named once; a failed load says so
     in their place, with Try again (EmptyLoadFailed). The rest of the page works meanwhile.
   - 3.3.4: deleting the account sits apart at the end, offers the data first, says what will be lost, and asks for the
     account's email before its button works; a delete that fails says so in the dialog, which stays open. After it,
     focus goes to the h1 of the page that says it's done.
   Checking passwords and codes, ending sessions and deleting the account are the app's job: the on* props get them. */

export interface SignedInDevice {
  id: string;
  /** "Firefox on a Windows PC". */
  name: string;
  /** "Jakarta, Indonesia". */
  place: string;
  /** When it was last used: a Date, a time in ms, or an ISO string. */
  lastActive: Date | number | string;
  current?: boolean | undefined;
}

export interface AccountSecurityProps {
  /** Two-step verification is on at first. Default: false. */
  twoStep?: boolean | undefined;
  /** The key to add to an authenticator app, shown during setup. Default: a demo key. */
  setupKey?: string | undefined;
  /** The recovery codes shown once setup is done. Default: demo codes. */
  recoveryCodes?: readonly string[] | undefined;
  /** The devices signed in, the one in use first. Default: three demo devices. */
  devices?: readonly SignedInDevice[] | undefined;
  /** Change password was pressed with no problems left. Return its promise: a rejection says it couldn't be saved. */
  onChangePassword?: ((current: string, next: string) => unknown) | undefined;
  /** A 6-digit code was entered during setup. Return its promise: a rejection says the code didn't work. */
  onEnableTwoStep?: ((code: string) => unknown) | undefined;
  /** Turning two-step verification off was confirmed. */
  onDisableTwoStep?: (() => void) | undefined;
  /** Sign out was pressed for one device. */
  onSignOut?: ((id: string) => void) | undefined;
  /** Sign out everywhere else was pressed. */
  onSignOutOthers?: (() => void) | undefined;
  /** The account's email, typed to confirm deleting it. Default: "ana@example.com". */
  email?: string | undefined;
  /** Where "Download your data" leads. Default: "#export". */
  dataHref?: string | undefined;
  /** The email was typed and Delete pressed. Return its promise: a rejection keeps the dialog open and says so. */
  onDeleteAccount?: (() => unknown) | undefined;
  /** The devices are on their way: placeholder rows, named once ("Loading where you’re signed in"). Default: false. */
  loading?: boolean | undefined;
  /** The devices failed to load: a "Couldn’t load where you’re signed in" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the devices again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

const MIN = 12;
const now = Date.now();
const demoDevices: SignedInDevice[] = [
  { id: 'd1', name: 'Chrome on a Mac', place: 'Jakarta, Indonesia', lastActive: now, current: true },
  { id: 'd2', name: 'Safari on an iPhone', place: 'Jakarta, Indonesia', lastActive: now - 3 * 3600_000 },
  { id: 'd3', name: 'Firefox on a Windows PC', place: 'Bandung, Indonesia', lastActive: now - 6 * 86400_000 },
];
const demoCodes = ['4f7k-2m9q', 'x8p3-n6tz', 'h2c5-w7rb', 'q9d4-j3vy', 'm6s8-k2fe', 't3g7-r5xa'];

/** What's wrong with a password change, in the order of its fields. */
export function passwordProblems(current: string, next: string): ErrorSummaryItem[] {
  const found: ErrorSummaryItem[] = [];
  if (!current) found.push({ field: 'password-current', message: 'Enter your current password' });
  if (next.length < MIN) found.push({ field: 'password-new', message: `Make the new password at least ${MIN} characters` });
  else if (next === current) found.push({ field: 'password-new', message: 'Choose a new password, not the one you have now' });
  return found;
}

/** The security page: a skip link, a header with the way back, then main with the h1 and a section per part. */
export function AccountSecurity({ twoStep: on0 = false, setupKey = 'JBSW Y3DP EHPK 3PXP', recoveryCodes = demoCodes, devices = demoDevices,
  onChangePassword, onEnableTwoStep, onDisableTwoStep, onSignOut, onSignOutOthers, email = 'ana@example.com', dataHref = '#export', onDeleteAccount, loading = false, loadFailed = false, onRetry }: AccountSecurityProps) {
  // Password
  const [current, setCurrent] = React.useState('');
  const [next, setNext] = React.useState('');
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>([]);
  const [status, setStatus] = React.useState<SaveState>('idle');
  const [savedAt, setSavedAt] = React.useState<number | undefined>(undefined);
  const err = (f: string) => errors.find((e) => e.field === f)?.message;
  const save = () => {
    const found = passwordProblems(current, next);
    setErrors(found);
    if (found.length) { setStatus('idle'); return; }
    setStatus('saving');
    void Promise.resolve().then(() => onChangePassword?.(current, next)).then(() => {
      setCurrent(''); setNext(''); setSavedAt(Date.now()); setStatus('saved');
    }, () => setStatus('error'));
  };

  // Two-step verification: setting up is a code step, then the recovery codes.
  const [on, setOn] = React.useState(on0);
  const [setup, setSetup] = React.useState<'closed' | 'code' | 'codes'>('closed');
  const [code, setCode] = React.useState('');
  const [codeError, setCodeError] = React.useState<string | null>(null);
  const [checking, setChecking] = React.useState(false);
  const [asking, setAsking] = React.useState(false);
  const twoStepButton = React.useRef<HTMLButtonElement>(null);
  const openSetup = (o: boolean) => {
    if (o) { setCode(''); setCodeError(null); setSetup('code'); return; }
    // Closing after the codes were shown ends setup; closing before it leaves two-step off.
    if (setup === 'codes') toast({ title: 'Two-step verification is on', tone: 'success' });
    setSetup('closed');
  };
  const verify = (e: React.FormEvent) => {
    e.preventDefault();
    if (!/^\d{6}$/.test(code)) { setCodeError('Enter the 6-digit code from your authenticator app.'); return; }
    setChecking(true);
    void Promise.resolve().then(() => onEnableTwoStep?.(code)).then(() => { setOn(true); setSetup('codes'); },
      () => {
        // The old code is no use any more: the boxes clear, ready for the next one.
        setCode('');
        setCodeError('That code didn’t work. Check that your phone’s clock is right, then enter the newest code.');
        requestAnimationFrame(() => document.getElementById('two-step-code')?.focus());
      })
      .finally(() => setChecking(false));
  };
  const turnOff = () => { setOn(false); setAsking(false); onDisableTwoStep?.(); toast({ title: 'Two-step verification is off' }); };

  // Devices
  const [gone, setGone] = React.useState<ReadonlySet<string>>(new Set());
  const devicesHeading = React.useRef<HTMLHeadingElement>(null);
  const shown = devices.filter((d) => !gone.has(d.id));
  const others = shown.filter((d) => !d.current);
  const signOut = (d: SignedInDevice) => {
    const at = others.indexOf(d), after = others[at + 1] ?? others[at - 1];
    setGone((g) => new Set(g).add(d.id));
    onSignOut?.(d.id);
    toast({ title: `Signed out of ${d.name}` });
    requestAnimationFrame(() => (after ? document.getElementById(`sign-out-${after.id}`)?.focus() : devicesHeading.current?.focus()));
  };
  const signOutOthers = () => {
    setGone(new Set(others.map((d) => d.id)));
    onSignOutOthers?.();
    toast({ title: others.length === 1 ? 'Signed out of 1 other device' : `Signed out of ${others.length} other devices` });
    requestAnimationFrame(() => devicesHeading.current?.focus());
  };

  // Deleting the account: a dialog that asks for the email, then a page that says it's done.
  const [deleting, setDeleting] = React.useState(false);
  const [deleteFailed, setDeleteFailed] = React.useState(false);
  const [deleted, setDeleted] = React.useState(false);
  const goneHeading = React.useRef<HTMLHeadingElement>(null);
  React.useEffect(() => { if (deleted) goneHeading.current?.focus(); }, [deleted]);
  const askDelete = (o: boolean) => { setDeleting(o); if (!o) setDeleteFailed(false); };
  // The promise goes back to the button, which shows it's busy while a slow delete runs.
  const deleteAccount = () => {
    setDeleteFailed(false);
    return Promise.resolve().then(() => onDeleteAccount?.()).then(() => { setDeleting(false); setDeleted(true); }, () => setDeleteFailed(true));
  };

  const part = 'grid grid-cols-1 gap-4 border-b border-border py-6 md:grid-cols-3 md:gap-8';
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link href="#settings">Back to settings</Link>
      </header>
      <main id="main" className="mx-auto flex max-w-4xl flex-col px-4 py-8 outline-none">
        {deleted ? (
          <div className="flex flex-col gap-3">
            <Heading level={1} ref={goneHeading} tabIndex={-1} className="outline-none">Your account is deleted</Heading>
            <p className="m-0 text-text-muted">Your projects, files and settings are gone, and you’re signed out everywhere.</p>
            <Link href="#home">Go to the home page</Link>
          </div>
        ) : <>
        <PageHeader title="Security" />

        <SettingsSection title="Password" description={`At least ${MIN} characters. A long phrase is easier to remember than symbols.`}
          onSave={save} errors={errors} status={status} savedAt={savedAt} onRetry={save} saveLabel="Change password">
          <Field label="Current password" id="password-current" error={err('password-current')} required>
            <PasswordInput name="current-password" autoComplete="current-password" value={current} onChange={(e) => setCurrent(e.target.value)} />
          </Field>
          <Field label="New password" id="password-new" hint={`At least ${MIN} characters.`} error={err('password-new')} required>
            <PasswordInput name="new-password" autoComplete="new-password" value={next} onChange={(e) => setNext(e.target.value)} />
          </Field>
        </SettingsSection>

        <section aria-labelledby="two-step" className={part}>
          <div className="flex flex-col gap-1">
            <Heading level={2} size="lg" id="two-step">Two-step verification</Heading>
            <p className="m-0 text-sm text-text-muted">A code from an app on your phone, as well as your password, when you sign in on a new device.</p>
          </div>
          <div className="flex flex-col items-start gap-3 md:col-span-2">
            <p className="m-0">{on ? <><Badge tone="success">On</Badge> With an authenticator app.</> : <><Badge>Off</Badge> Only your password protects this account.</>}</p>
            {on ? <Button ref={twoStepButton} variant="outline" onClick={() => setAsking(true)}>Turn off</Button>
              : <Button ref={twoStepButton} onClick={() => openSetup(true)}>Turn on</Button>}
          </div>
        </section>

        <section aria-labelledby="devices" className={part}>
          <div className="flex flex-col gap-1">
            <Heading level={2} size="lg" id="devices" ref={devicesHeading} tabIndex={-1} className="outline-none">Where you’re signed in</Heading>
            <p className="m-0 text-sm text-text-muted">If you don’t know a device, sign it out and change your password.</p>
          </div>
          <div className="flex min-w-0 flex-col gap-3 md:col-span-2">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load where you’re signed in" onRetry={() => onRetry?.()} headingLevel={3} /> : loading ? (
              // One name for all of them: the first row is named, the others are only pictures.
              <ul role="list" aria-busy="true" className="m-0 flex list-none flex-col divide-y divide-border p-0">
                {[0, 1, 2].map((i) => <li key={i} className="py-3"><Loader variant="skeleton" shape="text" size="sm" lines={2} label={i === 0 ? 'Loading where you’re signed in' : ''} /></li>)}
              </ul>
            ) : <>
            <ul className="m-0 flex list-none flex-col divide-y divide-border p-0">
              {shown.map((d) => (
                <li key={d.id} className="flex flex-wrap items-center gap-3 py-3">
                  <div className="flex min-w-0 flex-1 flex-col">
                    <span className="font-medium">{d.name}{d.current ? <Badge tone="primary" className="ms-2">This device</Badge> : null}</span>
                    <span className="text-sm text-text-muted">{d.place}, {d.current ? 'active now' : <>last active <RelativeTime date={d.lastActive} /></>}</span>
                  </div>
                  {d.current ? null : <Button id={`sign-out-${d.id}`} size="sm" variant="outline" aria-label={`Sign out of ${d.name}`} onClick={() => signOut(d)}>Sign out</Button>}
                </li>
              ))}
            </ul>
            {others.length > 1 ? <Button variant="outline" className="self-start" onClick={signOutOthers}>Sign out everywhere else</Button> : null}
            </>}
          </div>
        </section>

        <section aria-labelledby="delete-account" className={part}>
          <div className="flex flex-col gap-1">
            <Heading level={2} size="lg" id="delete-account">Delete your account</Heading>
            <p className="m-0 text-sm text-text-muted">This can’t be undone.</p>
          </div>
          <div className="flex flex-col items-start gap-3 md:col-span-2">
            <p className="m-0 max-w-prose">Deleting removes your projects, files and settings for good, and signs you out everywhere. Download your data first if you want to keep a copy.</p>
            <div className="flex flex-wrap gap-2">
              <Button href={dataHref} variant="outline">Download your data</Button>
              <Button variant="outline" destructive onClick={() => askDelete(true)}>Delete account</Button>
            </div>
          </div>
        </section>

        <Dialog open={setup !== 'closed'} onOpenChange={openSetup} finalFocus={twoStepButton}
          title={setup === 'codes' ? 'Save your recovery codes' : 'Turn on two-step verification'}
          description={setup === 'codes'
            ? 'If you lose your phone, each of these signs you in once. Keep them somewhere safe: they’re shown only now.'
            : 'Add this key to your authenticator app, by typing or pasting it, then enter the 6-digit code the app shows.'}>
          {setup === 'codes' ? (
            <div className="flex flex-col gap-4">
              <ul aria-label="Recovery codes" className="m-0 grid list-none grid-cols-2 gap-2 p-0 font-mono">
                {recoveryCodes.map((c) => <li key={c}>{c}</li>)}
              </ul>
              <div className="flex flex-wrap gap-2">
                <CopyButton value={recoveryCodes.join('\n')} copiedLabel="Copied">Copy the codes</CopyButton>
                <Button onClick={() => openSetup(false)}>I’ve saved them</Button>
              </div>
            </div>
          ) : (
            <form onSubmit={verify} noValidate className="flex flex-col gap-4">
              <div className="flex flex-wrap items-center gap-2">
                <span className="font-mono" id="setup-key">{setupKey}</span>
                <CopyButton value={setupKey.replace(/\s/g, '')} copiedLabel="Copied" aria-describedby="setup-key">Copy the key</CopyButton>
              </div>
              <Field label="6-digit code" error={codeError ?? undefined}>
                <PinInput id="two-step-code" name="code" length={6} autoComplete="one-time-code" type="numeric" value={code} invalid={!!codeError} onValueChange={(v) => { setCode(v); if (codeError) setCodeError(null); }} />
              </Field>
              <Button type="submit" className="self-start" loading={checking}>Turn on</Button>
            </form>
          )}
        </Dialog>

        <Dialog alert open={asking} onOpenChange={setAsking} title="Turn off two-step verification?"
          description="Then only your password protects this account. You can turn it on again at any time.">
          <div className="flex flex-wrap gap-2">
            <Button variant="outline" onClick={() => setAsking(false)}>Keep it on</Button>
            <Button variant="outline" destructive onClick={turnOff}>Turn off</Button>
          </div>
        </Dialog>

        <Dialog alert open={deleting} onOpenChange={askDelete} title="Delete your account?"
          description="This deletes your projects, files and settings for good. It can’t be undone.">
          <div className="flex flex-col gap-4">
            {deleteFailed ? <Alert tone="danger">Couldn’t delete your account. Try again.</Alert> : null}
            <TypeToConfirm phrase={email} confirmLabel="Delete my account" onConfirm={deleteAccount} />
          </div>
        </Dialog>
        </>}
      </main>
      <Toaster />
    </div>
  );
}

files.ActivityLog.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { SearchInput } from '@diki-stwn/serupa-ds';
import { LoadMore } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell, TableLoadingRows } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed, EmptyNoResults } from './EmptyStates';
import { useLocale } from '@diki-stwn/serupa-ds';

/* Activity log: what people did in a workspace, newest first, with a search, a type filter, more on request, and an
   export. For an app to copy, as the record admins check after something changes. What it carries (WCAG 2.2):
   - 1.3.1: the events are a table with a caption, so each cell is read with its column ("When", "Who", "What").
   - 1.3.1, 1.4.1: each event says what happened in a sentence ("changed Chen Wei's role to Admin"), and its type in
     words beside it, not only by color.
   - 4.1.3: how many events match is a status, so a search or a filter is said politely; Load more says what it added
     and keeps focus on its button.
   - 3.3.3: a search with no matches says so, with a way back to everything; a failed load says so, with Try again.
   - The time is the reader's locale's date and time, with the exact moment in <time dateTime>.
   Fetching and exporting are the app's job: events is what it has, and onExport gets the events that match. */

export type ActivityKind = 'members' | 'billing' | 'security' | 'projects';
export interface ActivityEvent {
  id: string;
  /** When it happened: a time in ms or an ISO string. */
  time: number | string;
  /** Who did it. */
  actor: string;
  /** What they did, as the rest of a sentence after their name: "changed Chen Wei's role to Admin". */
  action: string;
  kind: ActivityKind;
}

export interface ActivityLogProps {
  /** The events, newest first. Default: a demo workspace's. */
  events?: readonly ActivityEvent[] | undefined;
  /** How many show at first, and how many more each Load more adds. Default: 8. */
  pageSize?: number | undefined;
  /** Export was pressed: the events that match the search and filter, newest first. */
  onExport?: ((events: ActivityEvent[]) => void) | undefined;
  /** The events are on their way: a busy table with placeholder rows, named once ("Loading activity"). Default: false. */
  loading?: boolean | undefined;
  /** The events failed to load: a "Couldn’t load the activity log" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

const KINDS: { value: ActivityKind; label: string }[] = [
  { value: 'members', label: 'Members' }, { value: 'billing', label: 'Billing' },
  { value: 'security', label: 'Security' }, { value: 'projects', label: 'Projects' },
];
const kindLabel = (k: ActivityKind) => KINDS.find((x) => x.value === k)!.label;

// Times are hours before 9:00 UTC on 12 November 2026, so the demo reads the same whenever it's drawn.
const at = (hours: number) => Date.UTC(2026, 10, 12, 9) - hours * 3600_000;
const demo: ActivityEvent[] = [
  { id: 'e1', time: at(1), actor: 'Ana Lima', action: 'changed Chen Wei’s role to Admin', kind: 'members' },
  { id: 'e2', time: at(3), actor: 'Budi Santoso', action: 'turned on two-step verification', kind: 'security' },
  { id: 'e3', time: at(5), actor: 'Ana Lima', action: 'invited fay@example.com as a Viewer', kind: 'members' },
  { id: 'e4', time: at(9), actor: 'Chen Wei', action: 'created the project Website redesign', kind: 'projects' },
  { id: 'e5', time: at(26), actor: 'Ana Lima', action: 'changed the plan from Starter to Team', kind: 'billing' },
  { id: 'e6', time: at(30), actor: 'Dewi Lestari', action: 'signed out of Firefox on a Windows PC', kind: 'security' },
  { id: 'e7', time: at(49), actor: 'Budi Santoso', action: 'deleted the project Old landing page', kind: 'projects' },
  { id: 'e8', time: at(52), actor: 'Ana Lima', action: 'removed Eko Prasetyo from the team', kind: 'members' },
  { id: 'e9', time: at(75), actor: 'Ana Lima', action: 'updated the card to Visa ending 4242', kind: 'billing' },
  { id: 'e10', time: at(98), actor: 'Chen Wei', action: 'renamed the project Brand refresh to Website redesign', kind: 'projects' },
  { id: 'e11', time: at(120), actor: 'Dewi Lestari', action: 'changed their password', kind: 'security' },
];

/** The events whose person or action holds every word of the query, and whose type is kind (or any). */
export function matchEvents(events: readonly ActivityEvent[], query: string, kind: ActivityKind | 'all'): ActivityEvent[] {
  const words = query.toLocaleLowerCase().split(/\s+/).filter(Boolean);
  return events.filter((e) => (kind === 'all' || e.kind === kind)
    && words.every((w) => `${e.actor} ${e.action}`.toLocaleLowerCase().includes(w)));
}

/** The activity page: a skip link, a header, then main with the h1, the search and filter, and the events. */
export function ActivityLog({ events = demo, pageSize = 8, onExport, loading = false, loadFailed = false, onRetry }: ActivityLogProps) {
  const locale = useLocale();
  const [query, setQuery] = React.useState('');
  const [kind, setKind] = React.useState<ActivityKind | 'all'>('all');
  const [shownCount, setShownCount] = React.useState(pageSize);
  const found = matchEvents(events, query, kind);
  const rows = found.slice(0, shownCount);
  const filtered = !!query.trim() || kind !== 'all';
  // A new search or filter starts from the first page again.
  const refine = (f: () => void) => { f(); setShownCount(pageSize); };
  const when = (t: number | string) => {
    const d = new Date(t);
    try { return new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeStyle: 'short' }).format(d); } catch { return d.toISOString(); }
  };
  const count = loading ? 'Loading activity' : found.length === 1 ? '1 event' : `${found.length} events`;

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-5xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Activity log" description="What people did in this workspace, newest first. Kept for a year."
          primary={onExport && !loadFailed ? { label: 'Export', onSelect: () => onExport(found) } : undefined} />
        {loadFailed ? <EmptyLoadFailed title="Couldn’t load the activity log" onRetry={() => onRetry?.()} headingLevel={2} /> : <>
          <div className="flex flex-wrap items-end gap-3">
            <Field label="Search the log" className="min-w-0 flex-1 basis-60">
              <SearchInput value={query} onChange={(e) => refine(() => setQuery(e.target.value))} onClear={() => refine(() => setQuery(''))} clearLabel="Clear the search" />
            </Field>
            <Field label="Type" className="w-44">
              <Select value={kind} onChange={(e) => refine(() => setKind(e.target.value as ActivityKind | 'all'))}
                options={[{ value: 'all', label: 'All types' }, ...KINDS]} />
            </Field>
          </div>
          <p role="status" className="m-0 text-sm text-text-muted">{count}</p>

          {loading ? (
            <Table caption="Events" hideCaption loading>
              <TableHead><TableRow><TableHeaderCell>When</TableHeaderCell><TableHeaderCell>Who</TableHeaderCell><TableHeaderCell>What</TableHeaderCell></TableRow></TableHead>
              <TableLoadingRows columns={3} rows={5} label="" />
            </Table>
          ) : !events.length ? (
            <EmptyState icon="history" title="Nothing has happened yet" headingLevel={2} variant="dashed"
              description="When people join, change settings or edit projects, it’s recorded here." />
          ) : !found.length ? (
            <EmptyNoResults query={query.trim() || kindLabel(kind as ActivityKind)} headingLevel={2}
              title={(q) => (query.trim() ? `No events match “${q}”` : `No ${q.toLowerCase()} events`)}
              description="Try other words, or another type." onClearFilters={() => refine(() => { setQuery(''); setKind('all'); })} />
          ) : <>
            <Table caption="Events" hideCaption>
              <TableHead><TableRow><TableHeaderCell>When</TableHeaderCell><TableHeaderCell>Who</TableHeaderCell><TableHeaderCell>What</TableHeaderCell></TableRow></TableHead>
              <TableBody>{rows.map((e) => (
                <TableRow key={e.id}>
                  <TableCell className="whitespace-nowrap"><time dateTime={new Date(e.time).toISOString()}>{when(e.time)}</time></TableCell>
                  <TableCell>{e.actor}</TableCell>
                  <TableCell><span className="me-2">{e.action}</span><Badge>{kindLabel(e.kind)}</Badge></TableCell>
                </TableRow>
              ))}</TableBody>
            </Table>
            <LoadMore onLoadMore={() => setShownCount((n) => n + pageSize)} hasMore={rows.length < found.length}
              count={rows.length} total={found.length} endText={filtered || found.length > pageSize ? 'That’s every event' : null} />
          </>}
        </>}
      </main>
    </div>
  );
}

files.ApiKeys.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { CopyButton } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell, TableLoadingRows } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { useLocale } from '@diki-stwn/serupa-ds';

/* API keys: the keys a workspace's scripts and tools use, making one, and revoking one. For an app to copy. What it
   carries (WCAG 2.2):
   - 1.3.1: the keys are a table with a caption, so each cell is read with its column; each Revoke is named with its
     key ("Revoke Deploy bot"), so a list of them isn't "Revoke, Revoke, Revoke".
   - 1.4.1: what a key may do is in words ("Read only"), not only a color.
   - 3.3.2: the form says what a name is for and what each kind of access allows, before anything is typed.
   - 3.3.1, 3.3.3: a missing or taken name is said next to the field, which gets focus; a create or revoke that fails
     says so in its dialog, which stays open with what was typed.
   - 3.3.4: revoking breaks whatever uses the key at once, so it asks first and says that it can't be undone.
   - A new key is shown once, as text with a Copy button that gets focus, with a plain warning that it won't be shown
     again; the list shows only its last four characters.
   - 2.4.3: after a revoke, focus goes to the next key's Revoke (or the list's heading), never to the top of the page.
   - 4.1.3, 3.3.1: while the keys load, the table is busy with placeholder rows; a failed load says so, with Try again.
   Making and revoking keys is the app's job: onCreate gets the new key's details and returns its secret, and
   onRevoke gets the key to revoke. */

export type ApiKeyAccess = 'read' | 'write';
export interface ApiKey {
  id: string;
  /** What uses it, as the person named it: "Deploy bot". */
  name: string;
  /** The key's last four characters, so people can match it to what they stored. */
  ends: string;
  access: ApiKeyAccess;
  /** When it was made: a time in ms or an ISO string. */
  created: number | string;
  /** When it was last used, or null for never. */
  lastUsed?: number | string | null | undefined;
  /** When it stops working, or null for never. */
  expires?: number | string | null | undefined;
}
export interface ApiKeyDraft {
  name: string;
  access: ApiKeyAccess;
  /** Days until it stops working, or null for never. */
  expiresInDays: number | null;
}

export interface ApiKeysProps {
  /** The workspace's keys, newest first. Default: three demo keys. */
  keys?: readonly ApiKey[] | undefined;
  /** Create key was pressed with a good name. Return the new key's secret (or its promise): a rejection keeps the dialog open and says so. */
  onCreate?: ((draft: ApiKeyDraft) => string | Promise<string>) | undefined;
  /** Revoke key was pressed and confirmed. Return its promise: a rejection keeps the key and says so. */
  onRevoke?: ((id: string) => unknown) | undefined;
  /** The keys are on their way: a busy table with placeholder rows. Default: false. */
  loading?: boolean | undefined;
  /** The keys failed to load: a "Couldn’t load your API keys" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

// Times are days before 9:00 UTC on 12 November 2026, so the demo reads the same whenever it's drawn.
const day = (n: number) => Date.UTC(2026, 10, 12, 9) - n * 86400_000;
const demo: ApiKey[] = [
  { id: 'k1', name: 'Deploy bot', ends: '7Qx2', access: 'write', created: day(40), lastUsed: day(0), expires: day(-325) },
  { id: 'k2', name: 'Analytics export', ends: 'm4Ld', access: 'read', created: day(120), lastUsed: day(6), expires: null },
  { id: 'k3', name: 'Old staging test', ends: 'Pz09', access: 'read', created: day(300), lastUsed: null, expires: day(-10) },
];
const demoSecret = 'acme_demo_key_shown_once_8Kd7Ba3L';

const ACCESS: { value: ApiKeyAccess; label: string; hint: string }[] = [
  { value: 'read', label: 'Read only', hint: 'Can look at projects and data, not change them.' },
  { value: 'write', label: 'Read and write', hint: 'Can also change and delete projects and data.' },
];
const EXPIRY = [{ value: '30', label: 'In 30 days' }, { value: '90', label: 'In 90 days' }, { value: '365', label: 'In a year' }, { value: 'never', label: 'Never' }];

/** What's wrong with a new key's name, in words, or null when it's good. Names are compared without case. */
export function keyNameProblem(name: string, taken: readonly string[]): string | null {
  const n = name.trim();
  if (!n) return 'Name the key, so you know what uses it.';
  if (taken.some((t) => t.toLocaleLowerCase() === n.toLocaleLowerCase())) return `A key is already called “${n}”. Choose another name.`;
  return null;
}

/** The API keys page: a skip link, a header, then main with the h1 and Create key, and the keys. */
export function ApiKeys({ keys = demo, onCreate, onRevoke, loading = false, loadFailed = false, onRetry }: ApiKeysProps) {
  const locale = useLocale();
  const [made, setMade] = React.useState<ApiKey[]>([]);
  const [gone, setGone] = React.useState<ReadonlySet<string>>(new Set());
  const shown = [...made, ...keys].filter((k) => !gone.has(k.id));
  const listHeading = React.useRef<HTMLHeadingElement>(null);
  const afterRevoke = React.useRef<HTMLElement | null>(null);

  // Creating: the form, then the new key's secret, shown once.
  const [creating, setCreating] = React.useState(false);
  const [draft, setDraft] = React.useState<{ name: string; access: ApiKeyAccess; expiry: string }>({ name: '', access: 'read', expiry: '90' });
  const [nameProblem, setNameProblem] = React.useState<string | null>(null);
  const [createFailed, setCreateFailed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [secret, setSecret] = React.useState<string | null>(null);
  const openCreate = (o: boolean) => {
    setCreating(o);
    if (!o) { setSecret(null); setNameProblem(null); setCreateFailed(false); setDraft({ name: '', access: 'read', expiry: '90' }); }
  };
  const create = (e: React.FormEvent) => {
    e.preventDefault();
    const found = keyNameProblem(draft.name, shown.map((k) => k.name));
    setNameProblem(found);
    setCreateFailed(false);
    if (found) { document.getElementById('key-name')?.focus(); return; }
    const d: ApiKeyDraft = { name: draft.name.trim(), access: draft.access, expiresInDays: draft.expiry === 'never' ? null : Number(draft.expiry) };
    setBusy(true);
    void Promise.resolve().then(() => (onCreate ? onCreate(d) : demoSecret)).then((s) => {
      const now = Date.now();
      setMade((m) => [{ id: `new-${now}`, name: d.name, ends: s.slice(-4), access: d.access, created: now, lastUsed: null,
        expires: d.expiresInDays === null ? null : now + d.expiresInDays * 86400_000 }, ...m]);
      setSecret(s);
      // The form's button is gone: Copy, the one thing to do now, takes focus.
      requestAnimationFrame(() => document.getElementById('key-copy')?.focus());
    }, () => setCreateFailed(true)).finally(() => setBusy(false));
  };

  // Revoking: asks first, since whatever uses the key stops working at once.
  const [revoking, setRevoking] = React.useState<ApiKey | null>(null);
  const [revokeFailed, setRevokeFailed] = React.useState(false);
  const [revokeBusy, setRevokeBusy] = React.useState(false);
  const askRevoke = (k: ApiKey | null) => { setRevoking(k); setRevokeFailed(false); };
  const revoke = () => {
    const k = revoking;
    if (!k) return;
    setRevokeBusy(true);
    setRevokeFailed(false);
    void Promise.resolve().then(() => onRevoke?.(k.id)).then(() => {
      const at = shown.indexOf(k), next = shown[at + 1] ?? shown[at - 1];
      afterRevoke.current = next ? document.getElementById(`revoke-${next.id}`) : listHeading.current;
      setGone((g) => new Set(g).add(k.id));
      setRevoking(null);
      toast({ title: `Revoked ${k.name}`, tone: 'success' });
    }, () => setRevokeFailed(true)).finally(() => setRevokeBusy(false));
  };

  const date = (t: number | string) => {
    const d = new Date(t);
    let text: string;
    try { text = new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }).format(d); } catch { text = d.toISOString().slice(0, 10); }
    return <time dateTime={d.toISOString()}>{text}</time>;
  };
  const accessLabel = (a: ApiKeyAccess) => ACCESS.find((x) => x.value === a)!.label;
  const head = (
    <TableHead><TableRow>
      <TableHeaderCell>Name</TableHeaderCell><TableHeaderCell>Key</TableHeaderCell><TableHeaderCell>Access</TableHeaderCell>
      <TableHeaderCell>Created</TableHeaderCell><TableHeaderCell>Last used</TableHeaderCell><TableHeaderCell>Expires</TableHeaderCell>
      <TableHeaderCell><span className="sr-only">Actions</span></TableHeaderCell>
    </TableRow></TableHead>
  );

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-5xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="API keys" description="Keys let your scripts and tools use this workspace. Keep each one secret, like a password."
          primary={loadFailed ? undefined : { label: 'Create key', onSelect: () => openCreate(true) }} />

        {loadFailed ? <EmptyLoadFailed title="Couldn’t load your API keys" onRetry={() => onRetry?.()} headingLevel={2} /> : (
          <Card className="flex flex-col gap-3">
            <Heading level={2} size="lg" ref={listHeading} tabIndex={-1} className="outline-none">
              {loading ? 'Keys' : `Keys (${shown.length})`}
            </Heading>
            {loading ? (
              <Table caption="API keys" hideCaption loading>{head}<TableLoadingRows columns={7} rows={3} label="Loading API keys" /></Table>
            ) : !shown.length ? (
              <EmptyState icon="key" title="No API keys yet" headingLevel={3}
                description="Create a key when a script or tool needs to use this workspace." />
            ) : (
              <Table caption="API keys" hideCaption>
                {head}
                <TableBody>{shown.map((k) => (
                  <TableRow key={k.id}>
                    <TableCell className="font-medium">{k.name}</TableCell>
                    <TableCell className="whitespace-nowrap font-mono">…{k.ends}</TableCell>
                    <TableCell><Badge>{accessLabel(k.access)}</Badge></TableCell>
                    <TableCell className="whitespace-nowrap">{date(k.created)}</TableCell>
                    <TableCell className="whitespace-nowrap">{k.lastUsed == null ? 'Never' : date(k.lastUsed)}</TableCell>
                    <TableCell className="whitespace-nowrap">{k.expires == null ? 'Never' : date(k.expires)}</TableCell>
                    <TableCell>
                      <Button id={`revoke-${k.id}`} size="sm" variant="ghost" destructive aria-label={`Revoke ${k.name}`} onClick={() => askRevoke(k)}>Revoke</Button>
                    </TableCell>
                  </TableRow>
                ))}</TableBody>
              </Table>
            )}
          </Card>
        )}

        <Dialog open={creating} onOpenChange={openCreate}
          title={secret ? 'Copy your new key' : 'Create an API key'}
          description={secret
            ? 'This is the only time it’s shown. Store it where your script reads its secrets, or in a password manager.'
            : 'Give it only the access it needs. You can revoke it at any time.'}>
          {secret ? (
            <div className="flex flex-col gap-4">
              <code id="key-secret" className="rounded-md border border-border bg-surface-muted p-3 font-mono text-sm break-all">{secret}</code>
              <div className="flex flex-wrap gap-2">
                <CopyButton id="key-copy" value={secret} copiedLabel="Copied" aria-describedby="key-secret">Copy the key</CopyButton>
                <Button variant="outline" onClick={() => openCreate(false)}>Done</Button>
              </div>
            </div>
          ) : (
            <form onSubmit={create} noValidate className="flex flex-col gap-4">
              {createFailed ? <Alert tone="danger">Couldn’t create the key. Try again.</Alert> : null}
              <Field label="Name" id="key-name" hint="What uses it, like “Deploy bot”." error={nameProblem ?? undefined} required>
                <Input value={draft.name} autoComplete="off" onChange={(e) => { setDraft({ ...draft, name: e.target.value }); if (nameProblem) setNameProblem(null); }} />
              </Field>
              <Field label="Access" group>
                <RadioGroup name="key-access" value={draft.access} onValueChange={(v) => setDraft({ ...draft, access: v })}>
                  {ACCESS.map((a) => <Radio key={a.value} value={a.value} description={a.hint}>{a.label}</Radio>)}
                </RadioGroup>
              </Field>
              <Field label="Stops working" id="key-expiry" hint="A key that ends limits the harm if it leaks.">
                <Select value={draft.expiry} options={EXPIRY} onChange={(e) => setDraft({ ...draft, expiry: e.target.value })} />
              </Field>
              <Button type="submit" className="self-start" loading={busy}>Create key</Button>
            </form>
          )}
        </Dialog>

        <Dialog alert open={!!revoking} onOpenChange={(o) => { if (!o) askRevoke(null); }} finalFocus={afterRevoke}
          title={revoking ? `Revoke ${revoking.name}?` : 'Revoke this key?'}
          description="Anything using this key stops working at once. You can’t undo this, but you can create a new key.">
          <div className="flex flex-col gap-4">
            {revokeFailed ? <Alert tone="danger">Couldn’t revoke the key. It still works. Try again.</Alert> : null}
            <div className="flex flex-wrap gap-2">
              <Button variant="outline" onClick={() => askRevoke(null)}>Keep it</Button>
              <Button variant="outline" destructive loading={revokeBusy} onClick={revoke}>Revoke key</Button>
            </div>
          </div>
        </Dialog>
      </main>
      <Toaster />
    </div>
  );
}

files.Billing.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Meter } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { useLocale } from '@diki-stwn/serupa-ds';

/* Billing: the plan with what it costs and when it renews, how much of it is used, how it's paid (a card, a direct
   debit or an e-wallet), past invoices, and cancelling. For an app to copy. What it carries (WCAG 2.2, and the Ethical design rules):
   - The plan says what it costs and the day it renews, in the reader's locale, before anyone looks for it.
   - Cancelling takes no more steps than signing up: one button, then a dialog that says what changes and when, with
     Keep my plan and Cancel plan side by side, the same size. Nothing is deleted, and a cancelled plan can be resumed.
   - 1.4.1: usage says how much in words ("4 of 10 seats"), and "almost full" in words too, not only in color.
   - 1.3.1: invoices are a table with a caption; each Download link names its invoice ("Download the invoice of
     1 October 2026").
   - 3.3.1: a card that runs out before the next payment says so, in words as well as a badge, and so does a plan
     with no way to pay yet, each with the way to fix it.
   - 3.3.1, 4.1.3: a failed payment says so at the top, with the way to fix it; a cancel that fails says so in the
     dialog, which stays open; cancelling and resuming are said in a toast.
   - 4.1.3: while billing loads, main is busy with one placeholder name ("Loading billing"); a failed load says so,
     with Try again.
   Taking payments and storing the plan are the app's job: onCancel and onResume get the choices. */

export interface BillingPlan {
  name: string;
  /** The price per interval, in the currency's main unit (24 for $24). */
  price: number;
  currency: string;
  interval: 'month' | 'year';
  /** The next renewal, or the last day when cancelled: "2026-12-01". */
  renews: string;
  /** Cancelled: it stays active until `renews`, then stops. */
  cancelled?: boolean | undefined;
}
export interface BillingUsage { seats: { used: number; limit: number }; storageGb: { used: number; limit: number } }
export interface BillingCard { brand: string; last4: string; expires: string }
/** How the plan is paid: a card, a direct debit from a bank account, or an e-wallet. */
export type BillingPaymentMethod =
  | ({ kind: 'card' } & BillingCard)
  | { kind: 'bank'; bank: string; last4: string }
  | { kind: 'ewallet'; provider: string; phoneLast4: string };
export interface BillingInvoice { id: string; date: string; amount: number; status: 'paid' | 'due' | 'failed'; href: string }

export interface BillingProps {
  /** The plan. Default: a demo Team plan. */
  plan?: BillingPlan | undefined;
  /** How much of the plan is used. Default: demo numbers. */
  usage?: BillingUsage | undefined;
  /** The card it's paid with. Pass `paymentMethod` instead for a bank account or an e-wallet. */
  card?: BillingCard | undefined;
  /** How it's paid: a card, a direct debit or an e-wallet; null when nothing is on file yet. Wins over `card`. */
  paymentMethod?: BillingPaymentMethod | null | undefined;
  /** Past invoices, newest first. */
  invoices?: readonly BillingInvoice[] | undefined;
  /** Cancel plan was confirmed. Return its promise: a rejection keeps the dialog open and says so. */
  onCancel?: (() => unknown) | undefined;
  /** Resume plan was pressed on a cancelled plan. */
  onResume?: (() => void) | undefined;
  /** Where Change plan leads. Default: "#plans". */
  changePlanHref?: string | undefined;
  /** Where Update card (or Change payment method, or Add payment method) leads. Default: "#card". */
  updateCardHref?: string | undefined;
  /** Billing is on its way: placeholder parts, named once ("Loading billing"). Default: false. */
  loading?: boolean | undefined;
  /** Billing failed to load: a "Couldn’t load billing" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

const demoPlan: BillingPlan = { name: 'Team', price: 24, currency: 'USD', interval: 'month', renews: '2026-12-01' };
const demoUsage: BillingUsage = { seats: { used: 4, limit: 10 }, storageGb: { used: 8.6, limit: 10 } };
const demoCard: BillingCard = { brand: 'Visa', last4: '4242', expires: '2028-04' };
const demoInvoices: BillingInvoice[] = [
  { id: 'in3', date: '2026-11-01', amount: 24, status: 'paid', href: '#invoice-in3' },
  { id: 'in2', date: '2026-10-01', amount: 24, status: 'paid', href: '#invoice-in2' },
  { id: 'in1', date: '2026-09-01', amount: 24, status: 'paid', href: '#invoice-in1' },
];

// "1 December 2026" in the reader's locale for "2026-12-01", read as that calendar day wherever the reader is; a
// month ("2028-04") as "April 2028"; anything else as it came.
export function billingDate(iso: string, locale: string): string {
  const m = /^(\d{4})-(\d{2})(?:-(\d{2}))?$/.exec(iso);
  if (!m) return iso;
  const at = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3] ?? 1));
  try { return new Intl.DateTimeFormat(locale, m[3] ? { dateStyle: 'long' } : { month: 'long', year: 'numeric' }).format(at); } catch { return iso; }
}

/** An amount in the reader's locale: "$24.00". */
export function money(amount: number, currency: string, locale: string): string {
  try { return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(amount); } catch { return `${amount} ${currency}`; }
}

/** The method in words: "Visa ending 4242", "Direct debit from BCA, account ending 7781", "GoPay, phone ending 4410". */
export function methodText(m: BillingPaymentMethod): string {
  return m.kind === 'card' ? `${m.brand} ending ${m.last4}`
    : m.kind === 'bank' ? `Direct debit from ${m.bank}, account ending ${m.last4}` : `${m.provider}, phone ending ${m.phoneLast4}`;
}

const STATUS = { paid: ['Paid', 'success'], due: ['Due', 'warning'], failed: ['Payment failed', 'danger'] } as const;

/** The billing page: a skip link, a header, then main with the h1, the plan, usage, the card and the invoices. */
export function Billing({ plan = demoPlan, usage = demoUsage, card = demoCard, paymentMethod, invoices = demoInvoices, onCancel, onResume,
  changePlanHref = '#plans', updateCardHref = '#card', loading = false, loadFailed = false, onRetry }: BillingProps) {
  const locale = useLocale();
  const [cancelled, setCancelled] = React.useState(!!plan.cancelled);
  const [asking, setAsking] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const date = (iso: string) => billingDate(iso, locale);
  const price = money(plan.price, plan.currency, locale);
  const unpaid = invoices.find((i) => i.status === 'failed');
  const method = paymentMethod === undefined ? { kind: 'card' as const, ...card } : paymentMethod;
  // The way to fix the method names what it is: a card is updated, anything else is changed, and nothing is added.
  const fix = !method ? 'Add payment method' : method.kind === 'card' ? 'Update card' : 'Change payment method';
  // A card that runs out before the next payment ("2026-11" before a renewal on "2026-12-01") fails on that day.
  const runsOut = !cancelled && method?.kind === 'card' && method.expires < plan.renews.slice(0, 7);

  const ask = (open: boolean) => { setAsking(open); if (!open) setFailed(false); };
  // A cancel that fails, by rejecting or by throwing, keeps the dialog open and says so. The promise goes back to
  // the button, which shows it's busy while it runs.
  const cancel = () => {
    setFailed(false);
    return Promise.resolve().then(() => onCancel?.()).then(() => {
      setCancelled(true);
      setAsking(false);
      toast({ title: `Cancelled. ${plan.name} stays active until ${date(plan.renews)}.` });
    }, () => setFailed(true));
  };
  const [busy, setBusy] = React.useState(false);
  const confirm = () => { setBusy(true); void cancel().finally(() => setBusy(false)); };
  const resume = () => { setCancelled(false); onResume?.(); toast({ title: `Resumed. ${plan.name} renews on ${date(plan.renews)}.`, tone: 'success' }); };

  const full = (used: number, limit: number) => (used >= limit * 0.8 ? ', almost full' : '');

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" aria-busy={loading && !loadFailed ? true : undefined} className="mx-auto flex max-w-4xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Billing" description="Your plan, what it costs, and what you’ve paid." />
        {loadFailed ? <EmptyLoadFailed title="Couldn’t load billing" onRetry={() => onRetry?.()} headingLevel={2} /> : loading ? (
          ['Plan', 'Usage', 'Invoices'].map((t, i) => (
            <section key={t} aria-labelledby={`billing-loading-${i}`} className="flex flex-col gap-3">
              <Heading level={2} size="lg" id={`billing-loading-${i}`}>{t}</Heading>
              <Card><Loader variant="skeleton" shape="text" lines={3} label={i === 0 ? 'Loading billing' : ''} /></Card>
            </section>
          ))
        ) : <>
          {unpaid ? (
            <Alert tone="danger" title={`The payment on ${date(unpaid.date)} failed`}
              actions={<Link href={updateCardHref}>{fix}</Link>}>
              {method?.kind === 'card' ? 'Update your card' : method ? 'Change your payment method' : 'Add a payment method'} to keep {plan.name}. We’ll try the payment again when you do.
            </Alert>
          ) : null}

          <section aria-labelledby="billing-plan" className="flex flex-col gap-3">
            <Heading level={2} size="lg" id="billing-plan">Plan</Heading>
            <Card className="flex flex-row flex-wrap items-start justify-between gap-4">
              <div className="flex flex-col gap-1">
                <p className="m-0 text-lg font-semibold">{plan.name}{cancelled ? <Badge tone="warning" className="ms-2">Cancelled</Badge> : null}</p>
                <p className="m-0">{price} a {plan.interval}</p>
                <p className="m-0 text-text-muted">
                  {cancelled ? `Active until ${date(plan.renews)}, then it stops. Nothing is deleted.` : `Renews on ${date(plan.renews)} for ${price}.`}
                </p>
              </div>
              <div className="flex flex-wrap gap-2">
                {cancelled ? <Button onClick={resume}>Resume plan</Button> : <>
                  <Button href={changePlanHref} variant="outline">Change plan</Button>
                  <Button variant="ghost" onClick={() => ask(true)}>Cancel plan</Button>
                </>}
              </div>
            </Card>
          </section>

          <section aria-labelledby="billing-usage" className="flex flex-col gap-3">
            <Heading level={2} size="lg" id="billing-usage">Usage</Heading>
            <Card className="flex flex-col gap-5">
              <Meter label="Seats" showValue value={usage.seats.used} max={usage.seats.limit} high={usage.seats.limit * 0.8} optimum={0}
                formatValue={(v, _, max) => `${v} of ${max} seats${full(v, max)}`} />
              <Meter label="Storage" showValue value={usage.storageGb.used} max={usage.storageGb.limit} high={usage.storageGb.limit * 0.8} optimum={0}
                formatValue={(v, _, max) => `${v} GB of ${max} GB${full(v, max)}`} />
            </Card>
          </section>

          <section aria-labelledby="billing-card" className="flex flex-col gap-3">
            <Heading level={2} size="lg" id="billing-card">Payment method</Heading>
            <Card className="flex flex-row flex-wrap items-center justify-between gap-3">
              <div className="flex flex-col gap-1">
                {method ? <p className="m-0">
                  {methodText(method)}{method.kind === 'card' ? `, expires ${date(method.expires)}` : ''}
                  {runsOut ? <Badge tone="warning" className="ms-2">Expires soon</Badge> : null}
                </p> : <p className="m-0">No payment method yet.</p>}
                {runsOut ? <p className="m-0 text-text-muted">It runs out before the next payment on {date(plan.renews)}. Update it to keep {plan.name}.</p>
                  : !method && !cancelled ? <p className="m-0 text-text-muted">Add one before {date(plan.renews)} to keep {plan.name}.</p> : null}
              </div>
              <Link href={updateCardHref}>{fix}</Link>
            </Card>
          </section>

          <section aria-labelledby="billing-invoices" className="flex flex-col gap-3">
            <Heading level={2} size="lg" id="billing-invoices">Invoices</Heading>
            {invoices.length ? (
              <Table caption="Invoices" hideCaption>
                <TableHead><TableRow>
                  <TableHeaderCell>Date</TableHeaderCell><TableHeaderCell>Amount</TableHeaderCell>
                  <TableHeaderCell>Status</TableHeaderCell><TableHeaderCell><span className="sr-only">Download</span></TableHeaderCell>
                </TableRow></TableHead>
                <TableBody>{invoices.map((i) => (
                  <TableRow key={i.id}>
                    <TableCell><time dateTime={i.date}>{date(i.date)}</time></TableCell>
                    <TableCell>{money(i.amount, plan.currency, locale)}</TableCell>
                    <TableCell><Badge tone={STATUS[i.status][1]}>{STATUS[i.status][0]}</Badge></TableCell>
                    <TableCell><Link href={i.href} aria-label={`Download the invoice of ${date(i.date)}`}>Download</Link></TableCell>
                  </TableRow>
                ))}</TableBody>
              </Table>
            ) : <p className="m-0 text-text-muted">No invoices yet. The first comes on {date(plan.renews)}.</p>}
          </section>
        </>}

        <Dialog alert open={asking} onOpenChange={ask} title={`Cancel ${plan.name}?`}
          description={`${plan.name} stays active until ${date(plan.renews)}, and you won’t be charged again. After that, the workspace moves to the Free plan. Nothing is deleted, and you can resume any time before then.`}>
          <div className="flex flex-col gap-4">
            {failed ? <Alert tone="danger">Couldn’t cancel {plan.name}. Try again.</Alert> : null}
            <div className="flex flex-wrap gap-2">
              <Button variant="outline" onClick={() => ask(false)}>Keep my plan</Button>
              <Button variant="outline" destructive loading={busy} onClick={confirm}>Cancel plan</Button>
            </div>
          </div>
        </Dialog>
      </main>
      <Toaster />
    </div>
  );
}

