'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Badge, type BadgeTone } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { Meter } from '@diki-stwn/serupa-ds';
import { Progress } from '@diki-stwn/serupa-ds';
import { Table, TableBody, TableCell, TableHead, TableHeaderCell, TableRow } from '@diki-stwn/serupa-ds';
import { StatsRow, type Stat } from './StatsRow';
import { ActivityFeed, type ActivityEvent } from './ActivityFeed';
import { EmptyFirstRun, EmptyLoadFailed } from './EmptyStates';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';

/* Dashboard: the page an account lands on. Key numbers, how much of the plan is used, the latest projects and what
   the team did, with skeletons while it loads and a first-run state before there's anything to show. For an app to
   copy. What it carries (WCAG 2.2):
   - 1.3.1: each part is a region named by its h2 (the numbers, Usage, Recent projects, Activity), so a screen reader
     can list them and jump to one. The numbers and the projects are a list and a table, not boxes of text.
   - 1.4.1: a change says "Up 12%" or "Down 3%" in words with its arrow (StatsRow); the storage meter says "almost
     full" in words when it turns amber, not by color alone.
   - 4.1.3: while the page loads, main says it's busy (aria-busy) and each part has one named skeleton, so a screen
     reader hears "Loading" once per part, not once per grey bar. Nothing moves focus when the data arrives.
   - 2.4.4: "All projects" and each project's name are links that say where they go.
   - 1.4.10: the parts stack in one column on a phone; the table scrolls inside its own box rather than the page.
   - First run: with no projects yet, the page says so and offers the one button that starts one, instead of a row of
     zeros and empty boxes.
   Fetching the numbers, and what each one counts, is the app's job: pass them as `data`, or `loading` until then. */

export interface RecentProject {
  name: string; href: string; status: string; updated: string;
  /** The status badge's color: 'success' for running work, 'warning' for paused, 'neutral' (default) for the rest. Say the status in words too. */
  statusTone?: BadgeTone | undefined;
}
export interface DashboardData {
  /** The key numbers, two to four (StatsRow). */
  stats: readonly Stat[];
  /** Storage used and the plan's limit, in GB. */
  storage: { used: number; limit: number };
  /** A goal for the period: "Launch checklist", 3 of 5 done. */
  goal: { label: string; done: number; total: number };
  /** The latest projects, newest first: five is plenty. */
  projects: readonly RecentProject[];
  /** What the team did, newest first. */
  activity: readonly ActivityEvent[];
}

export interface DashboardProps {
  /** What the page shows. Default: a demo account. */
  data?: DashboardData | undefined;
  /** Shows skeletons in place of each part until the data arrives. */
  loading?: boolean | undefined;
  /** The numbers failed to load: a "Couldn’t load" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** The person's name, for the greeting. */
  name?: string | undefined;
  /** "New project" was pressed: in the header, or the first-run state. */
  onCreateProject?: (() => void) | undefined;
  /** Loads more activity. Return its promise, so the button shows it's busy. Without it, the demo pages through `data`. */
  onLoadMoreActivity?: (() => PromiseLike<unknown>) | undefined;
  /** With `onLoadMoreActivity`: false after the last page. */
  hasMoreActivity?: boolean | undefined;
}

const day = (n: number) => new Date(Date.UTC(2026, 10, 6, 9) - n * 3600_000 * 5).toISOString();
const PEOPLE = ['Ana Lima', 'Budi Santoso', 'Chen Wei', 'Dewi Lestari'];
const demo: DashboardData = {
  stats: [
    { label: 'Active projects', value: '12', change: { amount: '2', direction: 'up' } },
    { label: 'Tasks done', value: '148', change: { amount: '12%', direction: 'up' }, trend: [96, 110, 104, 121, 132, 148] },
    { label: 'Open issues', value: '23', change: { amount: '3%', direction: 'down', good: true } },
    { label: 'Spend', value: '$3,240', change: { amount: '8%', direction: 'up', good: false } },
  ],
  storage: { used: 8.6, limit: 10 },
  goal: { label: 'Launch checklist', done: 3, total: 5 },
  projects: [
    { name: 'Website redesign', href: '#website-redesign', status: 'Active', updated: '2026-11-06', statusTone: 'success' },
    { name: 'Billing migration', href: '#billing-migration', status: 'Active', updated: '2026-11-05', statusTone: 'success' },
    { name: 'Help center', href: '#help-center', status: 'Paused', updated: '2026-11-03', statusTone: 'warning' },
    { name: 'Mobile app', href: '#mobile-app', status: 'Active', updated: '2026-11-02', statusTone: 'success' },
    { name: 'Data export', href: '#data-export', status: 'Done', updated: '2026-10-30' },
  ],
  activity: ([
    ['commented on', 'Website redesign'], ['closed', 'Issue 214'], ['created', 'Billing migration'], ['uploaded 3 files to', 'Help center'],
    ['invited Dewi Lestari to', 'Mobile app'], ['moved to Done', 'Data export'], ['commented on', 'Billing migration'], ['reopened', 'Issue 198'],
    ['renamed', 'Help center'], ['archived', 'Old brand kit'],
  ] satisfies Array<[string, string]>).map(([action, target], i) => ({
    id: `e${i}`, actor: { name: PEOPLE[i % 4] ?? '' }, action, target: { label: target, href: `#${target.toLowerCase().replace(/\s+/g, '-')}` }, date: day(i),
  })),
};

// "6 Nov 2026" in the reader's locale for "2026-11-06", read as that calendar day wherever the reader is; anything
// else as it came. The <time> keeps the ISO day in dateTime.
function shortDay(iso: string, locale: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return iso;
  try { return new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }).format(new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]))); } catch { return iso; }
}

const PAGE = 4;
// In the provider's locale, as the days are, so the server's render and the browser's agree.
const gb = (n: number, locale: string) => `${n.toLocaleString(locale, { maximumFractionDigits: 1 })} GB`;

/** The dashboard page: a skip link, a header, then main with the h1 and its parts. */
export function Dashboard({ data = demo, loading = false, loadFailed = false, onRetry, name = 'Ana', onCreateProject, onLoadMoreActivity, hasMoreActivity = false }: DashboardProps) {
  const locale = useLocale();
  const [shown, setShown] = React.useState(PAGE);
  const firstRun = !loading && !loadFailed && data.projects.length === 0;
  const events = onLoadMoreActivity ? data.activity : data.activity.slice(0, shown);
  const more = () => (onLoadMoreActivity ? onLoadMoreActivity() : Promise.resolve().then(() => setShown((n) => n + PAGE)));
  const { used, limit } = data.storage;

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" aria-busy={loading || undefined} className="mx-auto flex max-w-6xl flex-col gap-8 px-4 py-8 outline-none">
        <PageHeader title={`Good morning, ${name}`} primary={firstRun ? undefined : { label: 'New project', onSelect: () => onCreateProject?.() }} />

        {loadFailed ? (
          <Card>
            <EmptyLoadFailed title="Couldn’t load your dashboard" onRetry={() => onRetry?.()} headingLevel={2} />
          </Card>
        ) : firstRun ? (
          <Card>
            <EmptyFirstRun title="No projects yet" headingLevel={2} createLabel="New project" onCreate={() => onCreateProject?.()}
              description="A project holds the tasks, files and people for one piece of work. Start one, and its numbers show up here."
              learnHref="#guide" learnLabel="How projects work" />
          </Card>
        ) : (
          <>
            <StatsRow title="This month" period="vs last month" stats={data.stats} loading={loading} />

            <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
              <section aria-labelledby="dash-projects" className="flex min-w-0 flex-col gap-3 lg:col-span-2">
                <div className="flex flex-wrap items-baseline justify-between gap-3">
                  <Heading level={2} size="lg" id="dash-projects">Recent projects</Heading>
                  <Link href="#projects">All projects</Link>
                </div>
                <Card padding="none" className="min-w-0 overflow-x-auto">
                  {loading ? (
                    <div className="p-4"><Loader variant="skeleton" shape="text" lines={5} label="Loading: Recent projects" /></div>
                  ) : (
                    <Table caption="Recent projects" hideCaption>
                      <TableHead><TableRow>
                        <TableHeaderCell>Name</TableHeaderCell><TableHeaderCell>Status</TableHeaderCell><TableHeaderCell>Updated</TableHeaderCell>
                      </TableRow></TableHead>
                      <TableBody>{data.projects.map((p) => (
                        <TableRow key={p.href}>
                          <TableCell><Link href={p.href}>{p.name}</Link></TableCell>
                          <TableCell><Badge dot tone={p.statusTone ?? 'neutral'}>{p.status}</Badge></TableCell>
                          <TableCell><time dateTime={p.updated}>{shortDay(p.updated, locale)}</time></TableCell>
                        </TableRow>
                      ))}</TableBody>
                    </Table>
                  )}
                </Card>
              </section>

              <section aria-labelledby="dash-usage" className="flex min-w-0 flex-col gap-3">
                <Heading level={2} size="lg" id="dash-usage">Usage</Heading>
                <Card className="flex flex-col gap-5">
                  {loading ? <Loader variant="skeleton" shape="text" lines={4} label="Loading: Usage" /> : (
                    <>
                      <Meter label="Storage" showValue value={used} max={limit} high={limit * 0.8} optimum={0}
                        formatValue={(v, _, max) => `${gb(v, locale)} of ${gb(max, locale)}${v >= max * 0.8 ? ', almost full' : ''}`} />
                      <Progress label={data.goal.label} showValue value={data.goal.done} max={data.goal.total}
                        formatValue={(v, max) => `${v} of ${max} done`} />
                      <Link href="#billing">Change plan</Link>
                    </>
                  )}
                </Card>
              </section>
            </div>

            {/* One shape loading and loaded, so the heading doesn't jump when the events arrive: the feed's own
                skeleton rows (an avatar and two lines) stand in for the events. */}
            <Card>
              <ActivityFeed events={events} loading={loading} headingSize="lg" onLoadMore={more} total={onLoadMoreActivity ? undefined : data.activity.length}
                hasMore={onLoadMoreActivity ? hasMoreActivity : shown < data.activity.length} />
            </Card>
          </>
        )}
      </main>
    </div>
  );
}

files.DataImport.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { FileUpload } from '@diki-stwn/serupa-ds';
import { withViewTransition } from '@diki-stwn/serupa-ds';
import { Stepper } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { Table, TableBody, TableCell, TableHead, TableHeaderCell, TableRow } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';

/* Data import: a CSV file of customers, its columns matched to the app's fields, every row checked and shown before
   anything is saved, then what happened in words. For an app to copy. What it carries (WCAG 2.2):
   - 3.3.4: nothing is saved until the last step's button, which says how many rows it saves. The check step lists
     each row's problems first, and rows with problems are skipped only when that's chosen.
   - 3.3.1, 3.3.3: a file that can't be read, a field left unmatched or a column used twice shows an ErrorSummary
     that takes focus and links to the control, each saying what to do.
   - 1.3.1, 1.4.1: the preview is a table with column headers; a row's problem is a Badge with its words and the
     message in its own column, never only a color.
   - 2.4.3, 4.1.3: each new step puts focus on its heading, so the change is said and Tab goes on from there; the
     Stepper above says which step this is in words.
   - 3.3.7: Back keeps the file and the matches, so nothing is chosen twice.
   Motion (the Motion foundation's "Layout changes"): the next step slides in from the end and Back brings the one
   before in from the start, mirrored right to left, so the way through reads as a direction. Under reduced motion
   the steps crossfade; where View Transitions are missing they swap at once.
   Saving the rows is the app's job: onImport stands in for it, and `existing` for the app's own records. */

export interface ImportField { key: 'name' | 'email' | 'phone' | 'city'; label: string; required: boolean }
export const FIELDS: ImportField[] = [
  { key: 'name', label: 'Name', required: true },
  { key: 'email', label: 'Email', required: true },
  { key: 'phone', label: 'Phone', required: false },
  { key: 'city', label: 'City', required: false },
];
export type ImportRow = Record<ImportField['key'], string>;
/** For each field, the index of the file's column that fills it, or -1 for none. */
export type ImportMapping = Record<ImportField['key'], number>;
export interface CheckedRow { line: number; row: ImportRow; problems: string[]; update: boolean }
export type DataImportStep = 'upload' | 'match' | 'check' | 'done';

export interface DataImportProps {
  /** The step it starts on, with `file`. Default: 'upload'. */
  start?: DataImportStep | undefined;
  /** A file already chosen: its name and text. */
  file?: { name: string; text: string } | undefined;
  /** Emails of the customers the app already has: a row with one of them updates that customer. */
  existing?: string[] | undefined;
  /** Saves the rows. A rejected promise keeps the check step, with "Couldn't import" and Try again. */
  onImport?: ((rows: ImportRow[]) => unknown) | undefined;
}

/** The rows of a CSV file: commas between cells, a line break between rows, "quoted" cells holding commas, line
    breaks and "" for a quote. Empty lines are left out. */
export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [], cell = '', quoted = false;
  const s = text.replace(/^\uFEFF/, '');
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quoted) {
      if (ch === '"' && s[i + 1] === '"') { cell += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cell += ch;
    } else if (ch === '"' && !cell) quoted = true;
    else if (ch === ',') { row.push(cell); cell = ''; }
    else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && s[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some((c) => c.trim())) rows.push(row);
      row = [];
    } else cell += ch;
  }
  row.push(cell);
  if (row.some((c) => c.trim())) rows.push(row);
  return rows;
}

const norm = (x: string) => x.toLowerCase().replace(/[^a-z]/g, '');
const SAME: Record<ImportField['key'], string[]> = { name: ['name', 'fullname', 'customer', 'nama'], email: ['email', 'emailaddress', 'mail'], phone: ['phone', 'mobile', 'telephone', 'tel', 'telepon'], city: ['city', 'town', 'kota'] };
/** Matches each field to the column whose heading names it, or -1. */
export function guessMapping(headers: string[]): ImportMapping {
  const out = {} as ImportMapping;
  for (const f of FIELDS) out[f.key] = headers.findIndex((h) => SAME[f.key].includes(norm(h)));
  return out;
}

/** What's wrong with the matches, in the order of the fields. */
export function mappingProblems(m: ImportMapping, headers: string[]): ErrorSummaryItem[] {
  const out: ErrorSummaryItem[] = [];
  for (const f of FIELDS) {
    const col = m[f.key];
    if (col < 0) { if (f.required) out.push({ field: `import-${f.key}`, message: `Choose the column that holds each customer’s ${f.label.toLowerCase()}` }); continue; }
    const first = FIELDS.find((g) => m[g.key] === col);
    if (first && first.key !== f.key) out.push({ field: `import-${f.key}`, message: `Choose another column for ${f.label.toLowerCase()}: “${headers[col]}” is already used for ${first.label.toLowerCase()}` });
  }
  return out;
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
/** Each data row as the app's fields, with its problems and whether it updates a customer the app has. */
export function checkRows(data: string[][], m: ImportMapping, existing: string[]): CheckedRow[] {
  const known = new Set(existing.map((e) => e.toLowerCase()));
  const seen = new Map<string, number>();
  return data.map((cells, i) => {
    const row = {} as ImportRow;
    for (const f of FIELDS) row[f.key] = m[f.key] < 0 ? '' : (cells[m[f.key]] || '').trim();
    const problems: string[] = [];
    if (!row.name) problems.push('No name');
    if (!row.email) problems.push('No email');
    else if (!EMAIL.test(row.email)) problems.push(`“${row.email}” isn’t an email address`);
    else {
      const twice = seen.get(row.email.toLowerCase());
      if (twice) problems.push(`Same email as line ${twice}`);
      else seen.set(row.email.toLowerCase(), i + 2);
    }
    return { line: i + 2, row, problems, update: known.has(row.email.toLowerCase()) };
  });
}

// A phone number reads as one piece: it doesn't break at its spaces.
const NOWRAP: Partial<Record<ImportField['key'], string>> = { phone: 'whitespace-nowrap' };
// Phone numbers and email addresses read left to right in every language: isolated, so a right-to-left page doesn't
// reverse their runs ("+62 811 0000 1234" would come out "1234 0000 811 62+").
const LTR: Partial<Record<ImportField['key'], true>> = { phone: true, email: true };
const DEMO_EXISTING = ['ani@example.com', 'budi@example.com'];
const STEPS = [{ title: 'Choose a file' }, { title: 'Match columns' }, { title: 'Check rows' }, { title: 'Done' }];
const ORDER: DataImportStep[] = ['upload', 'match', 'check', 'done'];
const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;

/** The import page: a skip link, then main with the Stepper and the step's form. */
export function DataImport({ start = 'upload', file: given, existing = DEMO_EXISTING, onImport }: DataImportProps) {
  const [step, setStep] = React.useState<DataImportStep>(given ? start : 'upload');
  const [file, setFile] = React.useState(given);
  const [files, setFiles] = React.useState<File[]>([]);
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>([]);
  const [tries, setTries] = React.useState(0);
  const table = React.useMemo(() => (file ? parseCsv(file.text) : []), [file]);
  const headers = table[0] || [];
  const [mapping, setMapping] = React.useState<ImportMapping>(() => guessMapping(headers));
  const [skip, setSkip] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [result, setResult] = React.useState<{ added: number; updated: number; skipped: number } | null>(null);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const moved = React.useRef(false);
  React.useEffect(() => { if (moved.current) heading.current?.focus(); }, [step]);
  // A step further on comes in from the end, one before from the start; starting a new import goes forward too.
  const go = (s: DataImportStep, way: 'forward' | 'back' = ORDER.indexOf(s) < ORDER.indexOf(step) ? 'back' : 'forward') =>
    void withViewTransition(() => { moved.current = true; setErrors([]); setStep(s); }, { types: [way] });
  const fail = (found: ErrorSummaryItem[]) => { setErrors(found); setTries((t) => t + 1); return found.length > 0; };
  const error = (field: string) => errors.find((e) => e.field === field)?.message;

  const checked = React.useMemo(() => checkRows(table.slice(1), mapping, existing), [table, mapping, existing]);
  const bad = checked.filter((r) => r.problems.length), good = checked.filter((r) => !r.problems.length);
  const updates = good.filter((r) => r.update).length;

  const read = async (e: React.FormEvent) => {
    e.preventDefault();
    const chosen = files[0];
    if (!chosen && !file) { fail([{ field: 'import-file', message: 'Choose a CSV file to import' }]); return; }
    const next = chosen ? { name: chosen.name, text: await chosen.text() } : file!;
    const rows = parseCsv(next.text);
    if (rows.length < 2) { fail([{ field: 'import-file', message: `${next.name} has no rows under its headings. Choose a CSV file with a heading row and a row for each customer` }]); return; }
    if (next !== file) { setFile(next); setMapping(guessMapping(rows[0] ?? [])); }
    go('match');
  };
  const match = (e: React.FormEvent) => {
    e.preventDefault();
    if (!fail(mappingProblems(mapping, headers))) go('check');
  };
  const save = (e: React.FormEvent) => {
    e.preventDefault();
    if (bad.length && !skip && fail([{ field: 'import-skip', message: `Fix the ${plural(bad.length, 'row', 'rows')} with problems in the file and choose it again, or skip them` }])) return;
    setBusy(true);
    setFailed(false);
    Promise.resolve().then(() => onImport?.(good.map((r) => r.row)))
      .then(() => { setResult({ added: good.length - updates, updated: updates, skipped: bad.length }); go('done'); }, () => setFailed(true))
      .finally(() => setBusy(false));
  };
  const again = () => { setFile(undefined); setFiles([]); setSkip(false); setResult(null); go('upload', 'forward'); };
  const columns = [{ value: '-1', label: 'Not in the file' }, ...headers.map((h, i) => ({ value: String(i), label: h || `Column ${i + 1}` }))];
  const summary = errors.length ? <ErrorSummary key={tries} errors={errors} headingLevel={3} /> : null;
  const h2 = (text: string) => <Heading level={2} size="lg" ref={heading} tabIndex={-1} className="outline-none">{text}</Heading>;

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-4xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Import customers" />
        <Stepper current={ORDER.indexOf(step) + (step === 'done' ? 1 : 0)} steps={STEPS} size="sm" />
        <Card className="flex flex-col gap-5" style={{ viewTransitionName: 'data-import-step', viewTransitionClass: 'step' }}>
          {step === 'upload' ? (
            <>
              {h2('Choose a file')}
              <p className="m-0">A CSV file with a heading row, then one row for each customer. A spreadsheet can save one: File, then Download or Export, then CSV.</p>
              {summary}
              <form noValidate onSubmit={(e) => { void read(e); }} className="flex flex-col gap-4">
                <Field label="Customer file" error={error('import-file')}>
                  <FileUpload id="import-file" accept=".csv,text/csv" maxSize={5 * 1024 * 1024} hint="CSV, up to 5 MB" files={files} onFilesChange={setFiles} />
                </Field>
                <Button type="submit" className="self-start">Continue</Button>
              </form>
            </>
          ) : step === 'match' ? (
            <>
              {h2('Match columns')}
              <p className="m-0">Choose the column in <strong>{file?.name}</strong> that holds each detail. We matched the ones whose headings name them.</p>
              {summary}
              <form noValidate onSubmit={match} className="flex flex-col gap-4">
                {FIELDS.map((f) => (
                  <Field key={f.key} label={f.label} optional={!f.required} error={error(`import-${f.key}`)}>
                    <Select id={`import-${f.key}`} options={columns} value={String(mapping[f.key])} onChange={(e) => { const v = Number(e.target.value); setMapping((o) => ({ ...o, [f.key]: v })); }} />
                  </Field>
                ))}
                <div className="flex flex-wrap gap-3">
                  <Button type="submit">Check rows</Button>
                  <Button variant="secondary" onClick={() => go('upload')}>Back</Button>
                </div>
              </form>
            </>
          ) : step === 'check' ? (
            <>
              {h2('Check rows')}
              <p className="m-0">
                {plural(good.length, 'row is', 'rows are')} ready: {plural(good.length - updates, 'new customer', 'new customers')} and {plural(updates, 'update', 'updates')} to customers you have.
                {bad.length ? ` ${plural(bad.length, 'row has', 'rows have')} problems, listed first.` : ''} Nothing is saved until you import.
              </p>
              {summary}
              <Table caption={`Rows in ${file?.name}`} hideCaption size="sm">
                <TableHead>
                  <TableRow>
                    <TableHeaderCell align="end">Line</TableHeaderCell>
                    <TableHeaderCell>Status</TableHeaderCell>
                    <TableHeaderCell>Problem</TableHeaderCell>
                    {FIELDS.map((f) => <TableHeaderCell key={f.key}>{f.label}</TableHeaderCell>)}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {[...bad, ...good].map((r) => (
                    <TableRow key={r.line}>
                      <TableCell align="end">{r.line}</TableCell>
                      <TableCell>{r.problems.length ? <Badge tone="danger">Problem</Badge> : r.update ? <Badge tone="info">Update</Badge> : <Badge tone="success">New</Badge>}</TableCell>
                      <TableCell>{r.problems.join('. ')}</TableCell>
                      {FIELDS.map((f) => <TableCell key={f.key} className={NOWRAP[f.key]}>{LTR[f.key] ? <bdi dir="ltr">{r.row[f.key]}</bdi> : r.row[f.key]}</TableCell>)}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
              <form noValidate onSubmit={save} className="flex flex-col gap-4">
                {bad.length ? (
                  <Field error={error('import-skip')}>
                    <Checkbox id="import-skip" checked={skip} onCheckedChange={setSkip} invalid={!!error('import-skip')}
                      description="They stay in your file, so you can fix them and import that file again.">
                      Skip the {plural(bad.length, 'row', 'rows')} with problems
                    </Checkbox>
                  </Field>
                ) : null}
                {failed ? <Alert tone="danger" title="Couldn’t import">Nothing was saved. Check your connection and try again.</Alert> : null}
                <div className="flex flex-wrap gap-3">
                  <Button type="submit" loading={busy} disabled={!good.length}>{failed ? 'Try again' : `Import ${plural(good.length, 'customer', 'customers')}`}</Button>
                  <Button variant="secondary" onClick={() => go('match')}>Back</Button>
                </div>
              </form>
            </>
          ) : (
            <>
              {h2('Import finished')}
              {result ? (
                <ul className="m-0 flex list-disc flex-col gap-1 ps-5">
                  <li>{plural(result.added, 'customer', 'customers')} added</li>
                  <li>{plural(result.updated, 'customer', 'customers')} updated</li>
                  <li>{plural(result.skipped, 'row', 'rows')} skipped{result.skipped ? ', still in your file to fix' : ''}</li>
                </ul>
              ) : null}
              <div className="flex flex-wrap items-center gap-4">
                <Link href="#customers">Go to customers</Link>
                <Button variant="secondary" onClick={again}>Import another file</Button>
              </div>
            </>
          )}
        </Card>
      </main>
    </div>
  );
}

files.DetailPage.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { InlineEdit } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Tabs, TabList, Tab, TabPanel } from '@diki-stwn/serupa-ds';
import { TypeToConfirm } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';

/* Detail page: one thing (a project) with where it sits, its name and details editable in place, its parts in tabs,
   small removals that can be undone, and a delete that can't, behind typing its name. For an app to copy. What it
   carries (WCAG 2.2):
   - 2.4.8, 1.3.1: a breadcrumb says where the page sits, the h1 is the project's name, and each tab's panel is
     named by its tab.
   - 3.3.4: removing a task happens at once with Undo in a toast, and is done for good only when the toast goes;
     deleting the project, which can't be undone, asks for its name first, in a dialog that says what will be lost.
   - 2.4.3: after a removal, focus goes to the next task (or the list's heading), never to the top of the page; after
     the delete, to the h1 of the page that says it's gone.
   - 4.1.3: the toast says what was removed; a saved name is shown in the h1 at once.
   - 3.3.1: a name left empty says so, and the old name stays; a delete that fails says so in the dialog, which stays
     open with focus on its button, so it can be tried again.
   - 1.3.1, 1.4.10: a supporting pane (`aside`), such as the project's activity, is a complementary landmark named by
     its heading; it sits beside the tabs on a wide screen and drops below them on a narrow one, in reading order.
   Storing the changes is the app's job: onRename, onRemoveTask and onDelete get them. */

export interface ProjectTask { id: string; title: string }
export interface Project { name: string; description: string; owner: string; created: string; tasks: readonly ProjectTask[] }

export interface DetailPageProps {
  /** The project shown. Default: a demo project. */
  project?: Project | undefined;
  /** A new name or description was saved. */
  onRename?: ((field: 'name' | 'description', value: string) => void) | undefined;
  /** A removed task's toast closed without Undo: remove it for good. */
  onRemoveTask?: ((id: string) => void) | undefined;
  /** The project's name was typed and Delete pressed. Return its promise, so the button shows it's busy. */
  onDelete?: (() => unknown) | undefined;
  /** Starts with the delete dialog open, as after a delete that failed: it says so, and the delete can be tried again. */
  deleteFailed?: boolean | undefined;
  /** The project is on its way: a busy placeholder for its details, named once ("Loading project"), in place of the page. Default: false. */
  loading?: boolean | undefined;
  /** The project failed to load: a "Couldn’t load this project" message with Try again, which calls onRetry, in place of the page. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** A supporting pane beside the tabs from 1024px, and below them on a narrower screen: the project's activity, its
      people. Its title names the landmark. */
  aside?: { title: string; content: React.ReactNode } | undefined;
}

const demo: Project = {
  name: 'Website redesign', description: 'New pages for the marketing site, with the updated brand.', owner: 'Ana Lima', created: '2026-09-14',
  tasks: [
    { id: 't1', title: 'Draft the home page copy' }, { id: 't2', title: 'Pick the photos' },
    { id: 't3', title: 'Review the pricing page' }, { id: 't4', title: 'Check the forms with a screen reader' },
  ],
};

// "14 September 2026" in the reader's locale for "2026-09-14", read as that calendar day wherever the reader is;
// anything else as it came.
function day(iso: string, locale: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return iso;
  try { return new Intl.DateTimeFormat(locale, { dateStyle: 'long' }).format(new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]))); } catch { return iso; }
}

const english = /* @__PURE__ */ new Intl.PluralRules('en');

/** The detail page: a skip link, a header, then main with the breadcrumb, the h1, the tabs and the danger zone. */
export function DetailPage({ project = demo, onRename, onRemoveTask, onDelete, deleteFailed, loading = false, loadFailed = false, onRetry, aside }: DetailPageProps) {
  const [name, setName] = React.useState(project.name);
  const [description, setDescription] = React.useState(project.description);
  // A new name or description from the app (another project opened, or the saved one coming back) replaces the one
  // shown; one the app passes again unchanged keeps an edit it hasn't stored yet.
  const [given, setGiven] = React.useState({ name: project.name, description: project.description });
  if (given.name !== project.name || given.description !== project.description) {
    setGiven({ name: project.name, description: project.description });
    if (given.name !== project.name) setName(project.name);
    if (given.description !== project.description) setDescription(project.description);
  }
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(new Set());
  const [asking, setAsking] = React.useState(!!deleteFailed);
  const [deleted, setDeleted] = React.useState(false);
  const [failed, setFailed] = React.useState(!!deleteFailed);
  const locale = useLocale();
  // The Undo toasts still open, and whether the project is gone: once it is, they close without removing anything,
  // since the delete took their tasks with it.
  const pending = React.useRef(new Set<string>());
  const gone = React.useRef(false);
  const tasksHeading = React.useRef<HTMLHeadingElement>(null);
  const goneHeading = React.useRef<HTMLHeadingElement>(null);
  const tasks = project.tasks.filter((t) => !hidden.has(t.id));
  const later = (f: () => void) => requestAnimationFrame(f);
  const removeButton = (id: string) => () => document.getElementById(`task-${id}`)?.focus();

  React.useEffect(() => { if (deleted) goneHeading.current?.focus(); }, [deleted]);

  const remove = (t: ProjectTask) => {
    const at = tasks.indexOf(t), next = tasks[at + 1] || tasks[at - 1];
    setHidden((h) => new Set(h).add(t.id));
    later(next ? removeButton(next.id) : () => tasksHeading.current?.focus());
    const id: string = toast.undo({
      title: `Removed “${t.title}”`,
      commit: () => { pending.current.delete(id); if (!gone.current) onRemoveTask?.(t.id); },
      onUndo: () => { pending.current.delete(id); setHidden((h) => { const n = new Set(h); n.delete(t.id); return n; }); later(removeButton(t.id)); },
    });
    pending.current.add(id);
  };
  // Saved without the spaces around it, as the check reads it.
  const save = (field: 'name' | 'description', set: (v: string) => void) => (v: string) => { const kept = v.trim(); set(kept); onRename?.(field, kept); };
  // A delete that fails, by rejecting or by throwing, keeps the dialog open and says so, instead of leaving the error
  // unhandled. The promise goes back to the button, which shows it's busy while a slow delete runs.
  const confirm = () => {
    setFailed(false);
    return Promise.resolve().then(() => onDelete?.()).then(() => {
      gone.current = true;
      for (const id of [...pending.current]) toast.dismiss(id);
      setAsking(false);
      setDeleted(true);
    }, () => setFailed(true));
  };
  const ask = (open: boolean) => { setAsking(open); if (!open) setFailed(false); };
  // What the dialog says will be lost: the tasks still there, with the word that fits the number: the words are
  // English, so the rule is too; an app translating them passes its own locale.
  const lost = tasks.length
    ? `its ${tasks.length} ${english.select(tasks.length) === 'one' ? 'task' : 'tasks'} and files`
    : 'its files';

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" aria-busy={loading && !loadFailed ? true : undefined} className={`mx-auto flex ${aside ? 'max-w-6xl' : 'max-w-4xl'} flex-col gap-6 px-4 py-8 outline-none`}>
        {loadFailed || loading ? (
          // The name isn't known yet, so the h1 says only what the page is; the way back stays.
          <>
            <Link href="#projects">Back to projects</Link>
            <Heading level={1} className="sr-only">Project</Heading>
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load this project" onRetry={() => onRetry?.()} headingLevel={2} />
              : <Card><Loader variant="skeleton" shape="text" lines={4} label="Loading project" /></Card>}
          </>
        ) : deleted ? (
          <div className="flex flex-col gap-3">
            <Heading level={1} ref={goneHeading} tabIndex={-1} className="outline-none">{name} was deleted</Heading>
            <p className="m-0 text-text-muted">Its tasks and files are gone too.</p>
            <Link href="#projects">Back to projects</Link>
          </div>
        ) : (
          <>
            <PageHeader breadcrumb={[{ label: 'Projects', href: '#projects' }, { label: name }]} title={name} description={description}
              primary={{ label: 'Share', href: '#share' }} />

            <div className={aside ? 'grid grid-cols-1 items-start gap-6 lg:grid-cols-3' : 'contents'}>
            <Tabs defaultValue="overview" className={aside ? 'min-w-0 lg:col-span-2' : undefined}>
              <TabList aria-label="Project">
                <Tab value="overview">Overview</Tab>
                <Tab value="tasks">Tasks</Tab>
                <Tab value="settings">Settings</Tab>
              </TabList>

              <TabPanel value="overview" className="pt-4">
                <Card>
                  <DescriptionList>
                    <DescriptionItem term="Name">
                      <InlineEdit label="Project name" value={name} onValueChange={save('name', setName)}
                        validate={(v) => (v.trim() ? null : 'Enter a name for the project.')} />
                    </DescriptionItem>
                    <DescriptionItem term="Description"><InlineEdit label="Description" value={description} onValueChange={save('description', setDescription)} /></DescriptionItem>
                    <DescriptionItem term="Owner">{project.owner}</DescriptionItem>
                    <DescriptionItem term="Created"><time dateTime={project.created}>{day(project.created, locale)}</time></DescriptionItem>
                  </DescriptionList>
                </Card>
              </TabPanel>

              <TabPanel value="tasks" className="pt-4">
                <Card className="flex flex-col gap-3">
                  <Heading level={2} size="lg" ref={tasksHeading} tabIndex={-1} className="outline-none">Tasks ({tasks.length})</Heading>
                  {tasks.length ? (
                    <ul className="m-0 flex list-none flex-col divide-y divide-border p-0">
                      {tasks.map((t) => (
                        <li key={t.id} className="flex flex-wrap items-center justify-between gap-3 py-2">
                          <span className="min-w-0">{t.title}</span>
                          <Button id={`task-${t.id}`} size="sm" variant="ghost" aria-label={`Remove ${t.title}`} onClick={() => remove(t)}>Remove</Button>
                        </li>
                      ))}
                    </ul>
                  ) : <p className="m-0 text-text-muted">No tasks left.</p>}
                </Card>
              </TabPanel>

              <TabPanel value="settings" className="pt-4">
                <section aria-labelledby="danger" className="flex flex-col gap-3 rounded-lg border border-danger bg-surface p-4">
                  <Heading level={2} size="lg" id="danger">Delete this project</Heading>
                  <p className="m-0 max-w-prose">Deleting removes the project with its tasks and files for everyone. It can’t be undone.</p>
                  <div><Button destructive variant="outline" onClick={() => ask(true)}>Delete project</Button></div>
                </section>
              </TabPanel>
            </Tabs>
            {aside ? (
              <aside aria-labelledby="detail-aside" className="flex min-w-0 flex-col gap-3">
                <Heading level={2} size="lg" id="detail-aside">{aside.title}</Heading>
                {aside.content}
              </aside>
            ) : null}
            </div>

            <Dialog alert open={asking} onOpenChange={ask} title={`Delete ${name}?`}
              description={`This deletes the project and ${lost} for everyone. It can’t be undone.`}>
              <div className="flex flex-col gap-4">
                {failed ? <Alert tone="danger">Couldn’t delete {name}. Try again.</Alert> : null}
                <TypeToConfirm phrase={name} confirmLabel="Delete this project" onConfirm={confirm} />
              </div>
            </Dialog>
          </>
        )}
      </main>
      <Toaster />
    </div>
  );
}

