'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card, CardHeader } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Faq, type FaqGroup } from './Faq';
import { PageHeader } from './PageHeader';

/* Help center: the topics people come for, the common questions with a search, and a way to write to a person that
   says when they'll answer. For an app to copy. What it carries (WCAG 2.2):
   - 3.2.6: the way to reach a person is in the same place, last on the page, and every topic and the questions'
     "Still stuck?" lead to it.
   - 1.3.1, 2.4.4: each topic is a heading whose link is named by its title, with what it covers under it, and the
     whole card takes the click.
   - 4.1.3: the questions' search says how many match (the FAQ block); a sent message is said with what happens next.
   - 3.3.1, 3.3.2: the message form says what to write before it's sent, names a missing topic or message next to its
     field and moves focus to the first, and a send that fails says so and keeps every word.
   Sending the message is the app's job: onSend gets it. */

export interface HelpTopic { id: string; title: string; description: string; href: string }
export interface HelpMessage { topic: string; message: string }

export interface HelpCenterProps {
  /** The topics people come for, as links to their articles. Default: four demo topics. */
  topics?: readonly HelpTopic[] | undefined;
  /** The common questions, in groups. Default: demo questions. */
  questions?: readonly FaqGroup[] | undefined;
  /** Where replies go, shown with the form and after sending. Default: "ana@example.com". */
  email?: string | undefined;
  /** How soon a person answers, as the end of "We answer …". Default: "within one working day". */
  replyTime?: string | undefined;
  /** Send was pressed with a topic and a message. Return its promise: a rejection says it wasn't sent. */
  onSend?: ((message: HelpMessage) => unknown) | undefined;
  /** The form's first answers, to bring a message back. */
  initial?: Partial<HelpMessage> | undefined;
  /** Start at the form, or with the message already sent. Default: "form". */
  start?: 'form' | 'sent' | undefined;
  /** Start with what went wrong already said: "empty" names what's missing, "send" says the last send failed. */
  failed?: 'empty' | 'send' | undefined;
}

const demoTopics: HelpTopic[] = [
  { id: 'start', title: 'Getting started', description: 'Set up a workspace, invite your team and make a first project.', href: '#help-start' },
  { id: 'account', title: 'Your account', description: 'Sign-in, two-step verification, and changing your email.', href: '#help-account' },
  { id: 'billing', title: 'Billing', description: 'Plans, invoices, refunds and cancelling.', href: '#help-billing' },
  { id: 'data', title: 'Your data', description: 'Exports, imports, and where your data is kept.', href: '#help-data' },
];
const demoQuestions: FaqGroup[] = [
  { id: 'q-account', title: 'Your account', questions: [
    { id: 'change-email', question: 'How do I change my email address?', answer: 'Go to Settings, then Account, and choose Change email. We send a link to the new address; the change takes effect once you open it.' },
    { id: 'two-step', question: 'How do I turn on two-step verification?', answer: 'Go to Settings, then Security, and choose Turn on. You need an authenticator app on your phone.', keywords: '2fa mfa authenticator' },
  ] },
  { id: 'q-billing', title: 'Billing', questions: [
    { id: 'cancel-plan', question: 'How do I cancel my plan?', answer: 'Go to Settings, then Billing, and choose Cancel plan. Your plan runs until the end of the period you paid for.', keywords: 'stop subscription' },
    { id: 'refund', question: 'Can I get a refund?', answer: 'Yes, within 14 days of a payment, for any reason. Write to us below and we refund it to the card you paid with.', keywords: 'money back' },
  ] },
];
const TOPICS = ['Your account', 'Billing', 'Your data', 'Something else'];

/** What's missing from a message, by field, in the order of the form. */
export function messageProblems(m: HelpMessage): { field: 'topic' | 'message'; text: string }[] {
  const found: { field: 'topic' | 'message'; text: string }[] = [];
  if (!m.topic) found.push({ field: 'topic', text: 'Choose what your message is about.' });
  if (!m.message.trim()) found.push({ field: 'message', text: 'Write what happened, or what you’re trying to do.' });
  return found;
}

/** The help page: a skip link, a header, then main with the h1, the topics, the questions and the message form. */
export function HelpCenter({ topics = demoTopics, questions = demoQuestions, email = 'ana@example.com', replyTime = 'within one working day', onSend,
  initial, start = 'form', failed }: HelpCenterProps) {
  const [value, setValue] = React.useState<HelpMessage>({ topic: '', message: '', ...initial });
  const [problems, setProblems] = React.useState(() => (failed === 'empty' ? messageProblems(value) : []));
  const [state, setState] = React.useState<'editing' | 'sending' | 'sent' | 'failed'>(start === 'sent' ? 'sent' : failed === 'send' ? 'failed' : 'editing');
  // Focus moves to "We got your message" when it's sent here, not when the page opens on it.
  const sentHere = React.useRef(false);
  const sentHeading = React.useRef<HTMLHeadingElement>(null);
  React.useEffect(() => { if (state === 'sent' && sentHere.current) sentHeading.current?.focus(); }, [state]);
  const problem = (f: 'topic' | 'message') => problems.find((p) => p.field === f)?.text;
  const set = (patch: Partial<HelpMessage>) => {
    const next = { ...value, ...patch };
    setValue(next);
    // A problem goes as soon as it's fixed; new ones wait for Send.
    if (problems.length) setProblems(messageProblems(next).filter((p) => problems.some((q) => q.field === p.field)));
  };
  const send = (e: React.FormEvent) => {
    e.preventDefault();
    const found = messageProblems(value);
    setProblems(found);
    if (found[0]) { document.getElementById(`help-${found[0].field}`)?.focus(); return; }
    setState('sending');
    void Promise.resolve().then(() => onSend?.(value)).then(() => { sentHere.current = true; setState('sent'); }, () => setState('failed'));
  };

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-4xl flex-col gap-10 px-4 py-8 outline-none">
        <PageHeader title="Help" description={<>Find an answer, or <Link href="#contact">write to us</Link>. We answer {replyTime}.</>} />

        <section aria-labelledby="help-topics" className="flex flex-col gap-4">
          <Heading level={2} size="lg" id="help-topics">Topics</Heading>
          <ul className="m-0 grid list-none grid-cols-1 gap-4 p-0 sm:grid-cols-2">
            {topics.map((t) => (
              <li key={t.id} className="flex">
                <Card href={t.href} className="w-full">
                  <CardHeader title={t.title} description={t.description} headingLevel={3} />
                </Card>
              </li>
            ))}
          </ul>
        </section>

        <Faq groups={questions} headingLevel={2}
          contact={<p className="m-0"><Link href="#contact">Write to us</Link>. We answer {replyTime}.</p>} />

        <section id="contact" aria-labelledby="help-contact" className="flex flex-col gap-4">
          {state === 'sent' ? (
            <>
              <Heading level={2} size="lg" id="help-contact" ref={sentHeading} tabIndex={-1} className="outline-none">We got your message</Heading>
              <p className="m-0">We answer {replyTime}, by email to <strong>{email}</strong>. You don’t need to do anything else.</p>
            </>
          ) : (
            <>
              <Heading level={2} size="lg" id="help-contact">Write to us</Heading>
              <p className="m-0 text-text-muted">A person reads every message and answers {replyTime}, by email to {email}.</p>
              <form noValidate onSubmit={send} className="flex max-w-xl flex-col gap-4">
                {state === 'failed' ? <Alert tone="danger">Couldn’t send your message. Try again: your words are still here.</Alert> : null}
                <Field label="What is it about?" error={problem('topic')} required>
                  <Select id="help-topic" placeholder="Choose one" value={value.topic} options={TOPICS.map((t) => ({ value: t, label: t }))}
                    onChange={(e) => set({ topic: e.target.value })} />
                </Field>
                <Field label="Your message" hint="What happened, and what you expected. Add the page or project name if it helps." error={problem('message')} required>
                  <Textarea id="help-message" rows={5} value={value.message} onChange={(e) => set({ message: e.target.value })} />
                </Field>
                <Button type="submit" className="self-start" loading={state === 'sending'}>Send</Button>
              </form>
            </>
          )}
        </section>
      </main>
    </div>
  );
}

files.Integrations.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { IconTile } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { SearchInput } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed, EmptyNoResults } from './EmptyStates';

/* Integrations: the other apps a workspace can connect, which are connected, connecting one and disconnecting one.
   For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 2.4.6: connected and available apps are two lists under their own headings, and each app is a heading, so
     a screen reader can list them and jump between them.
   - 2.4.6, 4.1.2: each button is named with its app ("Connect Slack", "Disconnect GitHub"), so a list of them isn't
     "Connect, Connect, Connect".
   - 1.4.1: connected is said in words, not only by a color or a mark.
   - 4.1.3: how many apps match the search is a status, so it's said politely as people type.
   - 3.3.4: disconnecting stops what the app does at once, so it asks first and says what stops.
   - 3.3.1: a connect that fails says so on that app's card, with what to do; a failed disconnect says so in its dialog.
   - 2.4.3: after a connect or a disconnect, focus goes to the app's button in the list it moved to, never to the top.
   Connecting (usually a sign-in on the other app's page) and disconnecting are the app's job: onConnect and
   onDisconnect get the app's id. */

export interface Integration {
  id: string;
  name: string;
  /** What it does once connected, in a sentence. */
  description: string;
  /** Its picture: a Serupa icon name or your own SVG. */
  icon: React.ComponentProps<typeof IconTile>['icon'];
  connected?: boolean | undefined;
  /** What stops when it's disconnected, said before it is: "New issues stop showing on your projects." */
  stops?: string | undefined;
}

export interface IntegrationsProps {
  /** The apps, in the order to show them. Default: six demo apps, two connected. */
  apps?: readonly Integration[] | undefined;
  /** Connect was pressed. Return its promise: a rejection says on the app's card that it didn't connect. */
  onConnect?: ((id: string) => unknown) | undefined;
  /** Disconnect was pressed and confirmed. Return its promise: a rejection keeps it connected and says so. */
  onDisconnect?: ((id: string) => unknown) | undefined;
  /** The apps are on their way: placeholder cards, named once ("Loading integrations"). Default: false. */
  loading?: boolean | undefined;
  /** The apps failed to load: a "Couldn’t load your integrations" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

const demo: Integration[] = [
  { id: 'slack', name: 'Slack', icon: 'forum', connected: true, description: 'Posts a message to a channel when a project changes.', stops: 'Messages stop going to your Slack channels.' },
  { id: 'github', name: 'GitHub', icon: 'code', connected: true, description: 'Links pull requests and issues to projects.', stops: 'Pull requests and issues stop showing on your projects.' },
  { id: 'calendar', name: 'Google Calendar', icon: 'calendar_month', description: 'Adds project due dates to a calendar.' },
  { id: 'drive', name: 'Google Drive', icon: 'folder', description: 'Attaches files from Drive to projects.' },
  { id: 'zapier', name: 'Zapier', icon: 'bolt', description: 'Connects to thousands of other apps without code.' },
  { id: 'stripe', name: 'Stripe', icon: 'payments', description: 'Shows payments and invoices next to customers.' },
];

/** The apps whose name or description holds every word of the query. */
export function matchIntegrations(apps: readonly Integration[], query: string): Integration[] {
  const words = query.toLocaleLowerCase().split(/\s+/).filter(Boolean);
  return apps.filter((a) => words.every((w) => `${a.name} ${a.description}`.toLocaleLowerCase().includes(w)));
}

/** The integrations page: a skip link, a header, then main with the h1, a search, and the connected and available apps. */
export function Integrations({ apps = demo, onConnect, onDisconnect, loading = false, loadFailed = false, onRetry }: IntegrationsProps) {
  const [on, setOn] = React.useState<Record<string, boolean>>({});
  const [query, setQuery] = React.useState('');
  const [busy, setBusy] = React.useState<string | null>(null);
  const [failed, setFailed] = React.useState<string | null>(null);
  const [asking, setAsking] = React.useState<Integration | null>(null);
  const [disconnectFailed, setDisconnectFailed] = React.useState(false);
  const isOn = (a: Integration) => on[a.id] ?? !!a.connected;
  const found = matchIntegrations(apps, query);
  const connected = found.filter(isOn), available = found.filter((a) => !isOn(a));
  const later = (id: string) => requestAnimationFrame(() => document.getElementById(id)?.focus());

  const connect = (a: Integration) => {
    setBusy(a.id);
    setFailed(null);
    void Promise.resolve().then(() => onConnect?.(a.id)).then(() => {
      setOn((o) => ({ ...o, [a.id]: true }));
      toast({ title: `Connected ${a.name}`, tone: 'success' });
      later(`disconnect-${a.id}`);
    }, () => setFailed(a.id)).finally(() => setBusy(null));
  };
  const ask = (a: Integration | null) => { setAsking(a); setDisconnectFailed(false); };
  const disconnect = () => {
    const a = asking;
    if (!a) return;
    setBusy(a.id);
    setDisconnectFailed(false);
    void Promise.resolve().then(() => onDisconnect?.(a.id)).then(() => {
      setOn((o) => ({ ...o, [a.id]: false }));
      setAsking(null);
      toast({ title: `Disconnected ${a.name}`, tone: 'success' });
      // The dialog gives focus back to its opener, which moved lists: Connect, in the available list, takes it.
      later(`connect-${a.id}`);
    }, () => setDisconnectFailed(true)).finally(() => setBusy(null));
  };

  const card = (a: Integration) => {
    const connectedNow = isOn(a);
    return (
      <li key={a.id} className="flex">
        <Card className="flex w-full flex-col gap-3">
          <div className="flex items-start gap-3">
            <IconTile icon={a.icon} tone={connectedNow ? 'primary' : 'neutral'} />
            <div className="flex min-w-0 flex-1 flex-col gap-1">
              <Heading level={3} size="base">{a.name}</Heading>
              <p className="m-0 text-sm text-text-muted">{a.description}</p>
            </div>
            {connectedNow ? <Badge tone="success">Connected</Badge> : null}
          </div>
          {failed === a.id ? <Alert tone="danger">Couldn’t connect {a.name}. Check that you allowed it on {a.name}’s page, then try again.</Alert> : null}
          <div className="mt-auto flex flex-wrap gap-2">
            {connectedNow ? (
              <Button id={`disconnect-${a.id}`} size="sm" variant="outline" aria-label={`Disconnect ${a.name}`} onClick={() => ask(a)}>Disconnect</Button>
            ) : (
              <Button id={`connect-${a.id}`} size="sm" variant="outline" aria-label={`Connect ${a.name}`} loading={busy === a.id} onClick={() => connect(a)}>Connect</Button>
            )}
          </div>
        </Card>
      </li>
    );
  };
  const list = (title: string, items: Integration[], none: string) => (
    <section aria-labelledby={`integrations-${title.toLowerCase()}`} className="flex flex-col gap-3">
      <Heading level={2} size="lg" id={`integrations-${title.toLowerCase()}`}>{title} ({items.length})</Heading>
      {items.length ? <ul className="m-0 grid list-none grid-cols-1 gap-4 p-0 md:grid-cols-2">{items.map(card)}</ul>
        : <p className="m-0 text-text-muted">{none}</p>}
    </section>
  );

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-5xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Integrations" description="Connect the other apps your team uses. Only admins can connect or disconnect them." />

        {loadFailed ? <EmptyLoadFailed title="Couldn’t load your integrations" onRetry={() => onRetry?.()} headingLevel={2} /> : loading ? (
          <ul role="list" aria-busy="true" className="m-0 grid list-none grid-cols-1 gap-4 p-0 md:grid-cols-2">
            {/* One name for all of them: the first card is named, the others are only pictures. */}
            {[0, 1, 2, 3].map((i) => <li key={i}><Card><Loader variant="skeleton" shape="text" lines={3} label={i === 0 ? 'Loading integrations' : ''} /></Card></li>)}
          </ul>
        ) : <>
          <Field label="Search integrations" className="max-w-md">
            <SearchInput value={query} onChange={(e) => setQuery(e.target.value)} onClear={() => setQuery('')} clearLabel="Clear the search" />
          </Field>
          <p role="status" className="m-0 text-sm text-text-muted">{found.length === 1 ? '1 app' : `${found.length} apps`}</p>
          {found.length ? <>
            {list('Connected', connected, 'None of these are connected.')}
            {list('Available', available, 'Every one of these is connected.')}
          </> : (
            <EmptyNoResults query={query.trim()} headingLevel={2} title={(q) => `No apps match “${q}”`}
              description="Try another name, or what you want it to do." onClearFilters={() => setQuery('')} />
          )}
        </>}

        <Dialog alert open={!!asking} onOpenChange={(o) => { if (!o) ask(null); }}
          title={asking ? `Disconnect ${asking.name}?` : 'Disconnect?'}
          description={`${asking?.stops ?? 'It stops working with this workspace.'} You can connect it again at any time.`}>
          <div className="flex flex-col gap-4">
            {disconnectFailed ? <Alert tone="danger">Couldn’t disconnect {asking?.name}. It’s still connected. Try again.</Alert> : null}
            <div className="flex flex-wrap gap-2">
              <Button variant="outline" onClick={() => ask(null)}>Keep it</Button>
              <Button variant="outline" destructive loading={!!asking && busy === asking.id} onClick={disconnect}>Disconnect</Button>
            </div>
          </div>
        </Dialog>
      </main>
      <Toaster />
    </div>
  );
}

