'use client';
import * as React from 'react';
import { flushSync } from 'react-dom';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { List, ListItem } from '@diki-stwn/serupa-ds';
import { Splitter } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Loader } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { withViewTransition } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';

/* List and detail: a list of messages beside the one that's open, in two panes on a wide screen and one at a time on
   a phone. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the list and the open message are regions named by their headings; the open item is aria-current.
   - 1.4.10: on a narrow screen the panes don't squeeze side by side: the list shows, choosing one shows it alone
     with "Back to messages", and nothing scrolls sideways.
   - 3.2.3: on a phone, the browser's or the system's Back from a message returns to the list, as "Back to messages"
     does, rather than leaving the page: opening a message adds a history entry (with no new address).
   - 2.4.3: on a phone, opening a message puts focus on its heading, and Back puts it on the message it came from,
     still marked as open, so the place in the list is never lost. On a wide screen focus stays in the list.
   - 2.1.1: the panes' divider is a Splitter, moved with the arrow keys as well as by dragging.
   - 4.1.3: while the messages load, the list's pane shows placeholder rows, busy and named once ("Loading messages").
   - 4.1.3, 3.3.3: a failed load says so once, in the panes' place, with Try again (EmptyLoadFailed).
   - With no messages, an empty state says what will show up here, instead of two empty panes and "Messages (0)".
   Motion (the Motion foundation's "Layout changes"): on a phone, an opened message slides in from the end while its
   subject glides from its row up into the heading, and "Back to messages" plays it the other way, so the message
   is seen to come from its place in the list and go back to it. Under reduced motion the two views crossfade; where
   View Transitions are missing they swap at once. The browser's own Back swaps at once: it may animate on its own.
   Loading the messages is the app's job: pass them as `messages`, and onSelect hears which one is open. */

export interface Message { id: string; from: string; subject: string; date: string; body: string }

export interface ListDetailProps {
  /** The messages, newest first. Default: a demo inbox. */
  messages?: readonly Message[] | undefined;
  /** The message open at first. Default: the first on a wide screen, none on a phone. */
  defaultSelected?: string | undefined;
  /** A message was opened. */
  onSelect?: ((id: string) => void) | undefined;
  /** The messages failed to load: a "Couldn’t load" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** The messages are on their way: the list's pane with placeholder rows, named once ("Loading messages"). Default: false. */
  loading?: boolean | undefined;
}

const demo: Message[] = [
  { id: 'm1', from: 'Ana Lima', subject: 'Launch checklist', date: '2026-11-06', body: 'Three of five steps are done. The pricing page and the forms are still to check.' },
  { id: 'm2', from: 'Budi Santoso', subject: 'Invoice for October', date: '2026-11-05', body: 'The invoice is attached. It is due at the end of the month.' },
  { id: 'm3', from: 'Chen Wei', subject: 'New photos for the home page', date: '2026-11-04', body: 'Here are twelve photos from the shoot. Pick three for the home page.' },
  { id: 'm4', from: 'Dewi Lestari', subject: 'Help center: new articles', date: '2026-11-02', body: 'Four new articles are ready for review: billing, exports, teams and sign-in.' },
];

// "6 Nov 2026" (medium) or "6 November 2026" (long) in the reader's locale for "2026-11-06", read as that calendar
// day wherever the reader is; anything else as it came.
function day(iso: string, locale: string, style: 'medium' | 'long'): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return iso;
  try { return new Intl.DateTimeFormat(locale, { dateStyle: style }).format(new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]))); } catch { return iso; }
}

const WIDE = '(min-width: 48rem)';
const subscribe = (f: () => void) => { const m = matchMedia(WIDE); m.addEventListener('change', f); return () => m.removeEventListener('change', f); };
/** Whether the screen is wide enough for both panes. */
function useWide() { return React.useSyncExternalStore(subscribe, () => matchMedia(WIDE).matches, () => true); }

/** The list-and-detail page: a skip link, a header, then main with the list and the open message. */
export function ListDetail({ messages = demo, defaultSelected, onSelect, loading = false, loadFailed = false, onRetry }: ListDetailProps) {
  const locale = useLocale();
  const wide = useWide();
  const [picked, setPicked] = React.useState<string | undefined>(defaultSelected);
  const [showing, setShowing] = React.useState(false);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const focus = React.useRef<'detail' | string | null>(null);
  const open = messages.find((m) => m.id === picked) || (wide ? messages[0] : undefined);

  // every render: a focus asked for by a handler (focus) moves once the render it caused is on screen.
  React.useEffect(() => {
    const to = focus.current;
    focus.current = null;
    if (to === 'detail') heading.current?.focus();
    else if (to) document.getElementById(`message-${to}`)?.focus();
  });

  // On a phone, a message open on its own has a history entry of its own (pushed), so the browser's Back closes it.
  const pushed = React.useRef(false);
  const choose = (m: Message) => (e: React.MouseEvent) => {
    e.preventDefault();
    // On a phone the row is marked open first, so its subject is the named element in the picture taken before.
    if (wide) setPicked(m.id); else flushSync(() => setPicked(m.id));
    onSelect?.(m.id);
    if (!wide) {
      if (!pushed.current) { history.pushState(history.state, ''); pushed.current = true; }
      void withViewTransition(() => { setShowing(true); focus.current = 'detail'; }, { types: ['forward'] });
    }
  };
  const close = () => { setShowing(false); focus.current = open?.id ?? null; };
  // "Back to messages" closes it at once, and takes back the entry it added, which the listener below then ignores.
  const back = () => {
    void withViewTransition(close, { types: ['back'] });
    if (pushed.current) { pushed.current = false; history.back(); }
  };
  const closeRef = React.useRef(close);
  // every render: the popstate listener reads the latest close through this ref.
  React.useEffect(() => { closeRef.current = close; });
  React.useEffect(() => {
    const onPop = () => { if (pushed.current) { pushed.current = false; closeRef.current(); } };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  // On a phone, the open message's subject is one element that travels between its row and the heading, and the pane
  // that holds the list or the message slides as a step (base.css).
  const subject = (id: string, text: string) => (!wide && open?.id === id ? <span style={{ viewTransitionName: 'list-detail-subject' }}>{text}</span> : text);
  const pane = wide ? undefined : ({ viewTransitionName: 'list-detail-pane', viewTransitionClass: 'step' } as React.CSSProperties);
  const list = (
    <section aria-labelledby="messages-title" className="flex h-full min-w-0 flex-col gap-3 p-4">
      <Heading level={2} size="lg" id="messages-title">Messages ({messages.length})</Heading>
      <List divided>
        {messages.map((m) => (
          <ListItem key={m.id} title={subject(m.id, m.subject)} description={<>{m.from} · <time dateTime={m.date}>{day(m.date, locale, 'medium')}</time></>} href={`#${m.id}`}
            linkProps={{ id: `message-${m.id}` }} selected={open?.id === m.id} onClick={choose(m)} />
        ))}
      </List>
    </section>
  );
  const detail = open ? (
    <section aria-labelledby="message-title" className="flex min-w-0 flex-col gap-3 p-4">
      {wide ? null : <div><Button variant="ghost" leftIcon="arrow_back" onClick={back}>Back to messages</Button></div>}
      <Heading level={2} size="lg" id="message-title" ref={heading} tabIndex={-1} className="outline-none">{subject(open.id, open.subject)}</Heading>
      <p className="m-0 text-sm text-text-muted">From {open.from}, <time dateTime={open.date}>{day(open.date, locale, 'long')}</time></p>
      <p className="m-0 max-w-prose">{open.body}</p>
    </section>
  ) : null;

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-6xl flex-col gap-4 px-4 py-8 outline-none">
        <PageHeader title="Inbox" />
        {loadFailed ? (
          <EmptyLoadFailed title="Couldn’t load your messages" onRetry={() => onRetry?.()} headingLevel={2} />
        ) : loading ? (
          <section aria-labelledby="messages-title" className="flex min-w-0 flex-col gap-3 rounded-lg border border-border bg-surface p-4">
            <Heading level={2} size="lg" id="messages-title">Messages</Heading>
            <ul role="list" aria-busy="true" className="m-0 flex list-none flex-col gap-4 p-0">
              {/* One name for all of them: the first row is named, the others are only pictures. */}
              {[0, 1, 2, 3].map((i) => <li key={i}><Loader variant="skeleton" shape="text" size="sm" lines={2} label={i === 0 ? 'Loading messages' : ''} /></li>)}
            </ul>
          </section>
        ) : messages.length ? <div className="min-w-0 rounded-lg border border-border bg-surface">
          {wide ? (
            <Splitter defaultSize={35} min={25} max={60} separatorLabel="Resize the message list" className="h-96">
              {list}{detail}
            </Splitter>
          ) : <div style={pane}>{showing && open ? detail : list}</div>}
        </div> : (
          <EmptyState icon="inbox" title="No messages yet" headingLevel={2} variant="dashed"
            description="When someone writes to you, their message shows up here." />
        )}
      </main>
    </div>
  );
}

files.ListSearch.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Pagination } from '@diki-stwn/serupa-ds';
import { Table, TableBody, TableCell, TableHead, TableHeaderCell, TableRow, TableSelectCell, TableLoadingRows, type SortDirection } from '@diki-stwn/serupa-ds';
import { TableToolbar } from './TableToolbar';
import { EmptyLoadFailed, EmptyNoResults } from './EmptyStates';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';

/* List with search and filters: a page of rows to search, filter, sort, select and page through. For an app to
   copy. What it carries (WCAG 2.2):
   - 4.1.3: the results count ("8 of 24 projects") is a status region, read out as the search or a filter changes,
     without moving focus. Bulk actions say "3 selected" the same way (TableToolbar, TableActionBar).
   - 1.3.1, 4.1.2: the sort is on the column headers (aria-sort, a button each), the selection is real checkboxes named
     after their row, and the table has a caption.
   - 3.3.1-ish: a search that finds nothing says so in words, with the query, and offers "Clear filters", the way out.
     Clearing puts focus on the search field, since the button that was pressed goes away (2.4.3).
   - 2.4.8, 3.2.3: the search, filters, sort and page are kept in the address (`?q=&status=&sort=&page=`), so Back,
     a reload and a shared link all show the same list. Writing the address is the app's job: `onSearchChange`
     gets the new query string.
   - 4.1.3: while the rows load, the results count says "Loading projects" (once, as a status), the table is busy and
     keeps its header, and its placeholder rows are decorative, so nothing jumps when the rows arrive.
   - With no projects at all, it says there are none yet and offers New project, not "Clear filters", since nothing
     is filtered out.
   - 4.1.3, 3.3.3: a failed load says so once, in the table's place, with Try again (EmptyLoadFailed).
   - Changing the search or a filter goes back to page 1, so nobody lands on an empty page 3, and lets go of the
     selected rows it hides, so "2 selected" never counts rows nobody can see, and a bulk action never reaches them.
   - 4.1.3: Archive and Export say what they did in a toast. Archive takes the rows away at once, with Undo; it's done
     for good (onArchive) only when the toast closes without Undo. */

export interface Project { name: string; status: 'Active' | 'Paused' | 'Done'; owner: string; updated: string }
type SortKey = 'name' | 'updated';
interface View { q: string; status: string; owner: string; sort: SortKey; dir: Exclude<SortDirection, 'none'>; page: number }

export interface ListSearchProps {
  /** The rows. Default: 24 demo projects. */
  projects?: readonly Project[] | undefined;
  /** The address's query string to start from: "?q=app&status=Active&sort=updated&dir=descending&page=2". */
  search?: string | undefined;
  /** Called with the new query string whenever the view changes: write it with history.replaceState (or your router). */
  onSearchChange?: ((search: string) => void) | undefined;
  /** Rows on a page. Default: 10. */
  pageSize?: number | undefined;
  /** Archives the rows for good, by name: called once the "Archived" toast closes without Undo. */
  onArchive?: ((names: string[]) => void) | undefined;
  /** The rows failed to load: a "Couldn’t load" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** The rows are on their way: the table keeps its header, with placeholder rows, and says it's busy. Default: false. */
  loading?: boolean | undefined;
  /** Exports the selected rows, by name. */
  onExport?: ((names: string[]) => void) | undefined;
}

const OWNERS = ['Ana', 'Budi', 'Chen', 'Dewi'];
const STATUSES: Project['status'][] = ['Active', 'Paused', 'Done'];
const NAMES = ['Website redesign', 'Mobile app', 'Billing migration', 'Help center', 'Onboarding emails', 'Data export',
  'Status page', 'Search ranking', 'Invoice templates', 'Team calendar', 'Single sign-on', 'Dark theme', 'Audit log',
  'Usage reports', 'Partner portal', 'Price page', 'Referral program', 'API keys', 'Mobile push', 'Accessibility review',
  'Translations', 'Release notes', 'Support chat', 'Backup restore'];
const demo: Project[] = NAMES.map((name, i) => ({
  name, status: STATUSES[i % 3] ?? 'Active', owner: OWNERS[(i * 3) % 4] ?? '',
  updated: new Date(Date.UTC(2026, 9, 28 - i)).toISOString().slice(0, 10),
}));

// "6 Nov 2026" in the reader's locale for "2026-11-06", read as that calendar day wherever the reader is; anything
// else as it came. The <time> keeps the ISO day in dateTime.
function shortDay(iso: string, locale: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return iso;
  try { return new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }).format(new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]))); } catch { return iso; }
}

/** The view from a query string, with anything missing or unknown at its default. */
export function readView(search: string): View {
  const p = new URLSearchParams(search);
  const page = Number(p.get('page'));
  return {
    q: p.get('q') ?? '', status: p.get('status') ?? '', owner: p.get('owner') ?? '',
    sort: p.get('sort') === 'updated' ? 'updated' : 'name',
    dir: p.get('dir') === 'descending' ? 'descending' : 'ascending',
    page: Number.isInteger(page) && page > 0 ? page : 1,
  };
}
/** The query string for a view, leaving out what's at its default, so a plain list has a plain address. */
export function writeView(v: View): string {
  const p = new URLSearchParams();
  if (v.q) p.set('q', v.q);
  if (v.status) p.set('status', v.status);
  if (v.owner) p.set('owner', v.owner);
  if (v.sort !== 'name') p.set('sort', v.sort);
  if (v.dir !== 'ascending') p.set('dir', v.dir);
  if (v.page > 1) p.set('page', String(v.page));
  const s = p.toString();
  return s ? `?${s}` : '';
}

/** The list page: a skip link, a header, then main with the h1, the search and filters, the table and the pages. */
export function ListSearch({ projects = demo, search = '', onSearchChange, pageSize = 10, onArchive, onExport, loading = false, loadFailed = false, onRetry }: ListSearchProps) {
  const locale = useLocale();
  const [view, setView] = React.useState<View>(() => readView(search));
  const [picked, setPicked] = React.useState<string[]>([]);
  const [archived, setArchived] = React.useState<ReadonlySet<string>>(() => new Set());
  const matches = (v: View) => {
    const q = v.q.trim().toLowerCase();
    return projects.filter((p) => !archived.has(p.name) && (!q || p.name.toLowerCase().includes(q)) && (!v.status || p.status === v.status) && (!v.owner || p.owner === v.owner));
  };
  const change = (next: Partial<View>, keepPage = false) => {
    const v = { ...view, ...next, page: keepPage ? next.page ?? view.page : 1 };
    setView(v);
    onSearchChange?.(writeView(v));
    // A narrower search or filter lets go of the selected rows it hides.
    if (v.q !== view.q || v.status !== view.status || v.owner !== view.owner) {
      const shown = new Set(matches(v).map((p) => p.name));
      setPicked((was) => was.filter((n) => shown.has(n)));
    }
  };
  const count = (n: number) => (n === 1 ? '1 project' : `${n} projects`);
  const archive = () => {
    const names = picked;
    setArchived((was) => new Set([...was, ...names]));
    setPicked([]);
    toast.undo({
      title: `Archived ${count(names.length)}`,
      commit: () => onArchive?.(names),
      onUndo: () => setArchived((was) => { const n = new Set(was); for (const x of names) n.delete(x); return n; }),
    });
  };
  const exportRows = () => {
    onExport?.(picked);
    toast({ title: `Exported ${count(picked.length)}`, tone: 'success' });
  };

  const live = projects.length - archived.size;
  const found = matches(view)
    .sort((a, b) => (view.dir === 'ascending' ? 1 : -1) * a[view.sort].localeCompare(b[view.sort]));
  const pages = Math.max(1, Math.ceil(found.length / pageSize));
  const page = Math.min(view.page, pages);
  const rows = found.slice((page - 1) * pageSize, page * pageSize);
  const all = rows.length > 0 && rows.every((p) => picked.includes(p.name));
  const toggle = (n: string) => setPicked(picked.includes(n) ? picked.filter((x) => x !== n) : [...picked, n]);
  const sortBy = (key: SortKey) => change({ sort: key, dir: view.sort === key && view.dir === 'ascending' ? 'descending' : 'ascending' });
  const dir = (key: SortKey): SortDirection => (view.sort === key ? view.dir : 'none');
  const clear = () => change({ q: '', status: '', owner: '' });

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-5xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Projects" primary={{ label: 'New project', href: '#new-project' }} />
        <TableToolbar
          noun="projects"
          query={view.q}
          onQueryChange={(value) => change({ q: value })}
          filters={[
            { label: 'Status', value: view.status, onChange: (value) => change({ status: value }), options: [{ value: '', label: 'All' }, ...STATUSES] },
            { label: 'Owner', value: view.owner, onChange: (value) => change({ owner: value }), options: [{ value: '', label: 'Anyone' }, ...OWNERS] },
          ]}
          results={loadFailed ? '' : loading ? 'Loading projects' : found.length === live ? `${found.length} projects` : `${found.length} of ${live} projects`}
          onClearFilters={clear}
          selectedCount={picked.length}
          onClearSelection={() => setPicked([])}
          bulkActions={<><Button size="sm" variant="outline" onClick={exportRows}>Export</Button><Button size="sm" variant="outline" onClick={archive}>Archive</Button></>}
        >
          {loadFailed ? (
            <EmptyLoadFailed title="Couldn’t load projects" onRetry={() => onRetry?.()} headingLevel={2} />
          ) : loading ? (
            // The header stays, so the columns don't move when the rows arrive; the placeholder rows are decorative.
            <Table caption="Projects" hideCaption loading>
              <TableHead><TableRow>
                <TableHeaderCell><span className="sr-only">Select</span></TableHeaderCell>
                <TableHeaderCell>Name</TableHeaderCell><TableHeaderCell>Status</TableHeaderCell>
                <TableHeaderCell>Owner</TableHeaderCell><TableHeaderCell>Updated</TableHeaderCell>
              </TableRow></TableHead>
              <TableLoadingRows columns={5} rows={Math.min(pageSize, 5)} label="" />
            </Table>
          ) : found.length ? (
            <Table caption="Projects" hideCaption>
              <TableHead><TableRow>
                <TableSelectCell header label="Select all projects on this page" checked={all}
                  indeterminate={!all && rows.some((p) => picked.includes(p.name))}
                  onChange={() => setPicked(all ? picked.filter((n) => !rows.some((p) => p.name === n)) : [...new Set([...picked, ...rows.map((p) => p.name)])])} />
                <TableHeaderCell sort={dir('name')} onSort={() => sortBy('name')}>Name</TableHeaderCell>
                <TableHeaderCell>Status</TableHeaderCell>
                <TableHeaderCell>Owner</TableHeaderCell>
                <TableHeaderCell sort={dir('updated')} onSort={() => sortBy('updated')}>Updated</TableHeaderCell>
              </TableRow></TableHead>
              <TableBody>{rows.map((p) => (
                <TableRow key={p.name} selected={picked.includes(p.name)}>
                  <TableSelectCell label={`Select ${p.name}`} checked={picked.includes(p.name)} onChange={() => toggle(p.name)} />
                  <TableCell>{p.name}</TableCell><TableCell>{p.status}</TableCell><TableCell>{p.owner}</TableCell>
                  <TableCell><time dateTime={p.updated}>{shortDay(p.updated, locale)}</time></TableCell>
                </TableRow>
              ))}</TableBody>
            </Table>
          ) : !projects.length ? (
            // No projects at all is a first visit, not a search that missed: there's no filter to clear.
            <EmptyState icon="add_circle" title="No projects yet" headingLevel={2}
              description="A project holds the tasks, files and people for one piece of work. Start one, and it shows up here."
              actions={<Button href="#new-project">New project</Button>} />
          ) : (
            <EmptyNoResults query={view.q} title={(text) => (text ? `No projects match “${text}”` : 'No projects match these filters')}
              description="Check the spelling, or clear the filters to see every project." headingLevel={2} onClearFilters={() => {
              clear();
              document.querySelector<HTMLInputElement>('main form[role="search"] input')?.focus();
            }} />
          )}
        </TableToolbar>
        {!loading && !loadFailed && pages > 1 ? (
          <Pagination count={pages} page={page} onPageChange={(n) => change({ page: n }, true)} total={found.length} pageSize={pageSize}
            aria-label="Projects pages" />
        ) : null}
      </main>
      <Toaster />
    </div>
  );
}

files.MultiStepForm.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Stepper } from '@diki-stwn/serupa-ds';
import { useSteps } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';

/* Multi-step form: an application for a business account in three steps of questions and a step that shows every
   answer before it's sent, then what happens next. For an app to copy. What it carries (WCAG 2.2):
   - 3.3.7: every step stays rendered (useSteps), so Back, the Stepper and "Change" keep every answer. Where the
     cards go is the business address unless that's unticked, so nobody types the same address twice.
   - 3.2.6: "Need help?" is in the same place, after the step, on every step, the review and the confirmation.
   - 3.3.1, 3.3.3: Continue checks the step. An ErrorSummary takes focus and links to each field, each saying what
     to write. The Stepper marks a step with a problem in words.
   - 3.3.4: nothing is sent until "Send application", after every answer is shown with a way to change it. A change
     made from there comes back to the answers, checked again on the way.
   - Email addresses and phone numbers are isolated left to right, so a right-to-left page doesn't reverse them.
   - 2.4.3, 4.1.3: each new step puts focus on its heading, so the change is said and Tab goes on from there.
   Sending is the app's job: onSubmit stands in for it. */

export type BusinessType = 'sole' | 'company' | 'partnership';
export interface Application {
  business: string; type: BusinessType | ''; registration: string;
  line1: string; line2: string; city: string; postcode: string; country: string;
  name: string; role: string; email: string; phone: string;
  /** Post the cards to the business address. Unticked, the card address fields are asked for. */
  sameAddress: boolean;
  cardLine1: string; cardLine2: string; cardCity: string; cardPostcode: string; cardCountry: string;
  currency: string; payments: 'few' | 'some' | 'many' | ''; cards: number;
}

export interface MultiStepFormProps {
  /** Answers already known, such as a saved draft or the signed-in person's details. */
  initial?: Partial<Application> | undefined;
  /** The step it opens on, from 0; 3 is the review. Every step before it needs good answers in `initial`. */
  start?: number | undefined;
  /** Opens on the review saying the application wasn't sent. Needs every answer in `initial`. */
  failed?: boolean | undefined;
  /** Opens on the confirmation, as after sending. Needs every answer in `initial`. */
  sent?: boolean | undefined;
  /** Sends the application. A rejected promise keeps the review and says it wasn't sent. */
  onSubmit?: ((answers: Application) => unknown) | undefined;
}

const EMPTY: Application = {
  business: '', type: '', registration: '', line1: '', line2: '', city: '', postcode: '', country: '',
  name: '', role: '', email: '', phone: '', sameAddress: true,
  cardLine1: '', cardLine2: '', cardCity: '', cardPostcode: '', cardCountry: '',
  currency: 'IDR', payments: '', cards: 1,
};
const COUNTRIES = [
  { value: 'ID', label: 'Indonesia' }, { value: 'MY', label: 'Malaysia' }, { value: 'PH', label: 'Philippines' },
  { value: 'SG', label: 'Singapore' }, { value: 'TH', label: 'Thailand' }, { value: 'VN', label: 'Vietnam' },
];
const CURRENCIES = [{ value: 'IDR', label: 'Indonesian rupiah (IDR)' }, { value: 'SGD', label: 'Singapore dollar (SGD)' }, { value: 'USD', label: 'US dollar (USD)' }];
const TYPES: Record<BusinessType, string> = { sole: 'Sole trader', company: 'Limited company', partnership: 'Partnership' };
const PAYMENTS = { few: 'Fewer than 50 a month', some: '50 to 500 a month', many: 'More than 500 a month' } as const;
const STEPS = [{ title: 'Your business' }, { title: 'Contact person' }, { title: 'The account' }, { title: 'Check your answers' }];
const REVIEW = STEPS.length - 1;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const id = (k: keyof Application) => `apply-${k}`;
const need = (a: Application, k: keyof Application, message: string, out: ErrorSummaryItem[]) => { if (!String(a[k]).trim()) out.push({ field: id(k), message }); };

/** What's wrong with a step's answers, in the order of its fields. The review step has none of its own. */
export function stepProblems(step: number, a: Application): ErrorSummaryItem[] {
  const out: ErrorSummaryItem[] = [];
  if (step === 0) {
    need(a, 'business', 'Enter the business’s name, as it’s registered', out);
    if (!a.type) out.push({ field: 'apply-type-sole', message: 'Choose what kind of business it is' });
    if (a.type === 'company') {
      if (!a.registration.trim()) out.push({ field: id('registration'), message: 'Enter the company’s registration number' });
      else if (!/^[A-Z0-9-]{6,20}$/i.test(a.registration.replace(/\s/g, ''))) out.push({ field: id('registration'), message: 'Enter the registration number as it is on the certificate: 6 to 20 letters and numbers' });
    }
    need(a, 'line1', 'Enter the first line of the business address', out);
    need(a, 'city', 'Enter the town or city', out);
    need(a, 'postcode', 'Enter the postcode', out);
    need(a, 'country', 'Choose the country', out);
  } else if (step === 1) {
    need(a, 'name', 'Enter the contact person’s full name', out);
    if (!a.email.trim()) out.push({ field: id('email'), message: 'Enter an email address' });
    else if (!EMAIL.test(a.email.trim())) out.push({ field: id('email'), message: 'Enter an email address like name@example.com' });
    need(a, 'phone', 'Enter a phone number, for when we need to check something quickly', out);
    if (!a.sameAddress) {
      need(a, 'cardLine1', 'Enter the first line of the address for the cards', out);
      need(a, 'cardCity', 'Enter the town or city for the cards', out);
      need(a, 'cardPostcode', 'Enter the postcode for the cards', out);
      need(a, 'cardCountry', 'Choose the country for the cards', out);
    }
  } else if (step === 2) {
    if (!a.payments) out.push({ field: 'apply-payments-few', message: 'Choose about how many payments the business makes a month' });
    if (!(a.cards >= 1 && a.cards <= 20)) out.push({ field: id('cards'), message: 'Enter how many debit cards you need, from 1 to 20' });
  }
  return out;
}

type Part = { step: number; title: string; what: string; items: (readonly [term: string, value: React.ReactNode])[] };
const country = (v: string) => COUNTRIES.find((c) => c.value === v)?.label || v;
const address = (...parts: string[]) => parts.filter((p) => p.trim()).join('\n');

/** The application page: a skip link, then main with the Stepper, the step, and help in the same place on every step. */
export function MultiStepForm({ initial, start = 0, failed: startFailed, sent: startSent, onSubmit }: MultiStepFormProps) {
  const [a, setA] = React.useState<Application>(() => ({ ...EMPTY, ...initial }));
  const [errors, setErrors] = React.useState<Record<number, ErrorSummaryItem[]>>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(!!startFailed);
  const [sent, setSent] = React.useState(!!startSent);
  const done = React.useRef<HTMLHeadingElement>(null);
  const send = () => {
    setBusy(true);
    setFailed(false);
    Promise.resolve().then(() => onSubmit?.(a))
      .then(() => setSent(true), () => setFailed(true))
      .finally(() => setBusy(false));
  };
  const s = useSteps({
    steps: STEPS,
    defaultStep: startFailed ? REVIEW : start,
    validate: (i) => {
      const found = stepProblems(i, a);
      setErrors((e) => ({ ...e, [i]: found }));
      if (found.length) setTries((t) => t + 1);
      return !found.length;
    },
    onComplete: send,
  });
  // Once the answers have been shown, a step opened with "Change" goes back to them instead of on to the next step.
  const [reviewed, setReviewed] = React.useState(s.current === REVIEW);
  if (s.current === REVIEW && !reviewed) setReviewed(true);
  const first = React.useRef(true);
  React.useEffect(() => { if (sent && !first.current) done.current?.focus(); first.current = false; }, [sent]);

  const set = <K extends keyof Application>(k: K) => (v: Application[K]) => setA((o) => ({ ...o, [k]: v }));
  const fieldError = (step: number, k: string) => errors[step]?.find((e) => e.field === k)?.message;
  const text = (step: number, k: keyof Application, label: string, autoComplete: string, more: Partial<React.ComponentProps<typeof Input>> = {}, hint?: string, optional?: boolean) => (
    <Field label={label} hint={hint} optional={optional} error={fieldError(step, id(k))}>
      <Input id={id(k)} name={k} autoComplete={autoComplete} value={String(a[k])} onChange={(e) => set(k)(e.target.value)} {...more} />
    </Field>
  );
  const summary = (step: number) => (errors[step]?.length ? <ErrorSummary key={tries} errors={errors[step]} headingLevel={3} /> : null);
  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (busy) return;
    if (reviewed && s.current < REVIEW) void s.goTo(REVIEW); else void s.next();
  };
  const change = (step: number, what: string) => (
    <Button variant="secondary" size="sm" onClick={() => void s.goTo(step)} aria-label={`Change ${what}`} disabled={busy} disabledReason={busy ? 'Your application is being sent' : undefined}>Change</Button>
  );
  const nav = (
    <div className="flex flex-wrap gap-3">
      <Button type="submit" loading={busy} loadingLabel="Sending your application">
        {s.isLast ? (failed ? 'Try sending again' : 'Send application') : reviewed ? 'Save and go back to your answers' : 'Continue'}
      </Button>
      {s.isFirst ? null : <Button variant="ghost" onClick={s.back} disabled={busy}>Back</Button>}
    </div>
  );
  const h2 = (i: number) => <Heading level={2} size="xl" {...s.headingProps(i)} className="outline-none">{STEPS[i]?.title}</Heading>;

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-3xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Open a business account" />
        <Stepper {...s.stepperProps} current={sent ? STEPS.length : s.current} onStepClick={sent || busy ? undefined : s.stepperProps.onStepClick} size="sm" aria-label="Application steps" />
        {sent ? (
          <Card className="flex flex-col gap-4">
            <Heading level={2} size="xl" ref={done} tabIndex={-1} className="outline-none">Application sent</Heading>
            <p className="m-0 wrap-anywhere">We’ve emailed a copy to <bdi dir="ltr">{a.email}</bdi>. Your reference is <strong>BA-20418</strong>.</p>
            <Heading level={3} size="base">What happens next</Heading>
            <ol className="m-0 flex list-decimal flex-col gap-1 ps-5">
              <li>We check the details, usually within 2 working days. We call {a.name || 'you'} if anything is missing.</li>
              <li>Once it’s open, we email the account number and how to sign in.</li>
              <li>The {a.cards === 1 ? 'card arrives' : 'cards arrive'} by post within 7 working days.</li>
            </ol>
            <Link href="#home">Go to the home page</Link>
          </Card>
        ) : (
          <form noValidate onSubmit={submit}>
            <Card className="flex flex-col gap-5">
              <section {...s.panelProps(0)} className="flex flex-col gap-4">
                {h2(0)}
                {summary(0)}
                {text(0, 'business', 'Business name', 'organization', {}, 'As it’s registered, or your own name for a sole trader.')}
                <Field label="Type of business" group error={fieldError(0, 'apply-type-sole')}>
                  <RadioGroup name="type" value={a.type} onValueChange={(v) => set('type')(v)} invalid={!!fieldError(0, 'apply-type-sole')}>
                    <Radio id="apply-type-sole" value="sole" description="One person runs it and is the business.">{TYPES.sole}</Radio>
                    <Radio value="company" description="Registered with its own registration number.">{TYPES.company}</Radio>
                    <Radio value="partnership" description="Two or more people run it together.">{TYPES.partnership}</Radio>
                  </RadioGroup>
                </Field>
                {a.type === 'company' ? text(0, 'registration', 'Company registration number', 'off', { spellCheck: false, autoCapitalize: 'characters', className: 'max-w-64' }, 'On the certificate of registration, like 8120001234567.') : null}
                <Heading level={3} size="base">Business address</Heading>
                {text(0, 'line1', 'Address line 1', 'address-line1')}
                {text(0, 'line2', 'Address line 2', 'address-line2', {}, undefined, true)}
                <div className="grid gap-4 sm:grid-cols-2">
                  {text(0, 'city', 'Town or city', 'address-level2')}
                  {text(0, 'postcode', 'Postcode', 'postal-code', { className: 'max-w-48' })}
                </div>
                <Field label="Country" error={fieldError(0, id('country'))}>
                  <Select id={id('country')} name="country" autoComplete="country" value={a.country} onChange={(e) => set('country')(e.target.value)} placeholder="Choose a country" options={COUNTRIES} />
                </Field>
              </section>

              <section {...s.panelProps(1)} className="flex flex-col gap-4">
                {h2(1)}
                {summary(1)}
                <p className="m-0">The person we contact about the account. They can sign in once it’s open.</p>
                {text(1, 'name', 'Full name', 'name')}
                {text(1, 'role', 'Role in the business', 'organization-title', {}, 'Such as owner, director or finance manager.', true)}
                {text(1, 'email', 'Email', 'email', { type: 'email', spellCheck: false, autoCapitalize: 'none' }, 'We send the account details here.')}
                {text(1, 'phone', 'Phone', 'tel', { type: 'tel', className: 'max-w-64' }, 'Only for when we need to check something quickly.')}
                <Heading level={3} size="base">Where to post the cards</Heading>
                <Checkbox id={id('sameAddress')} checked={a.sameAddress} onCheckedChange={set('sameAddress')}
                  description={a.line1 ? [a.line1, a.city].filter((p) => p.trim()).join(', ') : undefined}>
                  Post the cards to the business address
                </Checkbox>
                {a.sameAddress ? null : (
                  <>
                    {text(1, 'cardLine1', 'Address line 1', 'shipping address-line1')}
                    {text(1, 'cardLine2', 'Address line 2', 'shipping address-line2', {}, undefined, true)}
                    <div className="grid gap-4 sm:grid-cols-2">
                      {text(1, 'cardCity', 'Town or city', 'shipping address-level2')}
                      {text(1, 'cardPostcode', 'Postcode', 'shipping postal-code', { className: 'max-w-48' })}
                    </div>
                    <Field label="Country" error={fieldError(1, id('cardCountry'))}>
                      <Select id={id('cardCountry')} name="cardCountry" autoComplete="shipping country" value={a.cardCountry} onChange={(e) => set('cardCountry')(e.target.value)} placeholder="Choose a country" options={COUNTRIES} />
                    </Field>
                  </>
                )}
              </section>

              <section {...s.panelProps(2)} className="flex flex-col gap-4">
                {h2(2)}
                {summary(2)}
                <Field label="Currency" hint="The account holds money in this currency. You can add others once it’s open.">
                  <Select id={id('currency')} name="currency" value={a.currency} onChange={(e) => set('currency')(e.target.value)} options={CURRENCIES} />
                </Field>
                <Field label="About how many payments will the business make?" group error={fieldError(2, 'apply-payments-few')}>
                  <RadioGroup name="payments" value={a.payments} onValueChange={(v) => set('payments')(v)} invalid={!!fieldError(2, 'apply-payments-few')}>
                    <Radio id="apply-payments-few" value="few">{PAYMENTS.few}</Radio>
                    <Radio value="some">{PAYMENTS.some}</Radio>
                    <Radio value="many">{PAYMENTS.many}</Radio>
                  </RadioGroup>
                </Field>
                <Field label="Debit cards" hint="One for each person who pays for things, up to 20." error={fieldError(2, id('cards'))}>
                  <NumberInput id={id('cards')} name="cards" min={1} max={20} value={a.cards} onValueChange={(v) => set('cards')(v ?? 0)} className="max-w-40" />
                </Field>
              </section>

              <section {...s.panelProps(REVIEW)} className="flex flex-col gap-4">
                {h2(REVIEW)}
                <p className="m-0">Nothing is sent until you send the application.</p>
                {failed ? <Alert tone="danger" title="Your application wasn’t sent">Nothing you entered is lost. Check your connection and send it again.</Alert> : null}
                {([
                  { step: 0, title: 'Your business', what: 'your business’s details', items: [
                    ['Business name', a.business], ['Type of business', a.type ? TYPES[a.type] : ''],
                    ...(a.type === 'company' ? [['Registration number', a.registration] as const] : []),
                    ['Address', address(a.line1, a.line2, a.city, a.postcode, country(a.country))],
                  ] },
                  { step: 1, title: 'Contact person', what: 'the contact person', items: [
                    ['Name', a.role ? `${a.name}, ${a.role}` : a.name], ['Email', <bdi dir="ltr">{a.email}</bdi>], ['Phone', <bdi dir="ltr" className="whitespace-nowrap">{a.phone}</bdi>],
                    ['Cards posted to', a.sameAddress ? 'The business address' : address(a.cardLine1, a.cardLine2, a.cardCity, a.cardPostcode, country(a.cardCountry))],
                  ] },
                  { step: 2, title: 'The account', what: 'the account', items: [
                    ['Currency', CURRENCIES.find((c) => c.value === a.currency)?.label || a.currency],
                    ['Payments', a.payments ? PAYMENTS[a.payments] : ''], ['Debit cards', String(a.cards)],
                  ] },
                ] satisfies Part[]).map((part) => (
                  <div key={part.step} className="flex flex-col gap-2 border-t border-border pt-4">
                    <div className="flex flex-wrap items-center justify-between gap-3">
                      <Heading level={3} size="base">{part.title}</Heading>
                      {change(part.step, part.what)}
                    </div>
                    <DescriptionList className="text-sm">
                      {part.items.map(([term, value]) => <DescriptionItem key={term} term={term}><span className="whitespace-pre-line wrap-anywhere">{value}</span></DescriptionItem>)}
                    </DescriptionList>
                  </div>
                ))}
              </section>
              {nav}
            </Card>
          </form>
        )}
        {/* The same help, in the same place, on every step (3.2.6). */}
        <aside aria-labelledby="apply-help" className="flex flex-col gap-1 text-sm">
          <Heading level={2} id="apply-help" size="base">Need help?</Heading>
          <p className="m-0">Call <Link href="tel:+62215550100">+62 21 555 0100</Link>, Monday to Friday, 8 am to 6 pm, or <Link href="#chat">chat with us</Link>.</p>
        </aside>
      </main>
    </div>
  );
}

