'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { List, ListItem } from '@diki-stwn/serupa-ds';
import { Navbar, NavbarLink } from '@diki-stwn/serupa-ds';
import { NotificationCenter, type NotificationItem } from '@diki-stwn/serupa-ds';
import { RelativeTime } from '@diki-stwn/serupa-ds';
import { SegmentedControl } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { PageHeader } from './PageHeader';

/* Notifications: a bell in the Navbar that opens the recent ones in a drawer, and a full inbox page with a filter,
   mark as read and mark all as read. Both read the same list. For an app to copy. What it carries (WCAG 2.2):
   - 4.1.2, 1.3.1: the bell is named with its count ("Notifications, 3 unread"), so the number is heard, not only seen.
   - 1.4.1: an unread notification says "Unread" in words, besides the dot before it and its bolder title, which
     are what make it stand out at a glance (the same dot and weight as the drawer's).
   - 4.1.3, 3.3.3: a failed load says so once, in the list's place, with Try again (EmptyLoadFailed).
   - 4.1.3: while they load, the count says "Loading notifications" and the list is busy, with placeholder rows.
   - 4.1.3: the count above the list is a status, so marking one read or changing the filter is said politely.
   - 2.4.3: marking one read on the page takes its button away (and, under "Unread", the notification too), so focus
     goes to the next unread one's button, or the heading when none are left; after Mark all as read it goes to the
     heading. Never to the top of the page. In the drawer, focus stays in the drawer.
   - People choose what interrupts them: "Notification settings" sits by the heading (in More actions on a phone), and the empty state links there
     too (the Ethical design rule: turning notifications off takes no more steps than turning them on).
   Storing what's read is the app's job: onMarkRead and onMarkAllRead hear it. */

export interface NotificationsProps {
  /** The notifications, newest first. Default: a demo account's. */
  items?: readonly NotificationItem[] | undefined;
  /** One was marked read. */
  onMarkRead?: ((id: string) => void) | undefined;
  /** All were marked read. */
  onMarkAllRead?: (() => void) | undefined;
  /** The notifications failed to load: a "Couldn’t load" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** The notifications are on their way: placeholder rows, and the count says "Loading notifications". Default: false. */
  loading?: boolean | undefined;
  /** Where "Notification settings" leads: the page where people choose which notifications they get. Default: "#settings-notifications". */
  settingsHref?: string | undefined;
}

// Times are minutes before the page loaded, so they read the same whenever the page is drawn.
const now = Date.now();
const ago = (minutes: number) => now - minutes * 60_000;
const demo: NotificationItem[] = [
  { id: 'n1', title: 'Ana Lima mentioned you in Website redesign', description: '“Can you check the new pricing copy?”', tone: 'info', time: ago(5) },
  { id: 'n2', title: 'Your export is ready', description: 'projects-october.csv, 2.4 MB', tone: 'success', time: ago(42) },
  { id: 'n3', title: 'A payment failed', description: 'The card ending 4242 was declined. Update it to keep your plan.', tone: 'danger', time: ago(180) },
  { id: 'n4', title: 'Budi Santoso joined the team', tone: 'info', time: ago(60 * 20), read: true },
  { id: 'n5', title: 'Storage is almost full', description: '8.6 GB of 10 GB used.', tone: 'warning', time: ago(60 * 23), read: true },
];

type Filter = 'all' | 'unread';

/** The notifications page: a skip link, a Navbar with the bell, then main with the inbox. */
export function Notifications({ items = demo, onMarkRead, onMarkAllRead, settingsHref = '#settings-notifications', loading = false, loadFailed = false, onRetry }: NotificationsProps) {
  // Marked read here, on top of what the items say, so items that arrive later (after loading) keep their own.
  const [read, setRead] = React.useState<ReadonlySet<string>>(() => new Set());
  const [filter, setFilter] = React.useState<Filter>('all');
  const [open, setOpen] = React.useState(false);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const focusTo = React.useRef<string | null>(null);
  const all = items.map((n) => ({ ...n, read: !!n.read || read.has(n.id) }));
  const unread = all.filter((n) => !n.read).length;
  const shown = filter === 'unread' ? all.filter((n) => !n.read) : all;

  // every render: a focus asked for by a handler (focusTo) moves once the render it caused is on screen.
  React.useEffect(() => {
    const to = focusTo.current;
    focusTo.current = null;
    if (to === 'heading') heading.current?.focus();
    else if (to) document.getElementById(`read-${to}`)?.focus();
  });

  // onPage: pressed on the page, whose button goes away with it; the drawer keeps focus itself.
  const markRead = (id: string, onPage?: boolean) => {
    if (onPage) {
      const at = shown.findIndex((n) => n.id === id);
      const next = shown.slice(at + 1).find((n) => !n.read) || shown.slice(0, at).reverse().find((n) => !n.read);
      focusTo.current = next ? next.id : 'heading';
    }
    setRead((r) => new Set(r).add(id));
    onMarkRead?.(id);
  };
  const markAll = (onPage?: boolean) => {
    if (onPage) focusTo.current = 'heading';
    setRead(new Set(items.map((n) => n.id)));
    onMarkAllRead?.();
  };
  const bellName = unread ? `Notifications, ${unread} unread` : 'Notifications';

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <Navbar brand="Acme" actions={
        <Button variant="ghost" leftIcon="notifications" aria-label={bellName} onClick={() => setOpen(true)}>
          {unread ? <Badge count={unread} /> : null}
        </Button>
      }>
        <NavbarLink href="#dashboard">Dashboard</NavbarLink>
        <NavbarLink href="#projects">Projects</NavbarLink>
        <NavbarLink href="#notifications" active>Notifications</NavbarLink>
      </Navbar>
      <NotificationCenter items={all.slice(0, 5)} open={open} onOpenChange={setOpen} onMarkRead={(id) => markRead(id)} onMarkAllRead={() => markAll()} />

      <main id="main" className="mx-auto flex max-w-3xl flex-col gap-4 px-4 py-8 outline-none">
        <PageHeader title="Notifications" headingRef={heading}
          primary={{ label: 'Mark all as read', disabled: loading || loadFailed || !unread, onSelect: () => markAll(true) }}
          secondary={[{ label: 'Notification settings', icon: 'settings', href: settingsHref }]} />
        <div className="flex flex-wrap items-center justify-between gap-3">
          <SegmentedControl aria-label="Show" value={filter} onValueChange={setFilter}
            options={[{ value: 'all', label: 'All' }, { value: 'unread', label: 'Unread' }]} />
          <p role="status" className="m-0 text-sm text-text-muted">{loadFailed ? '' : loading ? 'Loading notifications' : unread ? `${unread} unread` : 'All caught up'}</p>
        </div>
        {loadFailed ? (
          <EmptyLoadFailed title="Couldn’t load your notifications" onRetry={() => onRetry?.()} headingLevel={2} />
        ) : loading ? (
          // Placeholder rows the shape of a notification; the status above says it's loading, so they're pictures only.
          <ul role="list" aria-busy="true" aria-label="All notifications" className="m-0 flex list-none flex-col gap-4 rounded-lg border border-border bg-surface p-4">
            {[0, 1, 2].map((i) => <li key={i}><Loader variant="skeleton" shape="text" size="sm" lines={2} label="" /></li>)}
          </ul>
        ) : !items.length ? (
          <EmptyState icon="notifications" title="No notifications yet" headingLevel={2} variant="dashed"
            description="When someone mentions you, an export finishes or a payment needs you, it shows up here."
            actions={<Button variant="outline" leftIcon="settings" href={settingsHref}>Choose what you hear about</Button>} />
        ) : shown.length ? (
          <List variant="card" divided aria-label={filter === 'unread' ? 'Unread notifications' : 'All notifications'}>
            {shown.map((n) => (
              <ListItem key={n.id}
                // The drawer's unread dot before the title (and room for it on read ones, so the titles line up).
                title={<span className="flex items-baseline gap-2"><span className={'dk-notification-center__dot self-center' + (n.read ? ' invisible' : '')} aria-hidden="true" /><span className={n.read ? undefined : 'font-semibold'}>{n.title}</span></span>}
                description={<>{n.description ? <>{n.description} · </> : null}<RelativeTime date={n.time ?? now} />{n.read ? null : <> · Unread</>}</>}
                trailing={n.read ? null : <Button id={`read-${n.id}`} size="sm" variant="ghost" aria-label={typeof n.title === 'string' ? `Mark as read: ${n.title}` : undefined} onClick={() => markRead(n.id, true)}>Mark as read</Button>} />
            ))}
          </List>
        ) : (
          <p className="m-0 rounded-lg border border-border bg-surface p-6 text-center text-text-muted">No unread notifications. You’re all caught up.</p>
        )}
      </main>
    </div>
  );
}

files.Onboarding.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Progress } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';

/* Onboarding / first run: the first page a new account sees. A checklist of setup steps with how far along it
   is, an empty state that says what to do first, and progress that's kept between visits. For an app to copy.
   What it carries (WCAG 2.2):
   - 1.3.1 in Safari: role="list" on the lists without bullets, since WebKit stops calling them lists.
   - 1.3.1: the steps are an ordered list, each a heading (h3 under the checklist's h2), so a screen reader can list
     and jump between them, and hears "1 of 4".
   - 1.4.10: a long title or a URL in a description wraps inside its card at 320 px, not past it.
   - 1.4.1: a done step says "Done" in words beside its tick, not by color or a strike-through alone.
   - 4.1.3: ticking a step says the new count ("2 of 4 steps done") politely, without moving focus. The last tick says
     "You're all set" once, and the page shows what's next.
   - 2.4.3: hiding the checklist moves focus to "Show the checklist", which takes its place; showing it again moves
     focus to the checklist's heading, so focus never drops to the page's start.
   - Progress and the hidden choice are kept between visits (here in localStorage under
     `saveKey`; an app keeps them on its server with `onChange`), so nobody is asked to do a step twice.
   Doing each step (the pages its link opens) is the app's job; here the links go nowhere. */

export interface SetupStep {
  id: string;
  /** What to do, as a short command: "Invite your team". */
  title: string;
  /** Why, in a sentence. */
  description: string;
  /** Where the step is done. */
  action: { label: string; href: string };
}

export interface OnboardingState {
  /** The ids of the steps that are done. */
  done: string[];
  /** The checklist is folded away. */
  hidden: boolean;
}

export interface OnboardingProps {
  /** The person's first name, for the welcome. */
  name?: string | undefined;
  /** The setup steps, in order. Default: four steps for the demo workspace. */
  steps?: readonly SetupStep[] | undefined;
  /** Where it starts when nothing is saved yet. Default: nothing done, shown. */
  initial?: Partial<OnboardingState> | undefined;
  /** Keeps the state in localStorage under this key, so a reload or a later visit picks up where it was. */
  saveKey?: string | undefined;
  /** Called with each new state: save it on your server. */
  onChange?: ((state: OnboardingState) => void) | undefined;
  /** Where "Go to your dashboard" goes once every step is done. Default: "#dashboard". */
  dashboardHref?: string | undefined;
}

const demoSteps: SetupStep[] = [
  { id: 'profile', title: 'Add your photo and job title', description: 'Your team sees them next to everything you write.', action: { label: 'Edit your profile', href: '#profile' } },
  { id: 'team', title: 'Invite your team', description: 'Projects are more use with the people you work with.', action: { label: 'Invite people', href: '#invite' } },
  { id: 'project', title: 'Create your first project', description: 'A project holds tasks, files and the talk about them.', action: { label: 'Create a project', href: '#new-project' } },
  { id: 'notifications', title: 'Choose your notifications', description: 'Pick what reaches you by email and what waits in the app.', action: { label: 'Open notification settings', href: '#notifications' } },
];

function load(key: string | undefined): Partial<OnboardingState> | null {
  if (!key) return null;
  try {
    const raw = window.localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as Partial<OnboardingState>) : null;
  } catch { return null; }
}
function save(key: string | undefined, state: OnboardingState) {
  if (!key) return;
  try { window.localStorage.setItem(key, JSON.stringify(state)); } catch { /* private mode or full: keeping it is a nicety */ }
}

/** The first-run page: a skip link, a header, then main with the welcome, the setup checklist and an empty project list. */
export function Onboarding({ name = 'Ada', steps = demoSteps, initial, saveKey, onChange, dashboardHref = '#dashboard' }: OnboardingProps) {
  const [state, setState] = React.useState<OnboardingState>(() => {
    const saved = load(saveKey) ?? initial ?? {};
    const ids = new Set(steps.map((s) => s.id));
    return { done: (saved.done ?? []).filter((id) => ids.has(id)), hidden: saved.hidden ?? false };
  });
  const update = (next: OnboardingState) => { setState(next); save(saveKey, next); onChange?.(next); };
  const count = (n: number) => `${n} of ${steps.length} steps done`;
  const finished = state.done.length === steps.length;

  const tick = (id: string, on: boolean) => {
    const done = steps.map((s) => s.id).filter((x) => (x === id ? on : state.done.includes(x)));
    update({ ...state, done });
    announce(done.length === steps.length ? `${count(done.length)}. You’re all set.` : count(done.length));
  };

  // After hiding or showing, focus goes to what took the place of the button that was pressed.
  const showButton = React.useRef<HTMLButtonElement | null>(null);
  const heading = React.useRef<HTMLHeadingElement | null>(null);
  const moved = React.useRef(false);
  React.useEffect(() => {
    if (!moved.current) return;
    moved.current = false;
    (state.hidden ? showButton.current : heading.current)?.focus();
  }, [state.hidden]);
  const setHidden = (hidden: boolean) => { moved.current = true; update({ ...state, hidden }); };

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-3xl flex-col gap-8 px-4 py-8 outline-none">
        <PageHeader title={`Welcome to Acme, ${name}`} description="A few steps get your workspace ready. Do them in any order, now or later: we keep your place." />

        <section aria-labelledby="setup-title" className="flex flex-col gap-4">
          {state.hidden ? (
            <Card padding="sm" className="flex flex-row flex-wrap items-center justify-between gap-3">
              <Heading level={2} size="base" id="setup-title">Set up your workspace: {count(state.done.length)}</Heading>
              <Button ref={showButton} variant="secondary" size="sm" onClick={() => setHidden(false)}>Show the checklist</Button>
            </Card>
          ) : (
            <>
              <div className="flex flex-wrap items-center justify-between gap-3">
                <Heading level={2} size="lg" id="setup-title" ref={heading} tabIndex={-1} className="outline-none">Set up your workspace</Heading>
                <Button variant="ghost" size="sm" onClick={() => setHidden(true)}>Hide the checklist</Button>
              </div>
              <Progress label="Setup progress" value={state.done.length} max={steps.length} showValue tone={finished ? 'success' : 'primary'}
                formatValue={(v) => count(v)} />
              {finished ? (
                <Card>
                  <EmptyState icon="check_circle" headingLevel={3} title="You’re all set"
                    description="Your workspace is ready. Everything here stays where you left it."
                    actions={<Button href={dashboardHref}>Go to your dashboard</Button>} />
                </Card>
              ) : null}
              <ol role="list" className="m-0 flex list-none flex-col gap-3 p-0">
                {steps.map((s, i) => {
                  const done = state.done.includes(s.id);
                  return (
                    <Card as="li" key={s.id} padding="md" className="flex min-w-0 flex-col gap-3 wrap-anywhere" aria-labelledby={`step-${s.id}`}>
                      <div className="flex flex-col gap-1">
                        <Heading level={3} size="base" id={`step-${s.id}`}>
                          <span className="text-text-muted">{i + 1}. </span>{s.title}
                        </Heading>
                        <p className="m-0 text-sm text-text-muted">{s.description}</p>
                      </div>
                      <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
                        <Button href={s.action.href} variant={done ? 'secondary' : 'primary'} size="sm">{s.action.label}</Button>
                        <Checkbox checked={done} onCheckedChange={(on) => tick(s.id, on)} description={done ? 'Done' : 'To do'}>
                          Mark “{s.title}” as done
                        </Checkbox>
                      </div>
                    </Card>
                  );
                })}
              </ol>
            </>
          )}
        </section>

        <section aria-labelledby="projects-title" className="flex flex-col gap-4">
          <Heading level={2} size="lg" id="projects-title">Your projects</Heading>
          <Card variant="filled">
            <EmptyState icon="folder_open" headingLevel={3} title="No projects yet"
              description="A project holds a piece of work: its tasks, its files and the talk about them. Start with one you’re doing now."
              actions={<Button href="#new-project">Create a project</Button>} />
          </Card>
        </section>
      </main>
    </div>
  );
}

files.PasswordReset.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { PasswordInput } from '@diki-stwn/serupa-ds';
import { Icon } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';

/* Password reset: asking for a link by email, then choosing a new password from it. For an app to copy. What it
   carries (WCAG 2.2):
   - 3.3.2: each step says what happens next, and the new password's rules are listed under it from the start, each
     saying in words whether it's met.
   - 1.3.5, 3.3.8: the email field says it holds an email, and the new-password step tells the password manager
     which account it's for (a username field it can read), so it can suggest a strong one and save it; pasting works.
   - 3.3.1, 3.3.3: a missing or malformed email, or a password that breaks a rule, is said next to its field, which
     gets focus; a request or change that fails says so, keeping what was typed.
   - 3.3.7: "Use a different email" and "Send a new link" go back with the email kept, so it isn't typed twice.
   - 4.1.3: sending the link again says, in a status region, that it went or couldn't, without moving focus.
   - 2.4.3: each new step puts focus on its heading, so the change is said and Tab goes on from there.
   - The sent step says the same whether or not an account uses the email, so the page doesn't tell a stranger who
     has an account.
   Sending the link, checking it and storing the password are the app's job: onRequest and onReset stand in. */

export type PasswordResetStep = 'request' | 'sent' | 'choose' | 'expired' | 'done';

export interface PasswordResetProps {
  /** The step it starts on: 'choose' when the page opens from the email's link, 'expired' when that link is too old or used. Default: 'request'. */
  start?: PasswordResetStep | undefined;
  /** The email it starts with: for 'choose', the account the link is for. Default: "". */
  email?: string | undefined;
  /** Send the link to this email. Return its promise: a rejection stays on the step and says the link didn't go. */
  onRequest?: ((email: string) => unknown) | undefined;
  /** Store the new password. Return its promise: a rejection stays on the step and says it wasn't changed. */
  onReset?: ((password: string) => unknown) | undefined;
  /** How long a link works, as the end of "It works for …". Default: "1 hour". */
  linkLife?: string | undefined;
  /** Where "Back to sign in" and "Sign in" go. Default: "#sign-in". */
  signInHref?: string | undefined;
}

const MIN = 12;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** What's wrong with the email, in words, or null when a link can be sent to it. */
export function resetEmailProblem(email: string): string | null {
  const e = email.trim();
  if (!e) return 'Enter the email address you sign in with.';
  if (!EMAIL.test(e)) return 'Enter an email address in the right format, like name@example.com.';
  return null;
}

/** The new password's rules, each met or not for this password and the account's email. */
export function resetPasswordRules(password: string, email: string) {
  const local = email.split('@')[0]?.toLowerCase() || '';
  return [
    { text: `At least ${MIN} characters`, met: password.length >= MIN },
    { text: 'Not your email address or its name part', met: password.length > 0 && !(local.length > 2 && password.toLowerCase().includes(local)) },
  ];
}

/** The password reset page: a skip link, then main with the step's card. */
export function PasswordReset({ start = 'request', email: email0 = '', onRequest, onReset, linkLife = '1 hour', signInHref = '#sign-in' }: PasswordResetProps) {
  const [step, setStep] = React.useState<PasswordResetStep>(start);
  const [email, setEmail] = React.useState(email0);
  const [emailProblem, setEmailProblem] = React.useState<string | null>(null);
  const [password, setPassword] = React.useState('');
  const [passwordProblem, setPasswordProblem] = React.useState<string | null>(null);
  const [failed, setFailed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  // Each answer to "Send it again" is a new keyed line in the status region, so it's said every time.
  const [resent, setResent] = React.useState<{ n: number; ok: boolean }>({ n: 0, ok: true });
  const heading = React.useRef<HTMLHeadingElement>(null);
  const moved = React.useRef(false);
  React.useEffect(() => { if (moved.current) heading.current?.focus(); }, [step]);
  const go = (s: PasswordResetStep) => { moved.current = true; setFailed(false); setResent({ n: 0, ok: true }); setStep(s); };
  const rules = resetPasswordRules(password, email);
  const run = (work: () => unknown, then: () => void) => {
    setBusy(true);
    setFailed(false);
    void Promise.resolve().then(work).then(then, () => setFailed(true)).finally(() => setBusy(false));
  };

  const request = (e: React.FormEvent) => {
    e.preventDefault();
    const found = resetEmailProblem(email);
    setEmailProblem(found);
    if (found) { document.getElementById('reset-email')?.focus(); return; }
    run(() => onRequest?.(email.trim()), () => go('sent'));
  };
  const resend = () => {
    if (busy) return;
    setBusy(true);
    const done = (ok: boolean) => { setBusy(false); setResent((s) => ({ n: s.n + 1, ok })); };
    void Promise.resolve().then(() => onRequest?.(email.trim())).then(() => done(true), () => done(false));
  };
  const choose = (e: React.FormEvent) => {
    e.preventDefault();
    const found = rules.every((r) => r.met) ? null : 'Choose a password that meets the rules under it.';
    setPasswordProblem(found);
    if (found) { document.getElementById('reset-password')?.focus(); return; }
    run(() => onReset?.(password), () => go('done'));
  };
  const title = (text: string) => <Heading level={1} size="xl" ref={heading} tabIndex={-1} className="outline-none">{text}</Heading>;
  const back = <p className="m-0 text-sm"><Link href={signInHref}>Back to sign in</Link></p>;

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <main id="main" className="mx-auto flex max-w-md flex-col gap-6 px-4 py-12 outline-none">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Card className="flex flex-col gap-5">
          {step === 'request' ? (
            <>
              {title('Reset your password')}
              <p className="m-0">Enter the email you sign in with. We’ll send a link to choose a new password.</p>
              <form noValidate onSubmit={request} className="flex flex-col gap-4">
                <Field label="Email" error={emailProblem ?? undefined}>
                  <Input id="reset-email" name="email" type="email" autoComplete="email" spellCheck={false} autoCapitalize="none" value={email}
                    onChange={(e) => { setEmail(e.target.value); if (emailProblem) setEmailProblem(null); }} />
                </Field>
                {failed ? <Alert tone="danger">Couldn’t send the link. Check your connection and try again.</Alert> : null}
                <Button type="submit" loading={busy}>Send the link</Button>
              </form>
              {back}
            </>
          ) : step === 'sent' ? (
            <>
              {title('Check your email')}
              <p className="m-0">If an account uses <strong className="wrap-break-word">{email.trim()}</strong>, we sent it a link to choose a new password. It works for {linkLife}.</p>
              <p className="m-0 text-sm text-text-muted">Nothing there after a few minutes? Check your spam folder, or send it again.</p>
              <div className="flex flex-wrap gap-3">
                <Button variant="outline" loading={busy} onClick={resend}>Send it again</Button>
                <Button variant="ghost" onClick={() => go('request')}>Use a different email</Button>
              </div>
              {/* Always there, so a reader is listening before the first ask; empty, it takes no room. */}
              <div role="status" className="text-sm text-text-muted">
                {resent.n ? <p key={resent.n} className={resent.ok ? 'm-0' : 'm-0 text-danger-text'}>{resent.ok ? `We sent a new link. It works for ${linkLife}.` : 'Couldn’t send the link. Check your connection and try again.'}</p> : null}
              </div>
              {back}
            </>
          ) : step === 'choose' ? (
            <>
              {title('Choose a new password')}
              <form noValidate onSubmit={choose} className="flex flex-col gap-4">
                {/* Tells a password manager which account the new password is for. */}
                <Field label="Account">
                  <Input id="reset-username" name="username" autoComplete="username" value={email} readOnly />
                </Field>
                <Field label="New password" error={passwordProblem ?? undefined}
                  hint={
                    <ul aria-label="Your password needs" className="m-0 flex list-none flex-col gap-1 p-0">
                      {rules.map((r) => (
                        <li key={r.text} className={`flex items-center gap-2 ${r.met ? 'text-text' : 'text-text-muted'}`}>
                          <Icon name={r.met ? 'check_circle' : 'radio_button_unchecked'} size="sm" />
                          <span>{r.text}<span className="sr-only">{r.met ? ', done' : ', not yet'}</span></span>
                        </li>
                      ))}
                    </ul>
                  }>
                  <PasswordInput id="reset-password" name="new-password" autoComplete="new-password" value={password}
                    onChange={(e) => { setPassword(e.target.value); if (passwordProblem) setPasswordProblem(null); }} />
                </Field>
                {failed ? <Alert tone="danger">Couldn’t change your password. Check your connection and try again.</Alert> : null}
                <Button type="submit" loading={busy}>Change password</Button>
              </form>
            </>
          ) : step === 'expired' ? (
            <>
              {title('This link has expired')}
              <p className="m-0">A link works for {linkLife}, and only once. Send a new one to choose your password.</p>
              <Button className="self-start" onClick={() => go('request')}>Send a new link</Button>
              {back}
            </>
          ) : (
            <>
              {title('Your password is changed')}
              <p className="m-0">We signed you out on your other devices. Sign in with your new password.</p>
              <Button href={signInHref} className="self-start">Sign in</Button>
            </>
          )}
        </Card>
      </main>
    </div>
  );
}

files.SessionTimeout.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';

/* Session time-out warning: warns well before a session ends, lets one action keep it, and loses nothing
   typed if it ends anyway. For an app to copy. What it carries (WCAG 2.2):
   - 2.2.1: typing or clicking on the page counts as activity and keeps the session (at most once every
     `activityEvery` seconds, through `onExtend`), so nobody writing a long message is interrupted mid-sentence.
   - 2.2.1: with nothing happening, a Dialog opens `warnBefore` seconds before the end (two minutes by default, well over the 20 seconds
     2.2.1 asks for). "Stay signed in", focused first, is the one action that extends it; Escape extends it too,
     since pressing anything means someone is there.
   - 4.1.3: the time left is said when the warning opens, then only at each whole minute and at 30 seconds, never
     every second. The countdown on screen updates every second, outside any live region.
   - 2.2.6, 3.3.7: what's typed is kept as it's typed (here in sessionStorage under `saveKey`), so if the session
     ends, signing in again in the same tab brings it all back, and the page says so before and after. Signing out on
     purpose or sending the message clears it, so the next person on the computer doesn't find it. Closing the tab
     doesn't: a browser that reopens a closed tab brings its sessionStorage back, so sign out on a shared computer.
     Only the subject and the message are kept: never a password, card number or ID number.
   - 2.4.3: when the warning closes, focus goes back to where it was; when the session ends, to the "Signed out"
     heading.
   Keeping the session on the server (a request from `onExtend`), and signing in again, is the app's job. */

export interface SessionTimeoutProps {
  /** How long the session lasts with nothing done, in seconds. Default: 1200 (20 minutes). */
  duration?: number | undefined;
  /** How long before the end the warning opens, in seconds. Default: 120. */
  warnBefore?: number | undefined;
  /** Refresh the session on the server: "Stay signed in" was pressed, or the person typed or clicked (at most once every
      `activityEvery` seconds). A rejected promise lets the session run out. */
  onExtend?: (() => void | Promise<unknown>) | undefined;
  /** The session ended: sign out on the server. */
  onExpire?: (() => void) | undefined;
  /** Typing or clicking keeps the session, at most once every this many seconds. Default: 60. */
  activityEvery?: number | undefined;
  /** Keeps what's typed in sessionStorage under this key, so it survives a time-out or a reload in the same tab.
      Signing out or sending the message clears it; a closed tab that the browser reopens brings it back. */
  saveKey?: string | undefined;
  /** Send the message. Once it resolves, the kept draft is cleared; a rejected promise keeps it. */
  onSend?: ((draft: { subject: string; message: string }) => void | Promise<unknown>) | undefined;
}

interface Draft { subject: string; message: string }
const TICK = 1000;

/** Words for a time left: "2 minutes", "1 minute 30 seconds", "45 seconds". */
export function timeLeft(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  const unit = (n: number, one: string) => `${n} ${one}${n === 1 ? '' : 's'}`;
  return [m ? unit(m, 'minute') : '', s || !m ? unit(s, 'second') : ''].filter(Boolean).join(' ');
}
/** Whether the time left is worth saying: each whole minute, and 30 seconds. */
const worthSaying = (seconds: number) => seconds > 0 && (seconds % 60 === 0 || seconds === 30);

// Drafts go in sessionStorage, not localStorage: they last for the tab, not for every later visit from the computer.
// Only the two fields below are written, so a field added to the form isn't kept until it's named here; never name a
// password, card number or ID number.
const keep = (d: Partial<Draft>): Draft => ({ subject: String(d.subject ?? ''), message: String(d.message ?? '') });
function load(key: string | undefined): Draft | null {
  if (!key) return null;
  try {
    const raw = window.sessionStorage.getItem(key);
    return raw ? keep(JSON.parse(raw) as Partial<Draft>) : null;
  } catch { return null; }
}
function forget(key: string | undefined) {
  if (!key) return;
  try { window.sessionStorage.removeItem(key); } catch { /* blocked: nothing was kept */ }
}
function save(key: string | undefined, draft: Draft) {
  if (!key) return;
  try { window.sessionStorage.setItem(key, JSON.stringify(keep(draft))); } catch { /* full or blocked: the draft stays in the page */ }
}

/** A page with a form, a warning Dialog before the session ends, and a signed-out page that keeps what was typed. */
export function SessionTimeout({ duration = 1200, warnBefore = 120, activityEvery = 60, onExtend, onExpire, onSend, saveKey }: SessionTimeoutProps) {
  const [deadline, setDeadline] = React.useState(() => Date.now() + duration * 1000);
  const [left, setLeft] = React.useState(duration);
  const [draft, setDraft] = React.useState<Draft>(() => load(saveKey) ?? { subject: '', message: '' });
  const expired = left <= 0;
  const warning = !expired && left <= warnBefore;
  const signedOut = React.useRef<HTMLHeadingElement | null>(null);
  const [byChoice, setByChoice] = React.useState(false);

  React.useEffect(() => {
    if (expired) return;
    const id = window.setInterval(() => {
      const next = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
      setLeft(next);
      if (!next) onExpire?.();
    }, TICK);
    return () => window.clearInterval(id);
  }, [deadline, expired, onExpire]);

  // Say the time left when the warning opens, then only at sensible steps.
  const opened = React.useRef(false);
  React.useEffect(() => {
    if (!warning) { opened.current = false; return; }
    if (!opened.current) { opened.current = true; announce(`You’ll be signed out in ${timeLeft(left)}.`); }
    else if (worthSaying(left)) announce(`${timeLeft(left)} left.`);
  }, [warning, left]);

  React.useEffect(() => { if (expired) signedOut.current?.focus(); }, [expired]);

  const restart = React.useCallback(() => { setDeadline(Date.now() + duration * 1000); setLeft(duration); setByChoice(false); }, [duration]);

  // Typing or clicking is activity: it refreshes the session, at most once every activityEvery seconds. Not while
  // the warning is open, where staying takes the warning's own answer.
  // The session last started at deadline - duration, and one refresh is asked for at a time.
  const asking = React.useRef(false);
  React.useEffect(() => {
    if (expired || warning) return;
    const active = () => {
      if (asking.current || Date.now() - (deadline - duration * 1000) < activityEvery * 1000) return;
      asking.current = true;
      Promise.resolve(onExtend?.()).then(restart, () => { /* the session runs out as warned */ }).finally(() => { asking.current = false; });
    };
    document.addEventListener('keydown', active, true);
    document.addEventListener('pointerdown', active, true);
    return () => { document.removeEventListener('keydown', active, true); document.removeEventListener('pointerdown', active, true); };
  }, [expired, warning, deadline, duration, activityEvery, onExtend, restart]);

  const signOut = () => {
    forget(saveKey);
    setDraft({ subject: '', message: '' });
    setByChoice(true);
    setLeft(0);
    onExpire?.();
  };
  // "Stay signed in" shows it's working while onExtend runs, and takes no second press. When it fails, the warning stays
  // open and says so, with the time still counting, so the person can try again or save their work.
  const [extending, setExtending] = React.useState(false);
  const [extendFailed, setExtendFailed] = React.useState(false);
  const extendingNow = React.useRef(false);
  const extend = async () => {
    if (extendingNow.current) return;
    extendingNow.current = true;
    setExtending(true);
    setExtendFailed(false);
    try { await onExtend?.(); restart(); announce('You’re still signed in.'); } catch {
      setExtendFailed(true);
      announce('Couldn’t keep you signed in. Check your connection and try again.');
    } finally { extendingNow.current = false; setExtending(false); }
  };
  // While a send is under way the button shows it and takes no more presses, so a second click doesn't send the
  // message twice (the ref covers a second press before the re-render). An empty Subject or Message isn't sent: each
  // says what's missing and the first takes focus. The outcome shows on screen, not only to a screen reader: a sent
  // message is confirmed above the form, which takes focus (the form is empty again); a failed one says so beside
  // the button, and what was typed stays.
  const [sending, setSending] = React.useState(false);
  const [missing, setMissing] = React.useState<{ subject?: string; message?: string }>({});
  const [outcome, setOutcome] = React.useState<'sent' | 'failed' | null>(null);
  const sentRef = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => { if (outcome === 'sent') sentRef.current?.focus(); }, [outcome]);
  const sendingNow = React.useRef(false);
  const send = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (sendingNow.current) return;
    const form = e.currentTarget;
    const empty = { subject: draft.subject.trim() ? undefined : 'Enter a subject', message: draft.message.trim() ? undefined : 'Enter your message' };
    setMissing(empty);
    if (empty.subject || empty.message) { setOutcome(null); (form.elements.namedItem(empty.subject ? 'subject' : 'message') as HTMLElement).focus(); return; }
    sendingNow.current = true;
    setSending(true);
    setOutcome(null);
    try { await onSend?.(draft); } catch { setOutcome('failed'); return; } finally { sendingNow.current = false; setSending(false); }
    forget(saveKey);
    setDraft({ subject: '', message: '' });
    setOutcome('sent');
  };
  const type = (k: keyof Draft) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const next = { ...draft, [k]: e.target.value };
    if (missing[k] && e.target.value.trim()) setMissing({ ...missing, [k]: undefined });
    setDraft(next);
    save(saveKey, next);
  };

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-2xl flex-col gap-6 px-4 py-8 outline-none">
        {expired ? (
          <div className="flex flex-col gap-3">
            <Heading level={1} ref={signedOut} tabIndex={-1} className="outline-none">{byChoice ? 'You’ve signed out' : 'You’ve been signed out'}</Heading>
            <p className="m-0">{byChoice
              ? 'What you typed is cleared from this computer, so nobody else finds it.'
              : `We signed you out because nothing happened for ${timeLeft(duration)}. What you typed is kept: sign in again to carry on where you left off.`}</p>
            <div><Button onClick={restart}>Sign in again</Button></div>
          </div>
        ) : (
          <>
            <PageHeader title="Contact support"
              description={<>For your security, you’re signed out after {timeLeft(duration)} with nothing happening: typing counts. We’ll warn you first, and keep what you’ve typed.</>} />
            <Card as="section" aria-labelledby="message-title">
              <form className="flex flex-col gap-4" noValidate onSubmit={(e) => void send(e)}>
                <Heading level={2} size="lg" id="message-title">Your message</Heading>
                {outcome === 'sent' ? <Alert ref={sentRef} tabIndex={-1} tone="success" className="outline-none">Message sent. We’ll reply by email.</Alert> : null}
                <Field label="Subject" error={missing.subject}>
                  <Input name="subject" value={draft.subject} onChange={type('subject')} />
                </Field>
                <Field label="Message" hint="What happened, and what you expected." error={missing.message}>
                  <Textarea name="message" rows={6} value={draft.message} onChange={type('message')} />
                </Field>
                {outcome === 'failed' ? <Alert tone="danger">The message wasn’t sent. What you typed is kept: try again.</Alert> : null}
                <div><Button type="submit" loading={sending}>Send message</Button></div>
              </form>
            </Card>
          </>
        )}
      </main>
      <Dialog open={warning} alert size="sm" title="You’ll be signed out soon"
        onOpenChange={(open) => { if (!open) void extend(); }}
        footer={<>
          <Button variant="secondary" onClick={signOut}>Sign out</Button>
          <Button data-autofocus loading={extending} onClick={() => void extend()}>Stay signed in</Button>
        </>}>
        <p className="m-0">You’ll be signed out in <strong>{timeLeft(left)}</strong> because nothing has happened for a while.</p>
        <p className="m-0 mt-2 text-sm text-text-muted">If the time runs out, what you’ve typed is kept. Signing out clears it.</p>
        {extendFailed ? <p className="m-0 mt-2 text-sm text-danger-text">Couldn’t keep you signed in. Check your connection and try again.</p> : null}
      </Dialog>
    </div>
  );
}

files.SettingsForm.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Switch } from '@diki-stwn/serupa-ds';
import { useUnsavedChanges } from '@diki-stwn/serupa-ds';
import type { ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import type { SaveState } from '@diki-stwn/serupa-ds';
import { SettingsSection } from './SettingsSection';
import { EmptyLoadFailed } from './EmptyStates';
import { PageHeader } from './PageHeader';

/* Settings form: a settings page of sections, each with its own Save, errors and status, and a question before
   unsaved changes are lost. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: each section is a region named by its heading; the switches are real checkboxes (role="switch") with
     their own labels and descriptions.
   - 3.3.1, 3.3.3: a Save with problems shows an ErrorSummary at the top of that section, which takes focus and links
     to each field, and each field says what to write ("Enter an email address, like name@example.com").
   - 4.1.3: SaveStatus says "Saved" politely when a save finishes, or "Couldn't save" with Try again, without moving
     focus.
   - 3.2.2: nothing saves on its own. Each section waits for its own Save, so a change in one never saves another.
   - 3.3.4-ish: leaving with unsaved changes (the "Back to the dashboard" link, or closing the tab) asks "Discard
     changes?" first, with Keep editing focused (useUnsavedChanges).
   Storing the settings is the app's job: `onSave` gets each section's values. */

export interface Profile { name: string; email: string; bio: string; timeZone: string }
export interface Notifications { comments: boolean; summary: boolean; news: boolean }
export interface SettingsValues { profile: Profile; notifications: Notifications }

export interface SettingsFormProps {
  /** The settings as saved. Default: a demo account. */
  initial?: SettingsValues | undefined;
  /** Saves one section. A rejected promise shows "Couldn't save" with Try again. */
  onSave?: (<K extends keyof SettingsValues>(section: K, values: SettingsValues[K]) => void | Promise<unknown>) | undefined;
  /** "Back to the dashboard" was followed, after any unsaved changes were discarded: go there. */
  onLeave?: (() => void) | undefined;
  /** The saved settings are on their way: each section shows placeholder fields, and the form starts from `initial` once
      they're in. Default: false. */
  loading?: boolean | undefined;
  /** The saved settings failed to load: a "Couldn’t load your settings" message with Try again, which calls onRetry, in
      place of the sections. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

const demo: SettingsValues = {
  profile: { name: 'Ada Lovelace', email: 'ada@example.com', bio: '', timeZone: 'Europe/London' },
  notifications: { comments: true, summary: true, news: false },
};
const ZONES = [
  { value: 'America/Los_Angeles', label: 'Los Angeles (UTC−8)' }, { value: 'America/New_York', label: 'New York (UTC−5)' },
  { value: 'Europe/London', label: 'London (UTC+0)' }, { value: 'Europe/Berlin', label: 'Berlin (UTC+1)' },
  { value: 'Asia/Jakarta', label: 'Jakarta (UTC+7)' }, { value: 'Asia/Tokyo', label: 'Tokyo (UTC+9)' },
];
const BIO_MAX = 160;
const id = (k: keyof Profile) => `profile-${k}`;

/** What's wrong with the profile, in the order of its fields. */
export function profileProblems(p: Profile): ErrorSummaryItem[] {
  const rules: [keyof Profile, boolean, string][] = [
    ['name', !p.name.trim(), 'Enter your name, as your team should see it'],
    ['email', !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email.trim()), 'Enter an email address, like name@example.com'],
    ['bio', p.bio.length > BIO_MAX, `Shorten your bio to ${BIO_MAX} characters or fewer`],
  ];
  return rules.filter(([, bad]) => bad).map(([k, , message]) => ({ field: id(k), message }));
}

/** One section's draft, saved copy, errors and save status. */
function useSection<K extends keyof SettingsValues>(key: K, saved0: SettingsValues[K], check: (v: SettingsValues[K]) => ErrorSummaryItem[],
  onSave: SettingsFormProps['onSave']) {
  const [draft, setDraft] = React.useState(saved0);
  const [saved, setSaved] = React.useState(saved0);
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>([]);
  const [status, setStatus] = React.useState<SaveState>('idle');
  const [savedAt, setSavedAt] = React.useState<number | undefined>(undefined);
  const dirty = JSON.stringify(draft) !== JSON.stringify(saved);
  const save = async () => {
    const found = check(draft);
    setErrors(found);
    if (found.length) { setStatus('idle'); return; }
    setStatus('saving');
    try {
      await onSave?.(key, draft);
      setSaved(draft);
      setSavedAt(Date.now());
      setStatus('saved');
    } catch { setStatus('error'); }
  };
  const set = (patch: Partial<SettingsValues[K]>) => { setDraft({ ...draft, ...patch }); if (status === 'saved') setStatus('idle'); };
  return { draft, set, dirty, errors, status, savedAt, save: () => void save() };
}

/** The settings page: a skip link, a header with the way back, then main with the h1 and a section per group. */
export function SettingsForm({ loading = false, loadFailed = false, onRetry, ...props }: SettingsFormProps) {
  // The form takes `initial` when it mounts, so it mounts once the settings are in, not before.
  return loading || loadFailed ? <Loading failed={loadFailed} onRetry={onRetry} /> : <Loaded {...props} />;
}

// While the settings load: the same page, with a busy placeholder per section, named once ("Loading settings"). When
// they failed to load: the page says so in the sections' place, with Try again.
function Loading({ failed, onRetry }: { failed: boolean; onRetry: SettingsFormProps['onRetry'] }) {
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link href="#dashboard">Back to the dashboard</Link>
      </header>
      <main id="main" aria-busy={failed ? undefined : true} className="mx-auto flex max-w-4xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Settings" />
        {failed ? <EmptyLoadFailed title="Couldn’t load your settings" onRetry={() => onRetry?.()} headingLevel={2} /> : ['Profile', 'Notifications'].map((t, i) => (
          <section key={t} aria-labelledby={'settings-loading-' + i} className="flex flex-col gap-3">
            <Heading level={2} size="lg" id={'settings-loading-' + i}>{t}</Heading>
            <Loader variant="skeleton" shape="text" lines={i === 0 ? 6 : 3} label={i === 0 ? 'Loading settings' : ''} />
          </section>
        ))}
      </main>
    </div>
  );
}

function Loaded({ initial = demo, onSave, onLeave }: Omit<SettingsFormProps, 'loading' | 'loadFailed' | 'onRetry'>) {
  const profile = useSection('profile', initial.profile, profileProblems, onSave);
  const notes = useSection('notifications', initial.notifications, () => [], onSave);
  const { confirm, dialog } = useUnsavedChanges(profile.dirty || notes.dirty);
  const p = profile.draft;
  const n = notes.draft;
  const err = (k: keyof Profile) => profile.errors.find((e) => e.field === id(k))?.message;

  const leave = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (await confirm()) onLeave?.();
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link href="#dashboard" onClick={(e) => void leave(e)}>Back to the dashboard</Link>
      </header>
      <main id="main" className="mx-auto flex max-w-4xl flex-col px-4 py-8 outline-none">
        <PageHeader title="Settings" />
        <SettingsSection title="Profile" description="How you appear to your team." onSave={profile.save}
          errors={profile.errors} status={profile.status} savedAt={profile.savedAt} onRetry={profile.save} saveLabel="Save profile">
          <Field label="Name" error={err('name')} required>
            <Input id={id('name')} name="name" autoComplete="name" value={p.name} onChange={(e) => profile.set({ name: e.target.value })} />
          </Field>
          <Field label="Email" hint="Where we send your notifications." error={err('email')} required>
            <Input id={id('email')} name="email" type="email" autoComplete="email" spellCheck={false} value={p.email}
              onChange={(e) => profile.set({ email: e.target.value })} />
          </Field>
          <Field label="Bio" hint={`A line about you, up to ${BIO_MAX} characters.`} error={err('bio')} optional>
            <Textarea id={id('bio')} name="bio" rows={3} showCount maxLength={BIO_MAX} value={p.bio} onChange={(e) => profile.set({ bio: e.target.value })} />
          </Field>
          <Field label="Time zone" hint="For the times on comments and the weekly summary.">
            <Select id={id('timeZone')} name="timeZone" value={p.timeZone} options={ZONES} onChange={(e) => profile.set({ timeZone: e.target.value })} />
          </Field>
        </SettingsSection>
        <SettingsSection title="Notifications" description="What reaches you by email. Everything is in the app either way."
          onSave={notes.save} status={notes.status} savedAt={notes.savedAt} onRetry={notes.save} saveLabel="Save notifications">
          <Switch checked={n.comments} onCheckedChange={(on) => notes.set({ comments: on })} description="When someone replies to you or mentions you.">Comments</Switch>
          <Switch checked={n.summary} onCheckedChange={(on) => notes.set({ summary: on })} description="Every Monday: what changed in your projects.">Weekly summary</Switch>
          <Switch checked={n.news} onCheckedChange={(on) => notes.set({ news: on })} description="New features, at most once a month.">Product news</Switch>
        </SettingsSection>
        {dialog}
      </main>
    </div>
  );
}

