'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { PasswordInput } from '@diki-stwn/serupa-ds';
import { PhoneInput } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { PinInput } from '@diki-stwn/serupa-ds';
import { Icon } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';

/* Sign-up: name, email, an optional phone, a password whose rules are shown before typing, and the terms; then a
   code sent by email; then done. For an app to copy. What it carries (WCAG 2.2):
   - 3.3.2: the password's rules are listed under it from the start, not only after a failed try, and each says
     whether it's met in words as well as by its mark.
   - 1.3.5: each field says what it holds (name, email, tel, new-password, one-time-code), so the browser, a phone
     and a password manager can fill it, and suggest a strong password.
   - 3.3.8: pasting works everywhere, the code can be filled from the email, and there's no puzzle to solve.
   - 3.3.1, 3.3.3: Create account with problems shows an ErrorSummary that takes focus and links to each field, and
     each field says what to do.
   - 3.3.7: "Change email" on the code step goes back with every answer kept, so nothing is typed twice.
   - 4.1.3: "Send a new code", which the wrong-code error points to, says in a status region that the code went, or
     that it couldn't (onResend rejected), without moving focus off the button.
   - 2.4.3, 4.1.3: each new step puts focus on its heading, so the change is said and Tab goes on from there.
   Creating the account and sending the code are the app's job: onSubmit and verify stand in for them. */

export interface SignUpValues { name: string; email: string; phone: string; password: string; terms: boolean }
export type SignUpStep = 'form' | 'code' | 'done';

export interface SignUpProps {
  /** The step it starts on. Default: 'form'. */
  start?: SignUpStep | undefined;
  /** The answers it starts with. */
  initial?: Partial<SignUpValues> | undefined;
  /** The form passed its checks: create the account and send the code. A rejected promise stays on the form. */
  onSubmit?: ((values: SignUpValues) => unknown) | undefined;
  /** Starts as after `onSubmit` was rejected: the form, with its answers, saying the account wasn't created. */
  failed?: boolean | undefined;
  /** The app's check of the code. Default: "123456". */
  verify?: ((code: string) => boolean) | undefined;
  /** Sends a new code to the email, from "Send a new code". Return its promise: the button is busy until it settles,
   *  and a rejection says the code didn't go. */
  onResend?: ((email: string) => void | PromiseLike<unknown>) | undefined;
}

const MIN = 12;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
/** The password's rules, each met or not for this password and email. */
export function passwordRules(password: string, email: string) {
  const local = email.split('@')[0]?.toLowerCase() || '';
  return [
    { text: `At least ${MIN} characters`, met: password.length >= MIN },
    { text: 'Not your email address or its name part', met: password.length > 0 && !(local.length > 2 && password.toLowerCase().includes(local)) },
  ];
}
/** What's wrong with the answers, in the order of the fields. */
export function signUpProblems(v: SignUpValues): ErrorSummaryItem[] {
  const out: ErrorSummaryItem[] = [];
  if (!v.name.trim()) out.push({ field: 'sign-up-name', message: 'Enter your name' });
  if (!v.email.trim()) out.push({ field: 'sign-up-email', message: 'Enter your email address' });
  else if (!EMAIL.test(v.email.trim())) out.push({ field: 'sign-up-email', message: 'Enter an email address in the right format, like name@example.com' });
  if (!passwordRules(v.password, v.email).every((r) => r.met)) out.push({ field: 'sign-up-password', message: `Choose a password that meets the rules under it` });
  if (!v.terms) out.push({ field: 'sign-up-terms', message: 'Agree to the terms to create an account' });
  return out;
}

const empty: SignUpValues = { name: '', email: '', phone: '', password: '', terms: false };

/** The sign-up page: a skip link, then main with the step's form. */
export function SignUp({ start = 'form', initial, onSubmit, failed: startFailed, verify = (c) => c === '123456', onResend }: SignUpProps) {
  const [step, setStep] = React.useState<SignUpStep>(start);
  const [v, setV] = React.useState<SignUpValues>({ ...empty, ...initial });
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>([]);
  const [tries, setTries] = React.useState(0);
  const [code, setCode] = React.useState('');
  const [codeError, setCodeError] = React.useState('');
  const [busy, setBusy] = React.useState(false);
  // onSubmit rejected (the server refused, or the network failed): say so over the button, and keep what was typed.
  const [failed, setFailed] = React.useState(!!startFailed);
  // Each answer to "Send a new code" is a new keyed line in the status region, so it's said every time.
  const [sent, setSent] = React.useState<{ n: number; ok: boolean }>({ n: 0, ok: true });
  const [resending, setResending] = React.useState(false);
  const resend = () => {
    if (resending) return;
    setCode(''); setCodeError('');
    const done = (ok: boolean) => { setResending(false); setSent((s) => ({ n: s.n + 1, ok })); };
    setResending(true);
    Promise.resolve().then(() => onResend?.(v.email)).then(() => done(true), () => done(false));
  };
  const heading = React.useRef<HTMLHeadingElement>(null);
  const moved = React.useRef(false);
  React.useEffect(() => { if (moved.current) heading.current?.focus(); }, [step]);
  const go = (s: SignUpStep) => { moved.current = true; setStep(s); };
  const set = <K extends keyof SignUpValues>(k: K) => (value: SignUpValues[K]) => setV((o) => ({ ...o, [k]: value }));
  const error = (field: string) => errors.find((e) => e.field === field)?.message;
  const rules = passwordRules(v.password, v.email);

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    const found = signUpProblems(v);
    setErrors(found);
    setTries((t) => t + 1);
    if (found.length) return;
    setBusy(true);
    setFailed(false);
    Promise.resolve().then(() => onSubmit?.(v)).then(() => go('code'), () => setFailed(true)).finally(() => setBusy(false));
  };
  const check = (e: React.FormEvent) => {
    e.preventDefault();
    // The same error again (a second wrong code) doesn't change the field's words, so the field doesn't say it again:
    // it's said here.
    const show = (message: string) => { if (message === codeError) announce(message); setCodeError(message); };
    if (code.length < 6) show('Enter the 6-digit code from the email');
    else if (!verify(code)) show('That code isn’t right. Check the latest email, or send a new code');
    else { setCodeError(''); go('done'); }
  };

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <main id="main" className="mx-auto flex max-w-md flex-col gap-6 px-4 py-12 outline-none">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Card className="flex flex-col gap-5">
          {step === 'form' ? (
            <>
              <Heading level={1} size="xl" ref={heading} tabIndex={-1} className="outline-none">Create your account</Heading>
              {errors.length ? <ErrorSummary key={tries} errors={errors} headingLevel={2} /> : null}
              <form noValidate onSubmit={submit} className="flex flex-col gap-4">
                <Field label="Name" error={error('sign-up-name')}>
                  <Input id="sign-up-name" name="name" autoComplete="name" value={v.name} onChange={(e) => set('name')(e.target.value)} />
                </Field>
                <Field label="Email" hint="We’ll send a code here to check it’s yours." error={error('sign-up-email')}>
                  <Input id="sign-up-email" name="email" type="email" autoComplete="email" spellCheck={false} autoCapitalize="none" value={v.email} onChange={(e) => set('email')(e.target.value)} />
                </Field>
                <Field label="Phone" optional hint="For signing in if you lose your password.">
                  <PhoneInput id="sign-up-phone" name="phone" autoComplete="tel" defaultCountry="ID" value={v.phone} onValueChange={(p) => set('phone')(p)} />
                </Field>
                <Field label="Password" error={error('sign-up-password')}
                  hint={
                    <ul aria-label="Your password needs" className="m-0 flex list-none flex-col gap-1 p-0">
                      {rules.map((r) => (
                        <li key={r.text} className={`flex items-center gap-2 ${r.met ? 'text-text' : 'text-text-muted'}`}>
                          <Icon name={r.met ? 'check_circle' : 'radio_button_unchecked'} size="sm" />
                          <span>{r.text}<span className="sr-only">{r.met ? ', done' : ', not yet'}</span></span>
                        </li>
                      ))}
                    </ul>
                  }>
                  <PasswordInput id="sign-up-password" name="password" autoComplete="new-password" value={v.password} onChange={(e) => set('password')(e.target.value)} />
                </Field>
                <Field error={error('sign-up-terms')}>
                  <Checkbox id="sign-up-terms" name="terms" checked={v.terms} onCheckedChange={set('terms')} invalid={!!error('sign-up-terms')}>
                    I agree to the <Link href="#terms">terms</Link> and the <Link href="#privacy">privacy notice</Link>
                  </Checkbox>
                </Field>
                {failed ? <Alert tone="danger">Couldn’t create your account. Check your connection and try again.</Alert> : null}
                <Button type="submit" loading={busy}>Create account</Button>
              </form>
              <p className="m-0 text-sm">Already have an account? <Link href="#sign-in">Sign in</Link></p>
            </>
          ) : step === 'code' ? (
            <>
              <Heading level={1} size="xl" ref={heading} tabIndex={-1} className="outline-none">Check your email</Heading>
              <p className="m-0">We sent a 6-digit code to <strong>{v.email || 'your email'}</strong>. It works for 10 minutes.</p>
              <form noValidate onSubmit={check} className="flex flex-col gap-4">
                <Field label="Code" error={codeError || undefined}>
                  <PinInput id="sign-up-code" name="code" length={6} autoComplete="one-time-code" value={code} onValueChange={setCode} invalid={!!codeError} />
                </Field>
                <Button type="submit">Verify email</Button>
              </form>
              <div className="flex flex-wrap gap-3">
                <Button variant="ghost" loading={resending} onClick={resend}>Send a new code</Button>
                <Button variant="ghost" onClick={() => { setCode(''); setCodeError(''); setSent({ n: 0, ok: true }); go('form'); }}>Change email</Button>
              </div>
              {/* Always there, so a reader is listening before the first ask; empty, it takes no room. */}
              <div role="status" className="text-sm text-text-muted">
                {sent.n ? <p key={sent.n} className={sent.ok ? 'm-0' : 'm-0 text-danger-text'}>{sent.ok ? `We sent a new code to ${v.email || 'your email'}. It works for 10 minutes.` : 'Couldn’t send a new code. Check your connection and try again.'}</p> : null}
              </div>
            </>
          ) : (
            <>
              <Heading level={1} size="xl" ref={heading} tabIndex={-1} className="outline-none">Your account is ready</Heading>
              <p className="m-0">Welcome, {v.name.trim() || 'there'}. You can change your details later in Settings.</p>
              <Link href="#dashboard">Go to your dashboard</Link>
            </>
          )}
        </Card>
      </main>
    </div>
  );
}

files.TeamMembers.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Avatar } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { announce } from '@diki-stwn/serupa-ds';

/* Team members: who is on the team, what each may do, inviting more people, and removing someone. For an app to copy.
   What it carries (WCAG 2.2):
   - 1.3.1, 2.4.6: each member's role picker is named with the member ("Role for Ana Lima"), so a list of them isn't
     a list of "Role, Role, Role".
   - 4.1.3: a changed role is said ("Ana Lima is now an Admin"); an invite sent, resent or revoked is said in a toast.
   - 3.3.4: removing a member or revoking an invite happens at once with Undo in a toast, and is done for good only
     when the toast goes, so nothing needs "Are you sure?" first.
   - 2.4.3: after a removal, focus goes to the next row's button (or the list's heading), never to the top of the page.
   - 3.3.1, 3.3.3: the invite form names each address that isn't one, or is on the team already, and keeps what was
     typed; an invite that fails says so in the dialog, which stays open.
   - 4.1.3, 3.3.1: while the team loads, the list is busy with one placeholder name ("Loading members"); a failed load
     says so in its place, with Try again.
   - The owner can't be removed or demoted here, and the row says why in words, not only by a missing button.
   Storing the changes is the app's job: onInvite, onRoleChange, onRemove, onResend and onRevoke get them. */

export type TeamRole = 'admin' | 'member' | 'viewer';
export interface TeamMember { id: string; name: string; email: string; role: TeamRole | 'owner'; avatar?: string | undefined; you?: boolean | undefined }
export interface TeamInvite { email: string; role: TeamRole }

export interface TeamMembersProps {
  /** The people on the team. Default: a demo team. */
  members?: readonly TeamMember[] | undefined;
  /** Invites sent and not yet accepted. Default: one demo invite. */
  invites?: readonly TeamInvite[] | undefined;
  /** Invite was pressed with good addresses. Return its promise: a rejection keeps the dialog open and says so. */
  onInvite?: ((emails: string[], role: TeamRole) => unknown) | undefined;
  /** A member's role was changed. */
  onRoleChange?: ((id: string, role: TeamRole) => void) | undefined;
  /** A removed member's toast closed without Undo: remove them for good. */
  onRemove?: ((id: string) => void) | undefined;
  /** Resend was pressed on an invite. */
  onResend?: ((email: string) => void) | undefined;
  /** A revoked invite's toast closed without Undo: revoke it for good. */
  onRevoke?: ((email: string) => void) | undefined;
  /** The team is on its way: placeholder rows in place of the members and invites, named once ("Loading members"). Default: false. */
  loading?: boolean | undefined;
  /** The team failed to load: a "Couldn’t load your team" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

const demoMembers: TeamMember[] = [
  { id: 'u1', name: 'Ana Lima', email: 'ana@example.com', role: 'owner', you: true },
  { id: 'u2', name: 'Budi Santoso', email: 'budi@example.com', role: 'admin' },
  { id: 'u3', name: 'Chen Wei', email: 'chen@example.com', role: 'member' },
  { id: 'u4', name: 'Dewi Lestari', email: 'dewi@example.com', role: 'viewer' },
];
const demoInvites: TeamInvite[] = [{ email: 'eko@example.com', role: 'member' }];

const ROLES: { value: TeamRole; label: string; hint: string }[] = [
  { value: 'admin', label: 'Admin', hint: 'can invite and remove people' },
  { value: 'member', label: 'Member', hint: 'can edit projects' },
  { value: 'viewer', label: 'Viewer', hint: 'can only look' },
];
const roleName = (r: TeamMember['role']) => (r === 'owner' ? 'Owner' : ROLES.find((x) => x.value === r)!.label);
const options = ROLES.map((r) => ({ value: r.value, label: r.label }));
const EMAIL = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/;

/** The addresses in what was typed, split at commas, semicolons, spaces and new lines, each once. */
export function emailsIn(text: string): string[] {
  return [...new Set(text.split(/[\s,;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean))];
}

/** What's wrong with these addresses, in words, or null when they can all be invited. */
export function inviteProblem(emails: readonly string[], taken: readonly string[]): string | null {
  if (!emails.length) return 'Enter at least one email address.';
  const bad = emails.filter((e) => !EMAIL.test(e));
  if (bad.length) return `${bad.length === 1 ? 'This isn’t an email address' : 'These aren’t email addresses'}: ${bad.join(', ')}.`;
  const on = emails.filter((e) => taken.includes(e));
  if (on.length) return `Already on the team or invited: ${on.join(', ')}.`;
  return null;
}

/** The team page: a skip link, a header, then main with the h1 and Invite people, the members, and the open invites. */
export function TeamMembers({ members = demoMembers, invites = demoInvites, onInvite, onRoleChange, onRemove, onResend, onRevoke, loading = false, loadFailed = false, onRetry }: TeamMembersProps) {
  const [roles, setRoles] = React.useState<Record<string, TeamRole>>({});
  const [gone, setGone] = React.useState<ReadonlySet<string>>(new Set());
  const [sent, setSent] = React.useState<TeamInvite[]>([]);
  const [inviting, setInviting] = React.useState(false);
  const [text, setText] = React.useState('');
  const [role, setRole] = React.useState<TeamRole>('member');
  const [problem, setProblem] = React.useState<string | null>(null);
  const [failed, setFailed] = React.useState(false);
  const membersHeading = React.useRef<HTMLHeadingElement>(null);
  const invitesHeading = React.useRef<HTMLHeadingElement>(null);
  const shown = members.filter((m) => !gone.has(m.id));
  const open = [...invites, ...sent].filter((i) => !gone.has(i.email));
  const later = (f: () => void) => requestAnimationFrame(f);
  const focusId = (id: string) => () => document.getElementById(id)?.focus();

  // Takes a row out with Undo, and moves focus to the next row's button, or the one before, or the list's heading.
  const takeOut = <T,>(rows: readonly T[], row: T, key: string, button: (r: T) => string, heading: React.RefObject<HTMLHeadingElement | null>,
    title: string, commit: () => void) => {
    const at = rows.indexOf(row), next = rows[at + 1] ?? rows[at - 1];
    setGone((g) => new Set(g).add(key));
    later(next !== undefined ? focusId(button(next)) : () => heading.current?.focus());
    toast.undo({
      title, commit,
      onUndo: () => { setGone((g) => { const n = new Set(g); n.delete(key); return n; }); later(focusId(button(row))); },
    });
  };
  const remove = (m: TeamMember) => takeOut(shown, m, m.id, (r) => `remove-${r.id}`, membersHeading, `Removed ${m.name}`, () => onRemove?.(m.id));
  const revoke = (i: TeamInvite) => takeOut(open, i, i.email, (r) => `revoke-${r.email}`, invitesHeading, `Revoked the invite to ${i.email}`, () => onRevoke?.(i.email));
  const resend = (i: TeamInvite) => { onResend?.(i.email); toast({ title: `Sent the invite to ${i.email} again`, tone: 'success' }); };
  const change = (m: TeamMember, r: TeamRole) => {
    setRoles((x) => ({ ...x, [m.id]: r }));
    onRoleChange?.(m.id, r);
    announce(`${m.name} is now ${r === 'admin' ? 'an' : 'a'} ${roleName(r)}`);
  };

  const ask = (o: boolean) => { setInviting(o); if (!o) { setProblem(null); setFailed(false); } };
  const [busy, setBusy] = React.useState(false);
  const send = (e: React.FormEvent) => {
    e.preventDefault();
    const emails = emailsIn(text);
    const found = inviteProblem(emails, [...members.map((m) => m.email.toLowerCase()), ...open.map((i) => i.email)]);
    setProblem(found);
    setFailed(false);
    if (found) { later(focusId('invite-emails')); return; }
    // A failed invite, by rejecting or by throwing, keeps the dialog open and says so; the addresses stay typed.
    setBusy(true);
    void Promise.resolve().then(() => onInvite?.(emails, role)).then(() => {
      setSent((s) => [...s, ...emails.map((email) => ({ email, role }))]);
      setInviting(false);
      setText('');
      toast({ title: emails.length === 1 ? `Invited ${emails[0]}` : `Invited ${emails.length} people`, tone: 'success' });
    }, () => setFailed(true)).finally(() => setBusy(false));
  };

  return (
    <div className="min-h-screen bg-surface-muted text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <main id="main" className="mx-auto flex max-w-4xl flex-col gap-6 px-4 py-8 outline-none">
        <PageHeader title="Team" description="Who can see and change this workspace."
          primary={{ label: 'Invite people', onSelect: () => ask(true) }} />

        {loadFailed ? <EmptyLoadFailed title="Couldn’t load your team" onRetry={() => onRetry?.()} headingLevel={2} /> : loading ? (
          <Card className="flex flex-col gap-3">
            <Heading level={2} size="lg">Members</Heading>
            <ul role="list" aria-busy="true" className="m-0 flex list-none flex-col gap-4 p-0">
              {/* One name for all of them: the first row is named, the others are only pictures. */}
              {[0, 1, 2].map((i) => <li key={i}><Loader variant="skeleton" shape="text" size="sm" lines={2} label={i === 0 ? 'Loading members' : ''} /></li>)}
            </ul>
          </Card>
        ) : <>
        <Card className="flex flex-col gap-3">
          <Heading level={2} size="lg" ref={membersHeading} tabIndex={-1} className="outline-none">Members ({shown.length})</Heading>
          <ul className="m-0 flex list-none flex-col divide-y divide-border p-0">
            {shown.map((m) => {
              const r = m.role === 'owner' ? 'owner' : roles[m.id] ?? m.role;
              return (
                <li key={m.id} className="flex flex-wrap items-center gap-3 py-3">
                  <Avatar size="sm" name={m.name} src={m.avatar} alt="" />
                  <div className="flex min-w-0 flex-1 flex-col">
                    <span className="font-medium">{m.name}{m.you ? <Badge className="ms-2">You</Badge> : null}</span>
                    <span className="text-sm wrap-break-word text-text-muted">{m.email}</span>
                  </div>
                  {r === 'owner' ? (
                    <span className="text-sm text-text-muted">Owner, can’t be removed</span>
                  ) : (
                    <>
                      <Select size="sm" aria-label={`Role for ${m.name}`} value={r} options={options}
                        onChange={(e) => change(m, e.target.value as TeamRole)} className="w-32" />
                      <Button id={`remove-${m.id}`} size="sm" variant="ghost" aria-label={`Remove ${m.name}`} onClick={() => remove(m)}>Remove</Button>
                    </>
                  )}
                </li>
              );
            })}
          </ul>
        </Card>

        <Card className="flex flex-col gap-3">
          <Heading level={2} size="lg" ref={invitesHeading} tabIndex={-1} className="outline-none">Invites ({open.length})</Heading>
          {open.length ? (
            <ul className="m-0 flex list-none flex-col divide-y divide-border p-0">
              {open.map((i) => (
                <li key={i.email} className="flex flex-wrap items-center gap-3 py-3">
                  <div className="flex min-w-0 flex-1 flex-col">
                    <span className="wrap-break-word">{i.email}</span>
                    <span className="text-sm text-text-muted">Invited as {roleName(i.role)}, not joined yet</span>
                  </div>
                  <Button size="sm" variant="outline" aria-label={`Resend the invite to ${i.email}`} onClick={() => resend(i)}>Resend</Button>
                  <Button id={`revoke-${i.email}`} size="sm" variant="ghost" aria-label={`Revoke the invite to ${i.email}`} onClick={() => revoke(i)}>Revoke</Button>
                </li>
              ))}
            </ul>
          ) : <p className="m-0 text-text-muted">No invites waiting.</p>}
        </Card>

        </>}

        <Dialog open={inviting} onOpenChange={ask} title="Invite people" description="They get an email with a link to join. It works for 7 days.">
          <form onSubmit={send} noValidate className="flex flex-col gap-4">
            {failed ? <Alert tone="danger">Couldn’t send the invites. Try again.</Alert> : null}
            <Field label="Email addresses" id="invite-emails" hint="Separate them with commas or new lines." error={problem ?? undefined}>
              <Textarea rows={3} value={text} onChange={(e) => { setText(e.target.value); if (problem) setProblem(null); }} autoComplete="off" />
            </Field>
            <Field label="Role" id="invite-role" hint={ROLES.find((x) => x.value === role)!.hint.replace(/^./, (c) => c.toUpperCase()) + '.'}>
              <Select value={role} options={options} onChange={(e) => setRole(e.target.value as TeamRole)} />
            </Field>
            <Button type="submit" className="self-start" loading={busy}>Send invites</Button>
          </form>
        </Dialog>
      </main>
      <Toaster />
    </div>
  );
}

