'use client';
import * as React from 'react';
import { Heading } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { PasswordInput } from '@diki-stwn/serupa-ds';
import { PinInput } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';

/* Auth card (BL9): the sign-in card, email and password and then a one-time code, as a block an app places on its own
   page. The Sign-in pattern (src/patterns/SignIn) is this card on a page of its own. What it carries (WCAG 2.2):
   - 3.3.8 Accessible authentication: nothing to remember or work out beyond the password itself. The fields say
     autocomplete="username" and "current-password", so a password manager fills them; paste works in both; the
     password can be shown; the code field is autocomplete="one-time-code", so a phone fills a texted code; no puzzle.
   - 3.3.1 and 3.3.3: a failed try lists each problem in an ErrorSummary at the top, which takes focus, with the same
     words under each field, saying how to fix it.
   - 2.4.3 and 4.1.3: moving to the code step and to the end puts focus on the new step's heading, so a screen reader
     says where it is. "Send a new code" says on screen that the code went, in a status region a screen reader reads
     without moving focus off the button, or that it couldn't go when onResend rejects. "Back to email and password"
     leaves the code step for the first one, keeping the email, with focus on its heading.
   - Each word is a label, English by default. The checks against a server are the app's: `check` and `verify`. */

export type AuthStep = 'password' | 'code' | 'done';

export interface AuthCardLabels {
  title: string;
  email: string;
  password: string;
  forgot: string;
  signIn: string;
  emailMissing: string;
  emailFormat: string;
  passwordMissing: string;
  /** A wrong email or password: one message, on the password, that doesn't say which was wrong. */
  wrong: string;
  codeTitle: string;
  codeSent: string;
  code: string;
  verify: string;
  codeShort: string;
  codeWrong: string;
  /** When check or verify rejects (the network, not the answer): shown under the button and said once. */
  failed: string;
  resend: string;
  resent: string;
  /** When onResend's promise rejects: said in the same status region, in place of "We sent a new code". */
  resendFailed: string;
  /** On the code step: back to the email and password, to sign in as someone else or fix a typo. */
  back: string;
  doneTitle: string;
  doneMessage: string;
  doneLink: string;
}

const english: AuthCardLabels = {
  title: 'Sign in',
  email: 'Email',
  password: 'Password',
  forgot: 'Forgot your password?',
  signIn: 'Sign in',
  emailMissing: 'Enter your email address',
  emailFormat: 'Enter an email address in the right format, like name@example.com',
  passwordMissing: 'Enter your password',
  wrong: 'The email or password is not right. Check them, or reset your password',
  codeTitle: 'Enter your sign-in code',
  codeSent: 'We sent a 6-digit code to the phone number on your account. It works for 10 minutes.',
  code: 'Code',
  verify: 'Verify',
  codeShort: 'Enter the 6-digit code',
  codeWrong: 'That code is not right. Check the latest message, or send a new code',
  failed: 'Couldn’t check that. Check your connection and try again.',
  resend: 'Send a new code',
  resent: 'We sent a new code to your phone. It works for 10 minutes.',
  resendFailed: 'Couldn’t send a new code. Check your connection and try again.',
  back: 'Back to email and password',
  doneTitle: 'You’re signed in',
  doneMessage: 'Welcome back. Taking you to your dashboard.',
  doneLink: 'Go to your dashboard',
};

type Check<A extends unknown[]> = (...args: A) => boolean | PromiseLike<boolean>;

export interface AuthCardProps {
  /** Your server's check of the email and password: true lets them on. */
  check: Check<[email: string, password: string]>;
  /** Your server's check of the one-time code. Without it there is no code step: a right password ends on done. */
  verify?: Check<[code: string]> | undefined;
  /** Sends a new code when "Send a new code" is pressed. Return its promise: the button is busy until it settles, and
   *  a rejection says the code didn't go. */
  onResend?: (() => void | PromiseLike<unknown>) | undefined;
  /** Runs once the person is signed in, on the done step. */
  onSignedIn?: (() => void) | undefined;
  /** Where "Forgot your password?" goes. */
  forgotHref: string;
  /** Where "Go to your dashboard" goes, on the done step. Without it, the link isn't shown. */
  doneHref?: string | undefined;
  /** The start of each field's id, which the error summary's links point at. Default: one of React's own. */
  idPrefix?: string | undefined;
  /** The headings' level: 1 when the card is the page, as on a sign-in page. Default: 1. */
  headingLevel?: 1 | 2 | 3 | undefined;
  /** Which step it starts on. Default: 'password'. */
  start?: AuthStep | undefined;
  /** For docs and tests: start as after a failed try, 'empty' (nothing filled in) or 'wrong' (no such account). */
  failed?: 'empty' | 'wrong' | undefined;
  /** The email it starts with: one remembered from the last visit, say. */
  defaultEmail?: string | undefined;
  /** For docs and tests only, to show a failed try. Never prefill a real password. */
  defaultPassword?: string | undefined;
  labels?: Partial<AuthCardLabels> | undefined;
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const thenable = (v: unknown): v is PromiseLike<unknown> => v != null && typeof (v as PromiseLike<unknown>).then === 'function';
/** Runs `then` with the answer: now when it's a boolean, so nothing waits a tick; when it settles when it's a promise. */
function answer(out: boolean | PromiseLike<boolean>, then: (ok: boolean) => void, busy: (on: boolean) => void, failed: () => void) {
  if (!thenable(out)) { then(out); return; }
  busy(true);
  out.then((ok) => { busy(false); then(ok); }, () => { busy(false); failed(); });
}

/** The sign-in card: email and password, then a one-time code, then signed in. */
export function AuthCard({ check, verify, onResend, onSignedIn, forgotHref, doneHref, idPrefix, headingLevel = 1, start = 'password', failed, defaultEmail = '', defaultPassword = '', labels }: AuthCardProps) {
  const l = { ...english, ...labels };
  const own = React.useId(), p = idPrefix ?? own;
  const ids = { title: `${p}-title`, email: `${p}-email`, password: `${p}-password`, code: `${p}-code` };
  const problems = (email: string, password: string): ErrorSummaryItem[] => {
    const out: ErrorSummaryItem[] = [];
    if (!email.trim()) out.push({ field: ids.email, message: l.emailMissing });
    else if (!EMAIL.test(email.trim())) out.push({ field: ids.email, message: l.emailFormat });
    if (!password) out.push({ field: ids.password, message: l.passwordMissing });
    return out;
  };
  const wrong: ErrorSummaryItem[] = [{ field: ids.password, message: l.wrong }];

  const [step, setStep] = React.useState<AuthStep>(start);
  const [email, setEmail] = React.useState(defaultEmail);
  const [password, setPassword] = React.useState(defaultPassword);
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>(() => (failed === 'empty' ? problems('', '') : failed === 'wrong' ? wrong : []));
  const [code, setCode] = React.useState('');
  const [codeError, setCodeError] = React.useState<string | null>(null);
  const [busy, setBusy] = React.useState(false);
  // A check that couldn't run: its words under the button, until the next try.
  const [failure, setFailure] = React.useState(false);
  // Each failed try remounts the error summary, so it takes focus and is read again even when its errors are the
  // same as last time (a second wrong password).
  const [tries, setTries] = React.useState(0);
  const fail = () => { setFailure(true); announce(l.failed); };
  // How many times a new code was asked for, and whether the last ask failed. Each answer puts a new line in the
  // status region below, so it is said every time.
  const [sent, setSent] = React.useState(0);
  const [resendFailed, setResendFailed] = React.useState(false);
  const [resending, setResending] = React.useState(false);
  const resend = () => {
    if (resending) return;
    setCode(''); setCodeError(null);
    const out = onResend?.();
    const done = (ok: boolean) => { setResending(false); setResendFailed(!ok); setSent((n) => n + 1); };
    if (!thenable(out)) { done(true); return; }
    setResending(true);
    out.then(() => done(true), () => done(false));
  };
  // A new step puts focus on its heading (tabIndex -1), so the change is said and the next Tab goes on from there.
  const heading = React.useRef<HTMLHeadingElement | null>(null);
  const moved = React.useRef(false);
  React.useEffect(() => { if (moved.current && heading.current) heading.current.focus(); }, [step]);
  const go = (next: AuthStep) => { moved.current = true; setStep(next); if (next === 'done') onSignedIn?.(); };

  const fieldError = (id: string) => errors.find((e) => e.field === id)?.message;
  const signIn = (e: React.FormEvent) => {
    e.preventDefault();
    if (busy) return;
    setFailure(false);
    const found = problems(email, password);
    if (found.length) { setErrors(found); setTries((n) => n + 1); return; }
    setErrors([]);
    answer(check(email.trim(), password), (ok) => {
      if (!ok) { setErrors(wrong); setTries((n) => n + 1); return; }
      go(verify ? 'code' : 'done');
    }, setBusy, fail);
  };
  const confirm = (e: React.FormEvent) => {
    e.preventDefault();
    if (busy || !verify) return;
    setFailure(false);
    // The same error again (a second wrong code) doesn't change the field's words, so the field doesn't say it again:
    // it's said here. A check that waits clears the error first, and the field says it when it comes back.
    const before = codeError;
    let waited = false;
    const show = (message: string) => { if (!waited && message === before) announce(message); setCodeError(message); };
    if (code.length < 6) { show(l.codeShort); return; }
    setCodeError(null);
    answer(verify(code), (ok) => {
      if (!ok) { show(l.codeWrong); return; }
      go('done');
    }, (on) => { if (on) waited = true; setBusy(on); }, fail);
  };
  const title = (text: string) => <Heading level={headingLevel} size="xl" id={ids.title} ref={heading} tabIndex={-1} className="outline-none">{text}</Heading>;

  return step === 'password' ? (
    <Card as="section" aria-labelledby={ids.title} className="flex flex-col gap-6">
      {title(l.title)}
      {errors.length ? <ErrorSummary key={tries} errors={errors} headingLevel={(headingLevel + 1) as 2 | 3 | 4} /> : null}
      <form noValidate onSubmit={signIn} className="flex flex-col gap-4" aria-labelledby={ids.title}>
        <Field label={l.email} error={fieldError(ids.email)}>
          <Input id={ids.email} name="email" type="email" autoComplete="username" spellCheck={false} autoCapitalize="none" value={email} onChange={(e) => setEmail(e.target.value)} />
        </Field>
        <Field label={l.password} error={fieldError(ids.password)}>
          <PasswordInput id={ids.password} name="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} />
        </Field>
        <Link href={forgotHref} className="self-start text-sm">{l.forgot}</Link>
        <Button type="submit" loading={busy}>{l.signIn}</Button>
        {failure ? <p className="m-0 text-sm text-danger-text">{l.failed}</p> : null}
      </form>
    </Card>
  ) : step === 'code' ? (
    <Card as="section" aria-labelledby={ids.title} className="flex flex-col gap-6">
      {title(l.codeTitle)}
      <p className="m-0 text-sm text-text-muted">{l.codeSent}</p>
      <form noValidate onSubmit={confirm} className="flex flex-col gap-4" aria-labelledby={ids.title}>
        <Field label={l.code} error={codeError}>
          <PinInput id={ids.code} name="code" length={6} value={code} onValueChange={setCode} />
        </Field>
        <Button type="submit" loading={busy}>{l.verify}</Button>
        {failure ? <p className="m-0 text-sm text-danger-text">{l.failed}</p> : null}
        <div className="flex flex-col">
          <Button type="button" variant="ghost" loading={resending} onClick={resend}>{l.resend}</Button>
          {/* Always there, so a reader is listening before the first ask; a new keyed line is added for each answer.
              Empty, it takes no room, so the step looks the same until a code is asked for. */}
          <div role="status" className="text-sm text-text-muted">
            {sent ? <p key={sent} className={resendFailed ? 'm-0 mt-2 text-danger-text' : 'm-0 mt-2'}>{resendFailed ? l.resendFailed : l.resent}</p> : null}
          </div>
          <Button type="button" variant="ghost" onClick={() => { setCode(''); setCodeError(null); setSent(0); setFailure(false); setPassword(''); go('password'); }}>{l.back}</Button>
        </div>
      </form>
    </Card>
  ) : (
    <Card as="section" aria-labelledby={ids.title} className="flex flex-col gap-4">
      {title(l.doneTitle)}
      <Alert tone="success">{l.doneMessage}</Alert>
      {doneHref ? <Link href={doneHref} className="self-start">{l.doneLink}</Link> : null}
    </Card>
  );
}

files.CartSummary.tsx:
'use client';
import * as React from 'react';
import { Button } from '@diki-stwn/serupa-ds';
import { DescriptionItem, DescriptionList } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Image } from '@diki-stwn/serupa-ds';
import { Input, InputAction } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Loader } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { toast } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';

/* Cart summary (RU19): what's in the cart, with quantities, a coupon and the total, for an app to copy. What it
   carries (WCAG 2.2):
   - 1.3.1: a region named by its heading; the items are a list (role="list", since WebKit stops calling a list without
     bullets one), and the sums are a description list, each amount after its term.
   - 2.4.6 / 2.5.3: each quantity field and Remove button is named after its item ("Quantity, Linen shirt", "Remove
     Linen shirt"), starting with the words people see, so a list of them still says which is which.
   - 3.3.4 / 2.4.3: Remove takes the item away at once with Undo in a toast, instead of "Are you sure?"; it's removed
     for good only when the toast goes. Focus moves to the next item's name, or to the heading when none is left.
   - 4.1.3: a new total is said politely once it settles ("Total $112.50"), so a change of quantity or coupon is heard
     without moving focus. A coupon that doesn't apply says why in the field's error.
   - 4.1.3: while the cart loads, it says it's busy with one name ("Loading your cart"), and the total that arrives
     isn't said as a change; a failed load says so under the heading, with Try again (EmptyLoadFailed).
   - Amounts are written the way the reader's locale writes money. Each word is a label, English by default. */

export interface CartItem {
  id: string;
  name: string;
  /** The product's page: the name links to it. */
  href?: string | undefined;
  /** A small picture of it. It's decorative beside the name, so it needs no alt text. */
  image?: string | undefined;
  /** The price of one. */
  price: number;
  quantity: number;
  /** The most one order can take: stock, or a limit per customer. */
  max?: number | undefined;
}

export interface CartSummaryLabels {
  title: string;
  /** The price of one, under the name. */
  each: (price: string) => string;
  quantity: (name: string) => string;
  remove: string;
  /** The toast after Remove, with Undo. */
  removed: (name: string) => string;
  coupon: string;
  apply: string;
  /** The discount's term, with the code that gave it. */
  discount: (code: string) => string;
  removeCoupon: string;
  subtotal: string;
  /** The tax's term, with its rate as a percentage. */
  tax: (rate: string) => string;
  total: string;
  /** Said when the total changes. */
  totalIs: (total: string) => string;
  checkout: string;
  empty: string;
  continueShopping: string;
  /** The placeholder's one name while the cart loads. */
  loading: string;
  /** The failed load's title. */
  loadFailed: string;
}

const english: CartSummaryLabels = {
  title: 'Your cart',
  each: (price) => `${price} each`,
  quantity: (name) => `Quantity, ${name}`,
  remove: 'Remove',
  removed: (name) => `Removed ${name}`,
  coupon: 'Coupon code',
  apply: 'Apply',
  discount: (code) => `Discount (${code})`,
  removeCoupon: 'Remove coupon',
  subtotal: 'Subtotal',
  tax: (rate) => `Tax (${rate})`,
  total: 'Total',
  totalIs: (total) => `Total ${total}`,
  checkout: 'Check out',
  empty: 'Your cart is empty.',
  continueShopping: 'Continue shopping',
  loading: 'Loading your cart',
  loadFailed: 'Couldn’t load your cart',
};

export interface CartSummaryProps {
  items: readonly CartItem[];
  /** An ISO 4217 code: "USD", "IDR", "EUR". */
  currency: string;
  /** A quantity changed: update the item. */
  onQuantityChange: (itemId: string, quantity: number) => void;
  /** An item is removed for good: the Undo toast went without Undo, or the page was left. */
  onRemove: (itemId: string) => void;
  /** A coupon was applied: resolve with the discount, or reject with an Error whose message says why it doesn't apply. */
  onApplyCoupon?: ((code: string) => Promise<number>) | undefined;
  /** The tax rate, such as 0.11 for 11%. Without it there's no tax line. */
  taxRate?: number | undefined;
  onCheckout: () => void | Promise<unknown>;
  /** Where "Continue shopping" goes from an empty cart. Default: "/". */
  continueHref?: string | undefined;
  /** The heading's level. Default: 2. */
  headingLevel?: 2 | 3 | undefined;
  labels?: Partial<CartSummaryLabels> | undefined;
  /** The cart is on its way: a placeholder under the heading, named once ("Loading your cart"). Default: false. */
  loading?: boolean | undefined;
  /** The cart failed to load: a "Couldn’t load your cart" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

/** The cart: each item with its quantity and Remove (with Undo), a coupon, and the sums down to the total. */
export function CartSummary({ items, currency, onQuantityChange, onRemove, onApplyCoupon, taxRate, onCheckout, continueHref = '/', headingLevel = 2, labels,
  loading = false, loadFailed = false, onRetry }: CartSummaryProps) {
  const l = { ...english, ...labels };
  const locale = useLocale();
  const base = React.useId();
  const heading = React.useRef<HTMLHeadingElement>(null);
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(() => new Set());
  const [code, setCode] = React.useState('');
  const [coupon, setCoupon] = React.useState<{ code: string; amount: number } | null>(null);
  const [couponError, setCouponError] = React.useState<string | null>(null);
  const [applying, setApplying] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const money = (value: number) => formatNumber(value, locale, { format: 'currency', currency });
  const shown = items.filter((i) => !hidden.has(i.id));
  const subtotal = shown.reduce((sum, i) => sum + i.price * i.quantity, 0);
  const discount = coupon ? Math.min(coupon.amount, subtotal) : 0;
  const tax = taxRate ? Math.round((subtotal - discount) * taxRate * 100) / 100 : 0;
  const total = subtotal - discount + tax;

  // A new total is said once it settles, not at first and not for each step of a quantity held down. The total a
  // loaded cart arrives with is its first, not a change.
  const ready = !loading && !loadFailed;
  const said = React.useRef(total), wasReady = React.useRef(ready), totalSaid = l.totalIs(money(total));
  React.useEffect(() => {
    if (!ready) { wasReady.current = false; return; }
    if (!wasReady.current) { wasReady.current = true; said.current = total; return; }
    if (total === said.current) return;
    const t = window.setTimeout(() => { said.current = total; announce(totalSaid); }, 500);
    return () => window.clearTimeout(t);
  }, [total, totalSaid, ready]);

  const nameOf = (id: string) => document.getElementById(`${base}-${id}`);
  // The removals whose Undo is still up, by item: Check out removes them for good first, so the order leaves them out.
  const pending = React.useRef(new Map<string, string>());
  const latestCheckout = React.useRef(onCheckout);
  // every render: keeps the app's latest onCheckout, which Check out calls after the removals have rendered.
  React.useEffect(() => { latestCheckout.current = onCheckout; });
  const remove = (item: CartItem) => {
    const at = shown.indexOf(item), next = shown[at + 1] || shown[at - 1];
    setHidden((h) => new Set(h).add(item.id));
    // After the list renders without it: the next item's name, or the heading when the cart is empty.
    requestAnimationFrame(() => { (next ? nameOf(next.id) : heading.current)?.focus(); });
    pending.current.set(item.id, toast.undo({
      title: l.removed(item.name),
      // Gone for good: the app drops it, so it's no longer hidden here, and the same product added again shows.
      commit: () => { pending.current.delete(item.id); onRemove(item.id); setHidden((h) => { const n = new Set(h); n.delete(item.id); return n; }); },
      onUndo: () => { pending.current.delete(item.id); setHidden((h) => { const n = new Set(h); n.delete(item.id); return n; }); requestAnimationFrame(() => nameOf(item.id)?.focus()); },
    }));
  };
  const apply = async () => {
    const typed = code.trim();
    if (!typed || !onApplyCoupon) return;
    setApplying(true); setCouponError(null);
    try {
      setCoupon({ code: typed, amount: await onApplyCoupon(typed) });
      setCode('');
    } catch (e) {
      setCouponError(e instanceof Error ? e.message : String(e));
    } finally { setApplying(false); }
  };
  const checkout = async () => {
    setBusy(true);
    try {
      if (pending.current.size) {
        for (const id of [...pending.current.values()]) toast.dismiss(id);
        // Once the app has rendered without them, its onCheckout sees the cart as it now is.
        await new Promise((done) => setTimeout(done, 0));
      }
      await latestCheckout.current();
    } finally { setBusy(false); }
  };

  return (
    <section aria-labelledby={`${base}-title`} aria-busy={loading && !loadFailed ? true : undefined} className="flex flex-col gap-4">
      <Heading level={headingLevel} size="lg" id={`${base}-title`} ref={heading} tabIndex={-1} className="outline-none">{l.title}</Heading>
      {loadFailed ? <EmptyLoadFailed title={l.loadFailed} onRetry={() => onRetry?.()} headingLevel={headingLevel === 2 ? 3 : 4} />
        : loading ? <Loader variant="skeleton" shape="text" lines={4} label={l.loading} />
        : shown.length ? <>
        <ul role="list" className="m-0 flex list-none flex-col p-0">
          {shown.map((item) => (
            <li key={item.id} className="flex flex-wrap items-center gap-3 border-b border-border py-3">
              {item.image ? <Image src={item.image} alt="" ratio="square" rounded frameProps={{ className: 'w-16 shrink-0' }} /> : null}
              <div className="flex min-w-0 flex-auto basis-40 flex-col gap-1 wrap-anywhere">
                {item.href
                  ? <Link href={item.href} id={`${base}-${item.id}`} className="font-semibold">{item.name}</Link>
                  : <span id={`${base}-${item.id}`} tabIndex={-1} className="font-semibold outline-none">{item.name}</span>}
                <span className="text-sm text-text-muted">{l.each(money(item.price))}</span>
              </div>
              <div className="flex items-center gap-2">
                <NumberInput className="w-32" size="sm" aria-label={l.quantity(item.name)} value={item.quantity} min={1} max={item.max}
                  onValueChange={(v) => { if (v != null && v >= 1 && v !== item.quantity) onQuantityChange(item.id, v); }} />
                <Button variant="ghost" size="sm" aria-label={`${l.remove} ${item.name}`} onClick={() => remove(item)}>{l.remove}</Button>
              </div>
              <span className="ms-auto font-semibold tabular-nums">{money(item.price * item.quantity)}</span>
            </li>
          ))}
        </ul>
        {onApplyCoupon ? (
          <form className="m-0" onSubmit={(e) => { e.preventDefault(); void apply(); }}>
            <Field label={l.coupon} error={couponError}>
              <Input value={code} onChange={(e) => { setCode(e.target.value); setCouponError(null); }} autoComplete="off" autoCapitalize="characters"
                actions={<InputAction type="submit" label={l.apply} disabled={applying || !code.trim()} />} />
            </Field>
          </form>
        ) : null}
        <DescriptionList layout="split" className="gap-1 border-t border-border pt-3 text-sm">
          <DescriptionItem term={l.subtotal}>{money(subtotal)}</DescriptionItem>
          {coupon ? (
            <DescriptionItem term={l.discount(coupon.code)}>
              <span className="flex flex-wrap items-center justify-end gap-2">
                −{money(discount)}
                <Button variant="link" size="sm" onClick={() => { setCoupon(null); requestAnimationFrame(() => document.getElementById(`${base}-title`)?.focus()); }}>{l.removeCoupon}</Button>
              </span>
            </DescriptionItem>
          ) : null}
          {taxRate ? <DescriptionItem term={l.tax(formatNumber(taxRate, locale, { format: 'percent', maximumFractionDigits: 2 }))}>{money(tax)}</DescriptionItem> : null}
          <DescriptionItem term={l.total} emphasis>{money(total)}</DescriptionItem>
        </DescriptionList>
        <Button className="w-full" loading={busy} onClick={() => void checkout()}>{l.checkout}</Button>
      </> : (
        <div className="flex flex-col items-start gap-2"><p className="m-0">{l.empty}</p><Link href={continueHref}>{l.continueShopping}</Link></div>
      )}
    </section>
  );
}

files.EmptyStates.tsx:
'use client';
import * as React from 'react';
import { Button } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';

/* Empty states (BL5): the four empties most apps need, each with its next step, built from EmptyState only, for an app
   to copy. What they carry (WCAG 2.2):
   - 3.3.3 / 2.4.6: each says what happened in words and offers the way out as a real button or link, not only a
     picture.
   - 4.1.3: the ones that appear after something the person did (no results, failed to load) are said once,
     politely; the first-run and no-access ones are on the page when it arrives, so they aren't.
   - 2.2.1 / 3.2.2: nothing retries or requests on its own; the person presses the button.
   - Each takes its words as props, English by default, so a page in another language passes its own. */

export interface EmptyFirstRunProps {
  /** "No projects yet". */
  title?: string | undefined;
  /** What it's for, and what the first step is. */
  description?: string | undefined;
  /** The first step's button: "New project". */
  createLabel: string;
  onCreate: () => void;
  /** A guide for people who want to read first. */
  learnHref?: string | undefined;
  /** The guide link's words. Default: "How it works". */
  learnLabel?: string | undefined;
  headingLevel?: 2 | 3 | 4 | undefined;
}

/** The first visit: nothing made yet, and the one button that makes the first. */
export function EmptyFirstRun({ title = 'Nothing here yet', description, createLabel, onCreate, learnHref, learnLabel = 'How it works', headingLevel }: EmptyFirstRunProps) {
  return (
    <EmptyState icon="add_circle" title={title} description={description} headingLevel={headingLevel}
      actions={<><Button onClick={onCreate}>{createLabel}</Button>{learnHref ? <Link href={learnHref}>{learnLabel}</Link> : null}</>} />
  );
}

export interface EmptyNoResultsProps {
  /** What was searched for. Shown in the title: No results for “mars”. */
  query: string;
  /** The title, from the query. Default: No results for “query”. */
  title?: ((query: string) => string) | undefined;
  /** Default: "Check the spelling, or try fewer words." */
  description?: string | undefined;
  /** Other searches to try, such as a spelling fix. */
  suggestions?: string[] | undefined;
  onSuggestion?: ((suggestion: string) => void) | undefined;
  /** Adds Clear filters, the usual way out. */
  onClearFilters?: (() => void) | undefined;
  headingLevel?: 2 | 3 | 4 | undefined;
}

/** A search or filter that found nothing: the query in the title, searches to try, and Clear filters. Said once. */
export function EmptyNoResults({ query, title = (q) => `No results for “${q}”`, description = 'Check the spelling, or try fewer words.', suggestions, onSuggestion, onClearFilters, headingLevel }: EmptyNoResultsProps) {
  return (
    <EmptyState icon="search_off" announce title={title(query)} description={description} headingLevel={headingLevel}
      suggestions={suggestions} onSuggestion={onSuggestion} onClearFilters={onClearFilters} />
  );
}

export interface EmptyNoAccessProps {
  /** Default: "You don’t have access". */
  title?: string | undefined;
  /** Who can give access, in a sentence: "Ana Putri owns this project. Ask them, or request access here." */
  description: string;
  /** Sends the request. Return a promise: the button then shows it's working, and requestedLabel once it's sent. */
  onRequest?: (() => Promise<unknown>) | undefined;
  /** Default: "Request access". */
  requestLabel?: string | undefined;
  /** Said and shown on the button once the request is sent. Default: "Request sent". */
  requestedLabel?: string | undefined;
  /** Said and shown under the description when onRequest rejects; the button can be pressed again.
      Default: "Couldn’t send the request. Try again." */
  requestFailedLabel?: string | undefined;
  /** Where to go instead: the list this page belongs to. */
  backHref?: string | undefined;
  /** Default: "Go back". */
  backLabel?: string | undefined;
  headingLevel?: 2 | 3 | 4 | undefined;
}

/** A page the person can't see: who can let them in, Request access, and a way back. */
export function EmptyNoAccess({ title = 'You don’t have access', description, onRequest, requestLabel = 'Request access', requestedLabel = 'Request sent', requestFailedLabel = 'Couldn’t send the request. Try again.', backHref, backLabel = 'Go back', headingLevel }: EmptyNoAccessProps) {
  // Once sent, the button keeps saying so and does nothing more, so one person can't send the same request twice.
  // It stays focusable (aria-disabled, not disabled), so focus isn't lost from under the keyboard.
  // A request that fails says so, in words under the description and once to a screen reader, and the button stays
  // Request access, so it can be pressed again (GR136). Nothing is said as sent unless onRequest resolved.
  const [sent, setSent] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const request = onRequest ? async () => {
    if (sent) return;
    setFailed(false);
    try { await onRequest(); } catch { setFailed(true); announce(requestFailedLabel); return; }
    setSent(true);
    announce(requestedLabel);
  } : undefined;
  return (
    <EmptyState icon="lock" title={title} headingLevel={headingLevel}
      description={failed ? <>{description}<br /><span className="text-danger-text">{requestFailedLabel}</span></> : description}
      actions={<>{request ? <Button onClick={request} aria-disabled={sent || undefined}>{sent ? requestedLabel : requestLabel}</Button> : null}{backHref ? <Link href={backHref}>{backLabel}</Link> : null}</>} />
  );
}

export interface EmptyLoadFailedProps {
  /** Default: "Couldn’t load this". */
  title?: string | undefined;
  /** What happened and what to do. Default: "Check your connection, then try again." */
  description?: string | undefined;
  /** Loads again. Return a promise: the button shows it's working until it settles. */
  onRetry: () => Promise<unknown> | void;
  /** Default: "Try again". */
  retryLabel?: string | undefined;
  /** A code to give support, shown under the description: "Reference: 7F3A-91". */
  reference?: string | undefined;
  /** The words before the code. Default: "Reference". */
  referenceLabel?: string | undefined;
  headingLevel?: 2 | 3 | 4 | undefined;
}

/** Loading failed: what to do, Try again, and a reference for support. Said once. */
export function EmptyLoadFailed({ title = 'Couldn’t load this', description = 'Check your connection, then try again.', onRetry, retryLabel = 'Try again', reference, referenceLabel = 'Reference', headingLevel }: EmptyLoadFailedProps) {
  return (
    <EmptyState icon="cloud_off" announce title={title} headingLevel={headingLevel}
      description={reference ? <>{description}<br />{referenceLabel}: <span className="font-mono">{reference}</span></> : description}
      actions={<Button onClick={onRetry}>{retryLabel}</Button>} />
  );
}

