'use client';
import * as React from 'react';
import { Accordion, AccordionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Highlight, highlightRanges } from '@diki-stwn/serupa-ds';
import { SearchInput } from '@diki-stwn/serupa-ds';

/* FAQ (RU17): questions and answers in groups, for an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the FAQ is a region named by its heading; each group has its own heading, and each question is a heading
     holding a button (Accordion), so a screen reader can list and jump between them.
   - Find-in-page reaches closed answers: they are hidden="until-found", and a match opens its question (Accordion).
   - 4.1.3: the search field filters the questions, and how many match is said politely (role="status").
     The words that matched are marked in each question (Highlight), so they show without color alone (1.4.1).
   - 2.4.3: a link to a question (#its-id, from a help article or a support reply) opens it and moves focus to it.
   - 3.3.5: "Still stuck?" is always there, after the questions and in the no-match text, so help is never a dead end.
   - Each word is a prop or a label, English by default. */

export interface FaqQuestion {
  /** Its id in the page: a link to #id opens it. Letters, digits and dashes: "cancel-plan". */
  id: string;
  /** The question, as people ask it: "How do I cancel my plan?". */
  question: string;
  /** The answer: text, or your own markup (paragraphs, a list, links). */
  answer: React.ReactNode;
  /** More words the search finds this question by, when the answer isn't plain text or people use other words:
      "refund money back". */
  keywords?: string | undefined;
}

export interface FaqGroup {
  id: string;
  /** The group's heading: "Billing". Leave it out when there's one group. */
  title?: string | undefined;
  questions: readonly FaqQuestion[];
}

/** The words Faq says. Pass your own for a page in another language. */
export interface FaqLabels {
  /** The FAQ's heading. */
  title: string;
  /** The search field's label. */
  search: string;
  /** How many questions match, said and shown while searching: "3 of 12 questions". */
  results: (shown: number, total: number) => string;
  /** Shown when nothing matches. */
  noMatch: (query: string) => string;
  /** The heading over the contact part. */
  stuck: string;
}
const EN: FaqLabels = {
  title: 'Frequently asked questions',
  search: 'Search the questions',
  results: (shown, total) => `${shown} of ${total} ${total === 1 ? 'question' : 'questions'}`,
  noMatch: (query) => `No questions match “${query}”. Try other words, or ask us.`,
  stuck: 'Still stuck?',
};

export interface FaqProps {
  groups: readonly FaqGroup[];
  /** The FAQ's heading level, to fit the page. Groups and questions take the next levels. Default: 2. */
  headingLevel?: 2 | 3 | undefined;
  /** Shows the search field. Default: true when there are more than 6 questions. */
  searchable?: boolean | undefined;
  /** How to reach a person, under "Still stuck?": a sentence and a Button or Link. Leave it out only when the
      page already says how, next to the FAQ. */
  contact?: React.ReactNode;
  /** The questions open at first, by id. A link to #id opens one too. Default: none. */
  defaultOpen?: readonly string[] | undefined;
  /** The search at first: from the page's address (?q=), or a help search people came from. Default: ''. */
  defaultQuery?: string | undefined;
  /** Its words, in the page's language. Each one left out stays English. */
  labels?: Partial<FaqLabels> | undefined;
}

const text = (q: FaqQuestion) => [q.question, typeof q.answer === 'string' ? q.answer : '', q.keywords || ''].join(' ');
const terms = (query: string) => query.split(/\s+/).filter(Boolean);
// Every word of the search is somewhere in the question, its answer or its keywords; case and accents don't count.
const matches = (q: FaqQuestion, query: string) => terms(query).every((t) => highlightRanges(text(q), t).length > 0);

/** Questions and answers in groups: find-in-page reaches closed answers, a search filters them, a link opens one,
    and "Still stuck?" is always there. */
export function Faq({ groups, headingLevel = 2, searchable, contact, defaultOpen, defaultQuery = '', labels }: FaqProps) {
  const w = { ...EN, ...labels };
  const id = React.useId();
  const all = groups.flatMap((g) => g.questions);
  const [open, setOpen] = React.useState<string[]>(() => (defaultOpen ? defaultOpen.slice() : []));
  const [query, setQuery] = React.useState(defaultQuery);
  const q = query.trim();
  const shown = groups.map((g) => ({ ...g, questions: g.questions.filter((x) => matches(x, q)) })).filter((g) => g.questions.length);
  const count = shown.reduce((n, g) => n + g.questions.length, 0);
  // A link to #question-id opens that question and moves focus to its button, on load and on a later hash change.
  const root = React.useRef<HTMLElement>(null);
  const ids = all.map((x) => x.id).join(' ');
  React.useEffect(() => {
    const go = () => {
      const target = decodeURIComponent(window.location.hash.slice(1));
      if (!target || ids.split(' ').indexOf(target) < 0) return;
      setQuery('');
      setOpen((o) => (o.indexOf(target) >= 0 ? o : o.concat(target)));
      requestAnimationFrame(() => {
        const button = root.current?.querySelector<HTMLButtonElement>(`[id="${CSS.escape(target)}"] button[aria-expanded]`);
        if (button) { button.focus({ preventScroll: true }); button.scrollIntoView({ block: 'start' }); }
      });
    };
    go();
    window.addEventListener('hashchange', go);
    return () => window.removeEventListener('hashchange', go);
  }, [ids]);
  const level = headingLevel + 1 as 3 | 4;
  const titled = groups.some((g) => g.title);
  const stuck = contact ? (
    <section aria-labelledby={id + '-stuck'} className="flex flex-col gap-2 border-t border-border pt-6">
      <Heading level={level} size="base" id={id + '-stuck'}>{w.stuck}</Heading>
      <div className="flex flex-col items-start gap-3 text-sm text-text-muted">{contact}</div>
    </section>
  ) : null;
  return (
    <section ref={root} aria-labelledby={id} className="flex flex-col gap-6">
      <Heading level={headingLevel} id={id}>{w.title}</Heading>
      {(searchable ?? all.length > 6) ? (
        <div className="flex flex-col gap-2">
          <Field label={w.search}>
            <SearchInput value={query} onChange={(e) => setQuery(e.target.value)} />
          </Field>
          <p role="status" className="m-0 text-sm text-text-muted">{q ? w.results(count, all.length) : ''}</p>
        </div>
      ) : null}
      {count === 0 ? <p className="m-0">{w.noMatch(q)}</p> : shown.map((g) => (
        <div key={g.id} className="flex flex-col gap-2">
          {g.title ? <Heading level={level} size="lg" id={`${id}-${g.id}`}>{g.title}</Heading> : null}
          <Accordion type="multiple" value={open} onValueChange={setOpen} headingLevel={titled ? (level + 1) as 4 | 5 : level}>
            {g.questions.map((x) => (
              <AccordionItem key={x.id} id={x.id} value={x.id} title={<Highlight query={terms(q)} words>{x.question}</Highlight>}>
                {typeof x.answer === 'string' ? <p className="m-0">{x.answer}</p> : x.answer}
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      ))}
      {stuck}
    </section>
  );
}

files.Footer.tsx:
'use client';
import * as React from 'react';
import { Button } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';

/* Footer (BL10): the site's footer, for an app to copy. What it carries (WCAG 2.2):
   - 1.3.1 / 2.4.1: a <footer> (the page's contentinfo landmark) with each link group as a navigation landmark named
     by its visible heading, so "Product" and "Company" are told apart in a list of landmarks.
   - 3.1.2: each language is written in itself, marked with its lang, so a screen reader says "Bahasa Indonesia" the
     Indonesian way.
   - 3.2.2: picking a language changes nothing until the person presses Change (a new language is a new page);
     picking a theme only changes how the page looks, so it applies at once.
   - 1.3.1 / 3.3.2: both pickers have visible labels. Each word is a prop or a label, English by default. */

export interface FooterLinkGroup {
  /** The group's heading, which names its navigation landmark: "Product". */
  title: string;
  links: readonly { label: string; href: string }[];
}

export interface FooterLanguage {
  /** What onLanguageChange gets: "id". */
  value: string;
  /** The language's name in itself: "Bahasa Indonesia". */
  label: string;
  /** Its BCP 47 tag, so the name is said in its own language. Default: value. */
  lang?: string | undefined;
}

export interface FooterLabels {
  language: string;
  changeLanguage: string;
  theme: string;
  /** The theme picker's choices, in order, when `themes` isn't given. */
  system: string;
  light: string;
  dark: string;
}

const english: FooterLabels = { language: 'Language', changeLanguage: 'Change', theme: 'Theme', system: 'Match my device', light: 'Light', dark: 'Dark' };

export interface FooterProps {
  groups: readonly FooterLinkGroup[];
  /** The languages the site is in. With fewer than two, there's no language picker. */
  languages?: readonly FooterLanguage[] | undefined;
  /** The page's language now. */
  language?: string | undefined;
  /** Change was pressed with a different language picked. */
  onLanguageChange?: ((value: string) => void) | undefined;
  /** The theme now: 'system', 'light' or 'dark', or one of your `themes`. Without onThemeChange, there's no theme picker. */
  theme?: string | undefined;
  onThemeChange?: ((value: string) => void) | undefined;
  /** Your own themes, in place of Match my device, Light and Dark. */
  themes?: readonly { value: string; label: string }[] | undefined;
  /** The legal line: "© 2026 Acme, Inc.", and links to terms and privacy. */
  legal: React.ReactNode;
  /** The groups' headings. Default: 2. */
  headingLevel?: 2 | 3 | 4 | undefined;
  labels?: Partial<FooterLabels> | undefined;
}

/** The site's footer: link groups as named navigation, language and theme pickers, and the legal line. */
export function Footer({ groups, languages = [], language, onLanguageChange, theme = 'system', onThemeChange, themes, legal, headingLevel = 2, labels }: FooterProps) {
  const l = { ...english, ...labels };
  const id = React.useId();
  const [picked, setPicked] = React.useState(language ?? languages[0]?.value ?? '');
  // The page's language changed (Change was pressed, or the app moved on): the picker shows it. Set while rendering,
  // React's way to follow a prop, so there's no render with the old choice.
  const [was, setWas] = React.useState(language);
  if (language !== was) { setWas(language); if (language != null) setPicked(language); }
  const choices = themes ?? [{ value: 'system', label: l.system }, { value: 'light', label: l.light }, { value: 'dark', label: l.dark }];
  const changeLanguage = (e: React.FormEvent) => { e.preventDefault(); if (picked !== language) onLanguageChange?.(picked); };
  return (
    <footer className="border-t border-border bg-surface text-text">
      <div className="mx-auto flex max-w-5xl flex-col gap-8 px-4 py-10">
        <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 md:grid-cols-4">
          {groups.map((g, i) => (
            <nav key={g.title} aria-labelledby={`${id}-${i}`} className="flex flex-col gap-3">
              <Heading level={headingLevel} id={`${id}-${i}`} size="sm" className="font-semibold">{g.title}</Heading>
              <ul className="m-0 flex list-none flex-col gap-2 p-0 text-sm">
                {g.links.map((link) => <li key={link.href + link.label}><Link href={link.href}>{link.label}</Link></li>)}
              </ul>
            </nav>
          ))}
        </div>
        {(languages.length > 1 && onLanguageChange) || onThemeChange ? (
          <div className="flex flex-col gap-4 sm:flex-row sm:items-end">
            {languages.length > 1 && onLanguageChange ? (
              <form onSubmit={changeLanguage} className="flex items-end gap-2">
                <Field label={l.language}>
                  <Select value={picked} onChange={(e) => setPicked(e.target.value)}>
                    {languages.map((x) => <option key={x.value} value={x.value} lang={x.lang ?? x.value}>{x.label}</option>)}
                  </Select>
                </Field>
                <Button type="submit" variant="outline">{l.changeLanguage}</Button>
              </form>
            ) : null}
            {onThemeChange ? (
              <Field label={l.theme}>
                <Select value={theme} options={choices.map((c) => ({ value: c.value, label: c.label }))} onChange={(e) => onThemeChange(e.target.value)} />
              </Field>
            ) : null}
          </div>
        ) : null}
        <div className="border-t border-border pt-6 text-sm text-text-muted">{legal}</div>
      </div>
    </footer>
  );
}

files.PageHeader.tsx:
'use client';
import * as React from 'react';
import { Breadcrumb, BreadcrumbItem } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { IconButton } from '@diki-stwn/serupa-ds';
import { Menu, MenuItem } from '@diki-stwn/serupa-ds';
import { TabNav, TabNavLink } from '@diki-stwn/serupa-ds';

/* Page header (BL1): the top of a page inside an app, built from the components only, for an app to copy.
   What it carries (WCAG 2.2):
   - 2.4.8 and 2.4.4: a Breadcrumb says where the page sits; its last item is the page itself (aria-current="page").
   - 1.3.1 and 2.4.6: the title is the page's one h1; the description is plain text under it, not a heading.
   - 2.4.3: actions come after the title in the reading and Tab order, the primary one first.
   - 1.4.10 reflow: on a phone the secondary actions move into a "More actions" Menu, so nothing is cut off or
     scrolls sideways at 320px; the primary action stays a button you can see.
   - 2.4.1 and 4.1.2: the section links are a TabNav, a nav landmark with its own name, and the current one says so
     (aria-current="page"), not by color alone: it has the tab line under it. */

export interface PageHeaderAction {
  /** What the button says. */
  label: string;
  /** What it does. */
  onSelect?: () => void;
  /** Or where it goes. */
  href?: string;
  /** An icon before the label: an icon name or any element. */
  icon?: React.ComponentProps<typeof Button>['leftIcon'];
  /** Can't be used now (nothing to do): the button, or the menu item on a phone, says so. */
  disabled?: boolean;
}
export interface PageHeaderSection {
  label: string;
  href: string;
  /** The section this page is. */
  current?: boolean;
}
export interface PageHeaderProps {
  /** The way here, from the top: each with an href, except the page itself last. */
  breadcrumb?: { label: string; href?: string }[];
  /** The page's name: its h1. */
  title: string;
  /** A sentence on what the page is for. */
  description?: React.ReactNode;
  /** The one main action, always shown. */
  primary?: PageHeaderAction;
  /** Other actions: buttons beside the primary one, or a "More actions" menu on a phone. */
  secondary?: PageHeaderAction[];
  /** Links to the page's sections (Overview, Activity, Settings), as a named nav under the title. */
  sections?: PageHeaderSection[];
  /** The sections nav's name, for a screen reader's landmark list. Default: "Sections". */
  sectionsLabel?: string;
  /** The phone menu's name, in the page's language. Default: "More actions". */
  moreLabel?: string | undefined;
  /** A ref to the h1. With it, the h1 can take focus from a script (tabIndex -1), for a page that moves focus to its
      title after an action takes away the button that had it. */
  headingRef?: React.Ref<HTMLHeadingElement> | undefined;
}

const button = (a: PageHeaderAction, variant: 'primary' | 'secondary') =>
  a.href && !a.disabled ? <Button key={a.label} href={a.href} variant={variant} leftIcon={a.icon}>{a.label}</Button>
    : <Button key={a.label} variant={variant} leftIcon={a.icon} disabled={a.disabled} onClick={a.onSelect}>{a.label}</Button>;

/** The top of a page: where it is, what it's called, what it's for, and what you can do there. */
export function PageHeader({ breadcrumb, title, description, primary, secondary = [], sections, sectionsLabel = 'Sections', moreLabel = 'More actions', headingRef }: PageHeaderProps) {
  return (
    // With sections, the tab row's own line is the header's bottom edge, so the two don't draw one line twice.
    <div className={sections?.length ? 'flex flex-col gap-4' : 'flex flex-col gap-4 border-b border-border pb-4'}>
      {breadcrumb?.length ? (
        <Breadcrumb>
          {breadcrumb.map((b, i) => <BreadcrumbItem key={b.label} href={i < breadcrumb.length - 1 ? b.href : undefined}>{b.label}</BreadcrumbItem>)}
        </Breadcrumb>
      ) : null}
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="flex min-w-0 flex-col gap-1">
          {headingRef ? <Heading level={1} ref={headingRef} tabIndex={-1} className="outline-none">{title}</Heading> : <Heading level={1}>{title}</Heading>}
          {description != null ? <p className="m-0 max-w-prose text-text-muted">{description}</p> : null}
        </div>
        {primary || secondary.length ? (
          <div className="flex flex-wrap items-center gap-2">
            {primary ? button(primary, 'primary') : null}
            {secondary.length ? (
              <>
                <div className="hidden flex-wrap gap-2 sm:flex">{secondary.map((a) => button(a, 'secondary'))}</div>
                <div className="sm:hidden">
                  <Menu placement="bottom-end" trigger={<IconButton variant="secondary" icon="more_horiz" label={moreLabel} hideTitle />}>
                    {secondary.map((a) => <MenuItem key={a.label} href={a.disabled ? undefined : a.href} icon={a.icon} disabled={a.disabled} onSelect={a.onSelect}>{a.label}</MenuItem>)}
                  </Menu>
                </div>
              </>
            ) : null}
          </div>
        ) : null}
      </div>
      {sections?.length ? (
        <TabNav aria-label={sectionsLabel}>
          {sections.map((s) => <TabNavLink key={s.href} href={s.href} current={s.current}>{s.label}</TabNavLink>)}
        </TabNav>
      ) : null}
    </div>
  );
}

files.Pricing.tsx:
'use client';
import * as React from 'react';
import { Badge } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Icon } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { SegmentedControl } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';

/* Pricing (BL6): plans side by side, for an app to copy. What it carries (WCAG 2.2):
   - 1.3.1 in Safari: role="list" on the lists without bullets, since WebKit stops calling them lists (FU1, GR151).
   - 1.3.1: the plans are a list, each plan's name is a heading, and what a plan includes is a real list named after it.
   - 1.4.1 / 1.3.3: the current plan and the recommended one say so in words, not only with a color or a border.
   - 2.4.6 / 2.5.3: each plan has one action, named after the plan ("Choose Pro"), so a list of buttons still makes
     sense out of context.
   - Monthly or yearly is a radio group (SegmentedControl, one choice); the yearly option says the saving in words.
   - 1.4.10: a long word, such as a German compound, wraps inside its card rather than running out of it (GR137).
   - Ethical design: under the plans, a line says paid plans renew until cancelled and links to where to cancel, before
     anyone chooses ("Say when a plan renews and what it will cost before someone chooses it, and how to cancel").
   - Prices are written the way the reader's locale writes money. Each word is a label, English by default. */

export type PricingPeriod = 'monthly' | 'yearly';

export interface PricingPlan {
  id: string;
  /** "Pro". */
  name: string;
  /** Who it's for, in a sentence. */
  description?: string | undefined;
  /** The price of one month, billed monthly. */
  monthly: number;
  /** The price of one year, billed yearly. */
  yearly: number;
  /** What it includes, one line each. */
  features: readonly string[];
  /** The person is on this plan now: it says so instead of offering a button. */
  current?: boolean | undefined;
  /** The plan most people should pick: marked in words. */
  recommended?: boolean | undefined;
}

export interface PricingLabels {
  /** The radio group's name. */
  period: string;
  monthly: string;
  /** The yearly option. savingPercent is the biggest saving yearly billing gives across the plans, rounded down (0
      for none); upTo is true when the plans save different amounts, so the words must say "up to" (GR138). */
  yearly: (savingPercent: number, upTo: boolean) => string;
  perMonth: string;
  /** Under a yearly price per month: what is paid once a year. */
  billedYearly: (total: string) => string;
  current: string;
  recommended: string;
  /** The name of a plan's list of what it includes. */
  included: (plan: string) => string;
  /** A plan's button. */
  choose: (plan: string) => string;
  /** Under the plans: that paid plans renew, every month or every year, until cancelled. */
  renews: (period: PricingPeriod) => string;
  /** The link to where a plan is cancelled, after the renews line. */
  cancel: string;
}

const english: PricingLabels = {
  period: 'Billing period',
  monthly: 'Monthly',
  yearly: (saving, upTo) => (saving > 0 ? `Yearly, save ${upTo ? 'up to ' : ''}${saving}%` : 'Yearly'),
  perMonth: 'per month',
  billedYearly: (total) => `${total} billed yearly`,
  current: 'Your current plan',
  recommended: 'Recommended',
  included: (plan) => `Included in ${plan}`,
  choose: (plan) => `Choose ${plan}`,
  renews: (period) => `Paid plans renew every ${period === 'yearly' ? 'year' : 'month'} at the price shown until you cancel.`,
  cancel: 'Cancel any time in Billing settings',
};

export interface PricingProps {
  plans: readonly PricingPlan[];
  /** An ISO 4217 code: "USD", "IDR", "EUR". */
  currency: string;
  /** The period shown, when the page holds it. */
  period?: PricingPeriod | undefined;
  /** The period shown first, when Pricing holds it. Default: monthly. */
  defaultPeriod?: PricingPeriod | undefined;
  onPeriodChange?: ((period: PricingPeriod) => void) | undefined;
  /** A plan's button was pressed. */
  onChoose: (planId: string, period: PricingPeriod) => void | Promise<unknown>;
  /** Each plan's name. Default: 3, under the page's h2. */
  headingLevel?: 2 | 3 | 4 | undefined;
  labels?: Partial<PricingLabels> | undefined;
  /** Where a plan is cancelled, linked under the plans. Default: "#settings-billing". */
  cancelHref?: string | undefined;
}

/** What yearly billing saves over twelve monthly payments, per paid plan, as whole percentages rounded down. */
function savings(plans: readonly PricingPlan[]) {
  // toFixed: 96 of 120 is 20%, not 19.99…%
  return plans.filter((p) => p.monthly > 0).map((p) => Math.max(0, Math.floor(Number(((1 - p.yearly / (p.monthly * 12)) * 100).toFixed(6)))));
}

/** Plans side by side, monthly or yearly, each with what it includes and one clear action. */
export function Pricing({ plans, currency, period, defaultPeriod = 'monthly', onPeriodChange, onChoose, headingLevel = 3, labels, cancelHref = '#settings-billing' }: PricingProps) {
  const l = { ...english, ...labels };
  const locale = useLocale();
  const [own, setOwn] = React.useState<PricingPeriod>(defaultPeriod);
  const shown = period ?? own;
  const uid = React.useId();   // the cards' ids are this block's own: a page can show the same plans twice
  // A whole amount without its cents ("$12", not "$12.00"); anything else as the currency writes it.
  const money = (value: number) => formatNumber(value, locale, { format: 'currency', currency, ...(Number.isInteger(value) && { minimumFractionDigits: 0, maximumFractionDigits: 0 }) });
  const saved = savings(plans), best = Math.max(0, ...saved);
  const change = (next: PricingPeriod) => { setOwn(next); onPeriodChange?.(next); };
  return (
    <div className="flex flex-col gap-6">
      <SegmentedControl<PricingPeriod> aria-label={l.period} value={shown} onValueChange={change} className="self-center"
        options={[{ value: 'monthly', label: l.monthly }, { value: 'yearly', label: l.yearly(best, saved.some((x) => x !== best)) }]} />
      <ul role="list" className="m-0 grid list-none grid-cols-1 gap-4 p-0 md:grid-cols-3">
        {plans.map((plan) => {
          const perMonth = shown === 'yearly' ? plan.yearly / 12 : plan.monthly;
          return (
            <Card as="li" key={plan.id} padding="lg" variant={plan.recommended ? 'elevated' : 'outline'} aria-labelledby={`${uid}-${plan.id}-name`}
              className={plan.recommended ? 'flex h-full min-w-0 flex-col gap-4 wrap-anywhere border-primary' : 'flex h-full min-w-0 flex-col gap-4 wrap-anywhere'}>
              <div className="flex flex-wrap items-center gap-2">
                <Heading level={headingLevel} id={`${uid}-${plan.id}-name`}>{plan.name}</Heading>
                {plan.recommended && <Badge tone="primary">{l.recommended}</Badge>}
              </div>
              {plan.description && <p className="text-sm text-text-muted">{plan.description}</p>}
              <p className="flex flex-wrap items-baseline gap-x-2">
                <span className="text-3xl font-semibold">{money(perMonth)}</span>
                <span className="text-sm text-text-muted">{l.perMonth}</span>
                {shown === 'yearly' && plan.yearly > 0 && <span className="w-full text-sm text-text-muted">{l.billedYearly(money(plan.yearly))}</span>}
              </p>
              <ul role="list" aria-label={l.included(plan.name)} className="m-0 flex list-none flex-col gap-2 p-0 text-sm">
                {plan.features.map((f) => <li key={f} className="flex items-center gap-2"><Icon name="check" className="shrink-0 text-success" />{f}</li>)}
              </ul>
              <div className="mt-auto">
                {plan.current
                  ? <p className="text-sm font-semibold">{l.current}</p>
                  : <Button className="w-full" variant={plan.recommended ? 'primary' : 'secondary'} onClick={() => onChoose(plan.id, shown)}>{l.choose(plan.name)}</Button>}
              </div>
            </Card>
          );
        })}
      </ul>
      {plans.some((p) => p.monthly > 0 || p.yearly > 0) && (
        <p className="text-center text-sm text-text-muted">{l.renews(shown)} <Link href={cancelHref}>{l.cancel}</Link>.</p>
      )}
    </div>
  );
}

